from dataclasses import dataclass


@dataclass
class Profile:
    username: str
    age: int | None = None
    email: str | None = None
    phone: str | None = None
    biography: str | None = None


def categorize_age(
    age: int | None,
) -> str | None:
    if age is None or age < 0:
        return None
    if age < 13:
        return "child"
    if age < 20:
        return "teen"
    if age < 65:
        return "adult"
    return "senior"


def email_domain(
    email: str | None,
) -> str | None:
    if email is None:
        return None
    parts = email.split("@")
    if len(parts) != 2 or not parts[0] or "." not in parts[1]:
        return None
    return parts[1].lower()


def format_phone(
    phone: str | None,
) -> str | None:
    if phone is None:
        return None
    digits = "".join(ch for ch in phone if ch.isdigit())
    if len(digits) != 10:
        return None
    return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"


def is_short_bio(biography: str | None) -> bool:
    if biography is None:
        return True
    return len(biography.strip()) < 40


def describe(profile: Profile) -> str:
    domain = email_domain(profile.email)
    group = categorize_age(profile.age)
    phone = format_phone(profile.phone)
    pieces = [profile.username, group or "age unknown", domain or "no domain"]
    if phone is not None:
        pieces.append(phone)
    if is_short_bio(profile.biography):
        pieces.append("bio needs work")
    return " | ".join(pieces)


def validate(profiles):
    complete = []
    for row in profiles:
        profile = Profile(*row)
        if email_domain(profile.email) and categorize_age(profile.age):
            complete.append(profile.username)
    return complete


def main() -> None:
    raw = [
        ("alice", 20, "alice@example.com", None, None),
        ("bob", None, "bob@mail.org", "555-123-4567", "Loves hiking."),
        ("carol", 42, None, "5559876543", "x" * 60),
    ]
    print(validate(raw))
    for row in raw:
        print(describe(Profile(*row)))


if __name__ == "__main__":
    main()

