from __future__ import annotations


class Node:
    def __init__(self, value: int):
        self.value: int = value
        self.left: Node | None = None
        self.right: Node | None = None


def insert(
    node: Node | None,
    value: int,
) -> Node | None:
    if node is None:
        return Node(value)
    if value < node.value:
        node.left = insert(node.left, value)
    elif value > node.value:
        node.right = insert(node.right, value)
    return node


def find(
    node: Node | None,
    value: int,
) -> Node | None:
    while node is not None and node.value != value:
        node = node.left if value < node.value else node.right
    return node


def find_min(
    node: Node | None,
) -> Node | None:
    if node is None:
        return None
    while node.left is not None:
        node = node.left
    return node


def max_depth(node: Node | None) -> int:
    if node is None:
        return 0
    return 1 + max(max_depth(node.left), max_depth(node.right))


def build(values: list[int]) -> Node | None:
    root: Node | None = None
    for value in values:
        root = insert(root, value)
    return root


def search(values: list[int]) -> int:
    return max_depth(build(values))


def describe(values: list[int], target: int) -> str:
    root = build(values)
    smallest = find_min(root)
    hit = find(root, target)
    parts = [f"values={values}", f"depth={max_depth(root)}"]
    if smallest is None:
        parts.append("min=none")
    else:
        parts.append(f"min={smallest.value}")
    if hit is None:
        parts.append(f"{target} not found")
    else:
        parts.append(f"{target} found with subtree depth {max_depth(hit)}")
    return ", ".join(parts)


def main() -> None:
    print(search([5, 3, 7]))
    print(describe([5, 3, 7], 7))
    print(describe([8, 3, 10, 1, 6, 14, 4, 7, 13], 6))
    print(describe([], 1))


if __name__ == "__main__":
    main()

