from dataclasses import dataclass


@dataclass
class Product:
    name: str
    price: int | None = None
    category: str | None = None
    rating: int | None = None
    color: str | None = None


def discounted_price(
    price: int | None,
    percent: int = 10,
) -> int | None:
    if price is None:
        return None
    return price - (price * percent) // 100


def format_category(
    category: str | None,
) -> str | None:
    if category is None:
        return None
    cleaned = category.strip()
    if not cleaned:
        return None
    return cleaned.upper()


def is_high_rating(rating: int | None, threshold: int = 4) -> bool:
    return rating is not None and rating >= threshold


def standardize_color(
    color: str | None,
) -> str | None:
    if color is None:
        return None
    cleaned = color.strip().lower().replace("_", " ")
    if not cleaned:
        return None
    return cleaned.replace(" ", "-")


def build_product(row: tuple) -> Product:
    name = row[0]
    fields = list(row[1:]) + [None] * (4 - len(row[1:]))
    price, category, rating, color = fields
    return Product(
        name=name,
        price=price,
        category=format_category(category),
        rating=rating,
        color=standardize_color(color),
    )


def filter(products: list[tuple]) -> list[str]:
    selected: list[str] = []
    for row in products:
        product = build_product(row)
        if not is_high_rating(product.rating):
            continue
        final_price: int | None = discounted_price(product.price)
        if final_price is None:
            continue
        selected.append(product.name)
    return selected


def describe(row: tuple) -> str:
    product = build_product(row)
    price = discounted_price(product.price)
    price_text = "n/a" if price is None else str(price)
    parts = [product.name, price_text, product.category or "uncategorized"]
    if product.color is not None:
        parts.append(product.color)
    return " | ".join(parts)


def main() -> None:
    catalogue = [
        ("laptop", 1000, "electronics", 5, "black"),
        ("mug", None, "kitchen", 5, "White"),
        ("chair", 200, None, 2, None),
    ]
    print(filter(catalogue))
    for row in catalogue:
        print(describe(row))


if __name__ == "__main__":
    main()

