from dataclasses import dataclass


@dataclass
class Query:
    table: str
    limit: int | None = None
    offset: int | None = None
    order: str | None = None
    group_by: str | None = None


def from_tuple(row: tuple) -> Query:
    if not row or not isinstance(row[0], str) or not row[0].strip():
        raise ValueError("a query needs a non-empty table name")
    limit: int | None = row[1] if len(row) > 1 else None
    offset: int | None = row[2] if len(row) > 2 else None
    order: str | None = row[3] if len(row) > 3 else None
    group_by: str | None = row[4] if len(row) > 4 else None
    return Query(row[0].strip(), limit, offset, order, group_by)


def limit_clause(
    limit: int | None,
) -> str | None:
    if limit is None or limit < 0:
        return None
    return f"LIMIT {limit}"


def offset_clause(
    offset: int | None,
) -> str | None:
    if offset is None or offset <= 0:
        return None
    return f"OFFSET {offset}"


def order_clause(
    direction: str | None,
) -> str | None:
    if direction is None:
        return None
    keywords = {"asc": "ASC", "ascending": "ASC", "desc": "DESC", "descending": "DESC"}
    keyword: str | None = keywords.get(direction.strip().lower())
    if keyword is None:
        return None
    return f"ORDER BY 1 {keyword}"


def valid_group(group_by: str | None) -> bool:
    if group_by is None:
        return False
    column = group_by.strip()
    return column.isidentifier() and not column[0].isdigit()


def render(query: Query) -> str:
    parts = [f"SELECT * FROM {query.table}"]
    if valid_group(query.group_by):
        parts.append(f"GROUP BY {query.group_by.strip()}")
    order: str | None = order_clause(query.order)
    if order is not None:
        parts.append(order)
    limit: str | None = limit_clause(query.limit)
    if limit is not None:
        parts.append(limit)
    offset: str | None = offset_clause(query.offset)
    if offset is not None:
        parts.append(offset)
    return " ".join(parts) + ";"


def build(queries: list) -> list:
    selected = []
    for row in queries:
        query = from_tuple(row)
        if valid_group(query.group_by) and limit_clause(query.limit) is not None:
            selected.append(query.table)
    return selected


def main() -> None:
    queries = [
        ("users", 10, None, "descending", "role"),
        ("logs", None, 5, "asc", "level"),
        ("orders", 20, 10, "sideways", "1bad"),
    ]
    print(build(queries))
    for row in queries:
        print(render(from_tuple(row)))


if __name__ == "__main__":
    main()

