from dataclasses import dataclass

Record = tuple[
    str,
    int | None,
    int | None,
    int | None,
    int | None,
]


@dataclass
class Observation:
    station: str
    temperature: int | None
    humidity: int | None
    wind_speed: int | None
    pressure: int | None


def from_record(record: Record) -> Observation:
    station, temperature, humidity, wind_speed, pressure = record
    return Observation(station.strip(), temperature, humidity, wind_speed, pressure)


def to_celsius(
    fahrenheit: int | None,
) -> int | None:
    if fahrenheit is None:
        return None
    return round((fahrenheit - 32) * 5 / 9)


def heat_index_category(
    humidity: int | None,
) -> str | None:
    if humidity is None:
        return None
    if humidity < 0 or humidity > 100:
        return None
    if humidity < 30:
        return "dry"
    if humidity < 60:
        return "comfortable"
    if humidity < 85:
        return "muggy"
    return "oppressive"


def wind_category(
    speed: int | None,
) -> str | None:
    if speed is None:
        return "unknown"
    if speed < 0:
        return None
    if speed < 2:
        return "calm"
    if speed < 20:
        return "breezy"
    if speed < 50:
        return "windy"
    return "storm"


def is_pressure_stable(pressure: int | None) -> bool:
    return pressure is not None and 1000 <= pressure <= 1025


def label(value: str | None) -> str:
    return value if value is not None else "n/a"


def format_celsius(celsius: int | None) -> str:
    return f"{celsius}C" if celsius is not None else "n/a"


def report(records: list[Record]) -> list[str]:
    lines = []
    for record in records:
        obs = from_record(record)
        pressure_note = "stable" if is_pressure_stable(obs.pressure) else "unsettled"
        lines.append(
            f"{obs.station}: {format_celsius(to_celsius(obs.temperature))}"
            f" | {label(heat_index_category(obs.humidity))}"
            f" | {label(wind_category(obs.wind_speed))}"
            f" | {pressure_note}"
        )
    return lines


def analyze(records: list[Record]) -> list[str]:
    usable = []
    for record in records:
        obs = from_record(record)
        if to_celsius(obs.temperature) is None:
            continue
        if wind_category(obs.wind_speed) is None:
            continue
        usable.append(obs.station)
    return usable


def main() -> None:
    records: list[Record] = [
        ("station one", 90, 80, None, None),
        ("station two", None, 45, 12, 1010),
        ("station three", 58, 110, -4, 980),
    ]
    for line in report(records):
        print(line)
    print(analyze(records))
    print(analyze([("station one", 90, 80, None, None)]))


if __name__ == "__main__":
    main()

