@dataclass
class Event:
    title: str
    start_hour: int | None = None
    end_hour: int | None = None
    location: str | None = None
    description: str | None = None


def time_of_day(
    start_hour: int | None,
) -> str | None:
    if start_hour is None:
        return None
    if start_hour < 12:
        return "morning"
    if start_hour < 17:
        return "afternoon"
    return "evening"


def ends_late(end_hour: int | None) -> bool:
    if end_hour is None:
        return False
    return end_hour >= 20


def format_location(
    location: str | None,
) -> str | None:
    cleaned = (location or "").strip()
    if not cleaned:
        return None
    return cleaned.upper()


def truncate_description(
    description: str | None,
    limit: int = 30,
) -> str | None:
    if description is None:
        return None
    if len(description) <= limit:
        return description
    return description[: limit - 3] + "..."


def duration(
    start_hour: int | None,
    end_hour: int | None,
) -> int | None:
    if start_hour is None or end_hour is None:
        return None
    return end_hour - start_hour


def build_event(row: tuple) -> Event:
    title, start_hour, end_hour, location, description = row
    return Event(title, start_hour, end_hour, location, description)


def describe(event: Event) -> str:
    parts = [event.title]
    slot = time_of_day(event.start_hour)
    if slot is not None:
        parts.append(slot)
    hours = duration(event.start_hour, event.end_hour)
    if hours is not None:
        parts.append(f"{hours}h")
    place = format_location(event.location)
    if place is not None:
        parts.append(place)
    summary = truncate_description(event.description)
    if summary is not None:
        parts.append(summary)
    return " | ".join(parts)


def schedule(events):
    titles = []
    for row in events:
        event = build_event(row)
        if format_location(event.location) is None:
            continue
        if ends_late(event.end_hour):
            continue
        titles.append(event.title)
    return titles


def main() -> None:
    rows = [
        ("meeting", 9, 10, "office", None),
        ("gala", 19, 22, "hall", "annual company celebration with dinner"),
        ("call", None, None, None, "sync with the remote team"),
    ]
    for row in rows:
        print(describe(build_event(row)))
    print(schedule(rows))


if __name__ == "__main__":
    main()

