from dataclasses import dataclass

BASE_METABOLIC_BURN = 2000


@dataclass
class DailyLog:
    date: str
    steps: int | None = None
    heart_rate: int | None = None
    sleep_hours: int | None = None
    calories: int | None = None


def assess_steps(
    steps: int | None,
) -> str | None:
    if steps is None:
        return None
    if steps >= 10000:
        return "goal met"
    if steps >= 5000:
        return "active"
    return "sedentary"


def evaluate_heart_rate(
    heart_rate: int | None,
) -> str | None:
    if heart_rate is None:
        return None
    if heart_rate < 60:
        return "resting"
    if heart_rate < 100:
        return "normal"
    if heart_rate < 140:
        return "aerobic"
    return "peak"


def check_sleep(sleep_hours: int | None) -> bool:
    if sleep_hours is None:
        return False
    return sleep_hours >= 7


def calorie_balance(
    calories: int | None,
) -> int | None:
    if calories is None:
        return None
    return calories - BASE_METABOLIC_BURN


def parse_log(entry: tuple) -> DailyLog:
    date, steps, heart_rate, sleep_hours, calories = entry
    return DailyLog(date, steps, heart_rate, sleep_hours, calories)


def summarize(log: DailyLog) -> str:
    goal = assess_steps(log.steps)
    zone = evaluate_heart_rate(log.heart_rate)
    balance = calorie_balance(log.calories)
    parts = [log.date]
    parts.append(f"steps: {goal or 'unknown'}")
    parts.append(f"zone: {zone or 'unknown'}")
    parts.append(f"sleep: {'sufficient' if check_sleep(log.sleep_hours) else 'short'}")
    parts.append("balance: " + ("unknown" if balance is None else f"{balance:+d} kcal"))
    return " | ".join(parts)


def evaluate(days: list[tuple]) -> list[str]:
    healthy = []
    for entry in days:
        log = parse_log(entry)
        zone = evaluate_heart_rate(log.heart_rate)
        if check_sleep(log.sleep_hours) and zone is not None:
            healthy.append(log.date)
    return healthy


def main() -> None:
    days = [
        ("monday", 10000, 80, 8, None),
        ("tuesday", 4200, None, 6, 2400),
        ("wednesday", None, 58, 9, 1850),
    ]
    for entry in days:
        print(summarize(parse_log(entry)))
    print(evaluate(days))


if __name__ == "__main__":
    main()

