from __future__ import annotations

import datetime
from dataclasses import dataclass
from typing import Any, Iterable, Sequence

WORD_NUMBERS = {"zero": 0, "one": 1, "two": 2, "three": 3, "four": 4}
VALID_SEAT_CLASSES = {"economy", "premium economy", "business", "first"}


@dataclass
class FlightQuery:
    destination: str
    return_date: str | None = None
    airline: str | None = None
    max_stops: int | None = None
    seat_class: str | None = None


def parse_return_date(
    raw: str | None,
    today: datetime.date | None = None,
) -> str | None:
    if raw is None:
        return None
    text = " ".join(raw.split()).lower()
    if not text:
        return None
    base = today if today is not None else datetime.date.today()
    if text == "today":
        return base.isoformat()
    if text == "tomorrow":
        return (base + datetime.timedelta(days=1)).isoformat()
    try:
        return datetime.date.fromisoformat(text).isoformat()
    except ValueError:
        return None


def standardize_airline(name: str | None) -> str | None:
    if name is None:
        return None
    cleaned = " ".join(name.split()).upper()
    return cleaned or None


def to_stop_count(
    value: Any,
) -> int | None:
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        text = " ".join(value.split()).lower()
        if text.isdigit():
            return int(text)
        return WORD_NUMBERS.get(text)
    return None


def evaluate_max_stops(stops: int | None) -> str | None:
    if stops is None:
        return None
    if stops <= 0:
        return "direct"
    if stops == 1:
        return "one stop"
    return "multi stop"


def validate_seat_class(seat: str | None) -> bool:
    if seat is None:
        return False
    return " ".join(seat.split()).lower() in VALID_SEAT_CLASSES


def build_query(row: Sequence[Any]) -> FlightQuery | None:
    fields = list(row) + [None] * (5 - len(row))
    destination, return_date, airline, stops, seat_class = fields[:5]
    if not isinstance(destination, str) or not destination.strip():
        return None
    return FlightQuery(
        destination=destination.strip(),
        return_date=return_date,
        airline=airline,
        max_stops=to_stop_count(stops),
        seat_class=seat_class,
    )


def format_summary(query: FlightQuery) -> str:
    parts = [query.destination]
    airline: str | None = standardize_airline(query.airline)
    if airline is not None:
        parts.append(f"airline={airline}")
    date_text: str | None = parse_return_date(query.return_date)
    if date_text is not None:
        parts.append(f"return={date_text}")
    stop_text: str | None = evaluate_max_stops(query.max_stops)
    if stop_text is not None:
        parts.append(f"stops={stop_text}")
    parts.append("seat=" + ("ok" if validate_seat_class(query.seat_class) else "invalid"))
    return ", ".join(parts)


def search(queries: Iterable[Sequence[Any]]) -> list[str]:
    matches = []
    for row in queries:
        query = build_query(row)
        if query is None:
            continue
        if validate_seat_class(query.seat_class) and standardize_airline(query.airline):
            matches.append(query.destination)
    return matches


def main() -> None:
    queries = [
        ("london", "tomorrow", "delta", "one", "economy"),
        ("paris", None, "  air france ", 0, "business"),
        ("oslo", "2026-03-04", None, 2, "first"),
        ("rome", "next week", "ita", "three", "sleeper"),
    ]
    print(search(queries))
    for row in queries:
        built = build_query(row)
        if built is not None:
            print(format_summary(built))


if __name__ == "__main__":
    main()

