from dataclasses import dataclass


@dataclass
class Book:
    title: str
    author: str | None = None
    year: int | None = None
    genre: str | None = None
    isbn: str | None = None


def format_author(
    author: str | None,
) -> str | None:
    if author is None or not author.strip():
        return None
    return author.strip().title()


def categorize_year(
    year: int | None,
) -> str | None:
    if year is None or year < 1500 or year > 2100:
        return None
    if year < 1900:
        return "Classic"
    if year < 1946:
        return "Modern"
    if year < 2000:
        return "Contemporary"
    return "Digital Age"


def standardize_genre(
    genre: str | None,
) -> str | None:
    if genre is None or not genre.strip():
        return None
    return genre.strip().upper()


def validate_isbn(isbn: str | None) -> bool:
    if isbn is None:
        return False
    code = isbn.replace("-", "").replace(" ", "").upper()
    if len(code) == 10:
        total = 0
        for position, char in enumerate(code):
            if char == "X" and position == 9:
                total += 10 * (10 - position)
            elif char.isdigit():
                total += int(char) * (10 - position)
            else:
                return False
        return total % 11 == 0
    if len(code) == 13 and code.isdigit():
        return sum(int(c) * (1 if i % 2 == 0 else 3) for i, c in enumerate(code)) % 10 == 0
    return False


def build_book(entry: tuple) -> Book:
    padded = tuple(entry) + (None,) * (5 - len(entry))
    title, author, year, genre, isbn = padded[:5]
    return Book(title, format_author(author), year, standardize_genre(genre), isbn)


def describe(book: Book) -> str:
    era: str | None = categorize_year(book.year)
    parts = [book.title, book.author or "unknown author", era or "undated"]
    if book.genre is not None:
        parts.append(book.genre)
    return " | ".join(parts)


def catalog(books):
    titles = []
    for entry in books:
        book = build_book(entry)
        if validate_isbn(book.isbn) and categorize_year(book.year) is not None:
            titles.append(book.title)
    return titles


def main() -> None:
    entries = [
        ("Foundation", "isaac asimov", 1951, None, "0553293354"),
        ("Untitled Draft", None, 3000, "sci-fi", "0553293354"),
        ("Broken Record", "ada lovelace", 1843, "essays", "123"),
    ]
    for entry in entries:
        print(describe(build_book(entry)))
    print(catalog(entries))


if __name__ == "__main__":
    main()

