import base64
import re
from typing import Optional


class Response:
    def __init__(
        self,
        status: int,
        error: Optional[str] = None,
        payload: Optional[str] = None,
        status_text: Optional[str] = None,
        request_id: Optional[str] = None,
    ) -> None:
        self.status = status
        self.error = error
        self.payload = payload
        self.status_text = status_text
        self.request_id = request_id

    def __repr__(self) -> str:
        return f"Response(status={self.status}, request_id={self.request_id!r})"


def extract_error_code(
    error: Optional[str],
) -> Optional[str]:
    if error is None:
        return None
    match = re.search(r"\b([A-Z]{2,}-\d{2,})\b", error)
    if match is None:
        return None
    return match.group(1)


def decode_payload(
    payload: Optional[str],
) -> Optional[str]:
    if payload is None:
        return None
    try:
        raw = base64.b64decode(payload, validate=True)
    except Exception:
        return payload
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        return payload


def format_status_text(
    status_text: Optional[str],
) -> Optional[str]:
    if status_text is None:
        return None
    stripped = status_text.strip()
    if not stripped:
        return None
    return stripped.upper()


def validate_request_id(request_id: Optional[str]) -> bool:
    if request_id is None:
        return False
    return bool(re.fullmatch(r"[A-Za-z0-9 _-]{2,64}", request_id.strip()))


def build_response(row: tuple) -> Response:
