from __future__ import annotations

MISSING = "missing"


class Property:
    def __init__(
        self,
        address: str,
        bedrooms: int | None,
        bathrooms: int | None,
        square_feet: int | None,
        lot_size: int | None,
    ) -> None:
        self.address = address
        self.bedrooms = bedrooms
        self.bathrooms = bathrooms
        self.square_feet = square_feet
        self.lot_size = lot_size

    @classmethod
    def from_tuple(cls, record: tuple) -> "Property":
        address, bedrooms, bathrooms, square_feet, lot_size = record
        return cls(address, bedrooms, bathrooms, square_feet, lot_size)


def categorize_bedrooms(bedrooms: int | None) -> str:
    if bedrooms is None:
        return MISSING
    if bedrooms <= 1:
        return "compact"
    if bedrooms <= 3:
        return "family"
    return "generous"


def has_enough_bathrooms(bathrooms: int | None) -> bool:
    return bathrooms is not None and bathrooms >= 2


def categorize_square_feet(square_feet: int | None) -> str:
    if square_feet is None:
        return MISSING
    if square_feet < 1000:
        return "small"
    if square_feet < 2500:
        return "medium"
    return "large"


def assess_lot_size(lot_size: int | None) -> str:
    if lot_size is None:
        return MISSING
    if lot_size < 4000:
        return "tight lot"
    if lot_size < 10000:
        return "standard lot"
    return "acreage"


def describe(home: Property) -> str:
    return (
        f"{home.address}: {categorize_bedrooms(home.bedrooms)} bedrooms, "
        f"{categorize_square_feet(home.square_feet)} interior, "
        f"{assess_lot_size(home.lot_size)}"
    )


def biggest_interior(homes: list[Property]) -> Property | None:
    sized = [home for home in homes if home.square_feet is not None]
    if not sized:
        return None
    return max(sized, key=lambda home: home.square_feet)


def search(properties) -> list[str]:
    homes = [Property.from_tuple(record) for record in properties]
    return [
        home.address
        for home in homes
        if has_enough_bathrooms(home.bathrooms)
        and categorize_square_feet(home.square_feet) != MISSING
    ]


def main() -> None:
    properties = [("main street", 3, 2, 2000, None)]
    print(search(properties))
    homes = [Property.from_tuple(record) for record in properties]
    for home in homes:
        print(describe(home))
    featured: Property | None = biggest_interior(homes)
    if featured is None:
        print("no measured homes to feature")
    else:
        print(f"featured listing: {featured.address}")


if __name__ == "__main__":
    main()

