@dataclass
class Recipe:
    name: str
    max_time: int | None = None
    restriction: str | None = None
    cuisine: str | None = None
    ingredient: str | None = None


def classify_time(max_time: int | None) -> str:
    if max_time is None:
        return "missing"
    if max_time <= 15:
        return "quick"
    if max_time <= 45:
        return "medium"
    return "slow"


def is_vegan(restriction: str | None) -> bool:
    if restriction is None:
        return False
    return restriction.strip().lower() == "vegan"


def format_cuisine(cuisine: str | None) -> str:
    if cuisine is None:
        return "missing"
    cleaned = cuisine.strip()
    if not cleaned:
        return "missing"
    return cleaned.capitalize()


def validate_ingredient(ingredient: str | None) -> str:
    if ingredient is None:
        return "missing"
    cleaned = ingredient.strip().lower()
    if not cleaned.isalpha():
        return "missing"
    return cleaned


def build_recipe(row: tuple) -> Recipe:
    name = row[0]
    max_time: int | None = row[1] if len(row) > 1 else None
    restriction: str | None = row[2] if len(row) > 2 else None
    cuisine: str | None = row[3] if len(row) > 3 else None
    ingredient: str | None = row[4] if len(row) > 4 else None
    return Recipe(name, max_time, restriction, cuisine, ingredient)


def describe(recipe: Recipe) -> str:
    return (
        f"{recipe.name}: {classify_time(recipe.max_time)}, "
        f"{format_cuisine(recipe.cuisine)}, {validate_ingredient(recipe.ingredient)}"
    )


def find(recipes):
    matches = []
    for row in recipes:
        recipe = build_recipe(row)
        if is_vegan(recipe.restriction) and classify_time(recipe.max_time) != "missing":
            matches.append(recipe.name)
    return matches


def main() -> None:
    data = [("salad", 10, "vegan", None, "lettuce")]
    for row in data:
        print(describe(build_recipe(row)))
    print(find(data))


if __name__ == "__main__":
    main()

