CLASSIC_CUTOFF = 1990
PREFIX_LENGTH = 12


@dataclass
class Track:
    title: str
    artist: str | None = None
    album: str | None = None
    genre: str | None = None
    year: int | None = None


def build_track(row: tuple) -> Track:
    fields = list(row) + [None] * (5 - len(row))
    title, artist, album, genre, year = fields[:5]
    return Track(str(title), artist, album, genre, year)


def format_artist(
    artist: str | None,
) -> str | None:
    if artist is None:
        return None
    cleaned = artist.strip()
    if not cleaned:
        return None
    return cleaned.title()


def album_prefix(
    album: str | None,
) -> str | None:
    if album is None:
        return None
    cleaned = album.strip()
    if not cleaned:
        return None
    return cleaned[:PREFIX_LENGTH]


def standardize_genre(
    genre: str | None,
) -> str | None:
    if genre is None:
        return None
    cleaned = genre.strip()
    if not cleaned:
        return None
    return cleaned.upper()


def is_classic(year: int | None) -> bool:
    return year is not None and year <= CLASSIC_CUTOFF


def describe(track: Track) -> str:
    artist = format_artist(track.artist)
    album = album_prefix(track.album)
    genre = standardize_genre(track.genre)
    year_note = str(track.year) if is_classic(track.year) else "modern"
    return " | ".join([
        track.title,
        artist or "unknown artist",
        album or "unknown album",
        genre or "UNKNOWN GENRE",
        year_note,
    ])


def search(tracks: list[tuple]) -> list[str]:
    matches: list[str] = []
    for row in tracks:
        track = build_track(row)
        named = format_artist(track.artist)
        if named is not None and is_classic(track.year):
            matches.append(track.title)
    return matches


def main() -> None:
    rows = [("bohemian rhapsody", "queen", None, "rock", 1975)]
    print(search(rows))
    for row in rows:
        print(describe(build_track(row)))


if __name__ == "__main__":
