from dataclasses import dataclass


@dataclass
class JobPosting:
    title: str
    salary: int | None = None
    location: str | None = None
    job_type: str | None = None
    experience: str | None = None


def monthly_pay(
    salary: int | None,
) -> int | None:
    if salary is None:
        return None
    return salary // 12


def format_location(
    location: str | None,
) -> str | None:
    if location is None:
        return None
    return location.strip().upper()


def is_remote(job_type: str | None) -> bool:
    if job_type is None:
        return False
    return job_type.strip().lower() in {"remote", "work from home", "telecommute"}


def categorize_experience(
    level: str | None,
) -> str | None:
    if level is None:
        return None
    normalized = level.strip().lower()
    if normalized in {"intern", "junior", "entry"}:
        return "early career"
    if normalized in {"mid", "intermediate"}:
        return "mid career"
    if normalized in {"senior", "lead", "principal"}:
        return "experienced"
    return "unclassified"


def build_posting(row: tuple) -> JobPosting:
    title, salary, location, job_type, experience = row
    return JobPosting(title, salary, location, job_type, experience)


def describe(posting: JobPosting) -> str:
    pay = monthly_pay(posting.salary)
    pay_text = f"{pay}/month" if pay is not None else "pay undisclosed"
    place = format_location(posting.location)
    place_text = place if place is not None else "LOCATION UNKNOWN"
    bracket = categorize_experience(posting.experience)
    bracket_text = bracket if bracket is not None else "experience unknown"
    mode = "remote" if is_remote(posting.job_type) else "on-site"
    return f"{posting.title}: {pay_text}, {place_text}, {mode}, {bracket_text}"


def match(jobs: list[tuple]) -> list[str]:
    matched = []
    for row in jobs:
        posting = build_posting(row)
        pay = monthly_pay(posting.salary)
        if is_remote(posting.job_type) and pay is not None:
            matched.append(posting.title)
    return matched


def main() -> None:
    jobs = [("developer", 100000, None, "remote", "senior")]
    for row in jobs:
        print(describe(build_posting(row)))
    print(match(jobs))


if __name__ == "__main__":
    main()

