from dataclasses import dataclass


@dataclass
class Room:
    number: str
    beds: int | None = None
    view: str | None = None
    balcony: str | None = None
    smoking: str | None = None


def field_at(record: tuple, index: int) -> object | None:
    if index < len(record):
        return record[index]
    return None


def categorize_beds(
    beds: int | None,
) -> str | None:
    if beds is None or beds < 1:
        return None
    if beds == 1:
        return "single"
    if beds == 2:
        return "double"
    if beds <= 4:
        return "family"
    return "suite"


def format_view(
    view: str | None,
) -> str | None:
    if view is None or not view.strip():
        return None
    return view.strip().upper()


def evaluate_balcony(
    balcony: str | None,
) -> str | None:
    if balcony is None or not balcony.strip():
        return None
    kind = balcony.strip().lower()
    if kind in ("none", "no"):
        return "no balcony"
    if kind in ("private", "shared", "juliet"):
        return kind + " balcony"
    return kind


def check_smoking(
    policy: str | None,
) -> bool | None:
    if policy is None or not policy.strip():
        return None
    return policy.strip().lower() in ("allowed", "smoking", "yes", "permitted")


def parse_record(record: tuple) -> Room | None:
    number = field_at(record, 0)
    if not isinstance(number, str) or not number.strip():
        return None
    raw_beds = field_at(record, 1)
    beds: int | None = int(raw_beds) if isinstance(raw_beds, int) else None
    return Room(
        number=number.strip(),
        beds=beds,
        view=field_at(record, 2),
        balcony=field_at(record, 3),
        smoking=field_at(record, 4),
    )


def describe(room: Room) -> str:
    parts = [room.number, categorize_beds(room.beds) or "unknown size"]
    view: str | None = format_view(room.view)
    parts.append(view or "no view")
    parts.append(evaluate_balcony(room.balcony) or "balcony unknown")
    smoking: bool | None = check_smoking(room.smoking)
    if smoking is None:
        parts.append("smoking policy unknown")
    else:
        parts.append("smoking" if smoking else "non-smoking")
    return " | ".join(parts)


def search(rooms):
    matches = []
    for record in rooms:
        room = parse_record(record)
        if room is None:
            continue
        if format_view(room.view) is not None and categorize_beds(room.beds) is not None:
            matches.append(room.number)
    return matches


def main() -> None:
    rooms = [("101", 2, "ocean", "private", "allowed")]
    print(search(rooms))
    for record in rooms:
        room = parse_record(record)
        if room is not None:
            print(describe(room))


if __name__ == "__main__":
    main()

