@dataclass
class Artifact:
    name: str
    era: str | None = None
    material: str | None = None
    origin: str | None = None
    discoverer: str | None = None


Record = tuple[
    str,
    str | None,
    str | None,
    str | None,
    str | None,
]

METAL_MATERIALS = {"bronze", "iron", "gold", "silver", "copper"}
CERAMIC_MATERIALS = {"clay", "porcelain", "terracotta"}
UNKNOWN_DISCOVERERS = {"unknown", "anonymous", "n/a"}


def standardize_era(
    era: str | None,
) -> str | None:
    if era is None:
        return None
    cleaned = era.strip()
    if not cleaned:
        return None
    return cleaned.upper()


def categorize_material(
    material: str | None,
) -> str | None:
    if material is None:
        return None
    cleaned = material.strip().lower()
    if not cleaned:
        return None
    if cleaned in METAL_MATERIALS:
        return "metal"
    if cleaned in CERAMIC_MATERIALS:
        return "ceramic"
    return "other"


def format_origin(
    origin: str | None,
) -> str | None:
    if origin is None:
        return None
    cleaned = origin.strip()
    if not cleaned:
        return None
    return cleaned.capitalize()


def is_discoverer_known(discoverer: str | None) -> bool:
    if discoverer is None:
        return False
    cleaned = discoverer.strip().lower()
    return bool(cleaned) and cleaned not in UNKNOWN_DISCOVERERS


def build_artifact(record: Record) -> Artifact:
    name, era, material, origin, discoverer = record
    return Artifact(
        name=name.strip(),
        era=standardize_era(era),
        material=categorize_material(material),
        origin=format_origin(origin),
        discoverer=discoverer.strip() if discoverer is not None else None,
    )


def describe(artifact: Artifact) -> str:
    parts = [artifact.name, artifact.era or "era unrecorded", artifact.material or "material unrecorded"]
    if artifact.origin is not None:
        parts.append(f"from {artifact.origin}")
    if is_discoverer_known(artifact.discoverer):
        parts.append(f"found by {artifact.discoverer}")
    return " | ".join(parts)


def catalog(artifacts: list[Record]) -> list[str]:
    names = []
    for record in artifacts:
        artifact = build_artifact(record)
        if is_discoverer_known(artifact.discoverer) and artifact.era is not None:
            names.append(artifact.name)
    return names


def main() -> None:
    records: list[Record] = [("ancient vase", "bronze age", "clay", "greece", "smith")]
    for record in records:
        print(describe(build_artifact(record)))
    print(catalog(records))


if __name__ == "__main__":
    main()

