from dataclasses import dataclass


@dataclass
class Mission:
    name: str
    crew_size: int | None = None
    destination: str | None = None
    launch_year: int | None = None
    outcome: str | None = None


def classify_crew(
    crew_size: int | None,
) -> str | None:
    if crew_size is None:
        return None
    if crew_size == 0:
        return "unmanned"
    if crew_size <= 3:
        return "small crew"
    if crew_size <= 7:
        return "medium crew"
    return "large crew"


def format_destination(
    destination: str | None,
) -> str | None:
    if destination is None:
        return None
    stripped = destination.strip()
    if not stripped:
        return None
    return stripped.upper()


def is_early_launch(launch_year: int | None) -> bool:
    if launch_year is None:
        return False
    return launch_year < 1970


def evaluate_outcome(
    outcome: str | None,
) -> str | None:
    if outcome is None:
        return None
    normalized = outcome.strip().lower()
    if normalized in ("success", "successful"):
        return "achieved"
    if normalized in ("failure", "failed", "loss"):
        return "not achieved"
    return "unclear"


def build_mission(record: tuple) -> Mission:
    name = record[0]
    tail = list(record[1:])
    fields: list[object | None] = tail + [None] * (4 - len(tail))
    crew_size, destination, launch_year, outcome = fields
    return Mission(name, crew_size, destination, launch_year, outcome)


def describe(mission: Mission) -> str:
    where: str | None = format_destination(mission.destination)
    status = evaluate_outcome(mission.outcome)
    parts = [mission.name, where or "unknown destination", status or "unknown status"]
    return " | ".join(parts)


def filter(missions: list[tuple]) -> list[str]:
    selected = []
    for record in missions:
        mission = build_mission(record)
        category: str | None = classify_crew(mission.crew_size)
        if is_early_launch(mission.launch_year) and category is not None:
            selected.append(mission.name)
    return selected


def main() -> None:
    missions = [("apollo eleven", 3, "moon", 1969, "success")]
    print(filter(missions))
    for record in missions:
        print(describe(build_mission(record)))


if __name__ == "__main__":
    main()

