from dataclasses import dataclass


@dataclass
class Reservation:
    name: str
    special_request: str | None = None
    seating: str | None = None
    occasion: str | None = None
    allergy: str | None = None


def truncate_request(
    request: str | None,
    limit: int = 20,
) -> str | None:
    if request is None:
        return None
    text = request.strip()
    if not text:
        return None
    if len(text) <= limit:
        return text
    return text[: limit - 3].rstrip() + "..."


def format_seating(
    seating: str | None,
) -> str | None:
    if seating is None:
        return None
    cleaned = seating.strip()
    if not cleaned:
        return None
    return cleaned.upper()


def is_birthday(occasion: str | None) -> bool:
    if occasion is None:
        return False
    return occasion.strip().lower() == "birthday"


def flag_allergy(
    allergy: str | None,
) -> str | None:
    if allergy is None:
        return None
    cleaned = allergy.strip()
    if not cleaned:
        return None
    severe = {"peanut", "peanuts", "shellfish", "gluten"}
    if cleaned.lower() in severe:
        return "SEVERE: " + cleaned.upper()
    return cleaned.upper()


def build(record: tuple) -> Reservation:
    padded = tuple(record) + (None,) * (5 - len(record))
    return Reservation(padded[0], padded[1], padded[2], padded[3], padded[4])


def describe(reservation: Reservation) -> str:
    seating = format_seating(reservation.seating)
    parts = [reservation.name, seating or "no seating preference"]
    request = truncate_request(reservation.special_request)
    if request is not None:
        parts.append(request)
    warning = flag_allergy(reservation.allergy)
    if warning is not None:
        parts.append("allergy " + warning)
    if is_birthday(reservation.occasion):
        parts.append("birthday")
    return " | ".join(parts)


def manage(reservations: list[tuple]) -> list[str]:
    selected = []
    for record in reservations:
        reservation = build(record)
        if is_birthday(reservation.occasion) and format_seating(reservation.seating):
            selected.append(reservation.name)
    return selected


def main() -> None:
    bookings = [("john doe", "quiet table", "window", "birthday", None)]
    for record in bookings:
        print(describe(build(record)))
    print(manage(bookings))


if __name__ == "__main__":
    main()

