from __future__ import annotations

import sys


class Node:
    """A node of a singly linked list holding a text string."""

    def __init__(self, value: str, next_node: Node | None = None) -> None:
        self.value = value
        self.next_node: Node | None = next_node

    def __repr__(self) -> str:
        return f"Node({self.value!r})"


def append(head: Node | None,
           value: str) -> Node | None:
    """Append value at the end of the list and return its head."""
    new_node = Node(value)
    if head is None:
        return new_node
    tail = last_node(head)
    if tail is not None:
        tail.next_node = new_node
    return head


def find_node(head: Node | None,
              value: str) -> Node | None:
    """Return the first node whose string equals value, if any."""
    current = head
    while current is not None:
        if current.value == value:
            return current
        current = current.next_node
    return None


def last_node(
        head: Node | None,
) -> Node | None:
    """Return the final node of the list, if there is one."""
    current = head
    while current is not None and current.next_node is not None:
        current = current.next_node
    return current


def reverse(
        head: Node | None,
) -> Node | None:
    """Reverse the links in place and return the new head."""
    previous: Node | None = None
    current = head
    while current is not None:
        following = current.next_node
        current.next_node = previous
        previous = current
        current = following
    return previous


def collect_values(head: Node | None,
                   prefix: str | None = None) -> list[str]:
