from dataclasses import dataclass


@dataclass
class FileInfo:
    name: str
    parent: str | None = None
    extension: str | None = None
    size: int | None = None
    owner: str | None = None


def format_parent(
    parent: str | None,
) -> str | None:
    if parent is None:
        return None
    stripped = parent.strip().rstrip("/")
    if not stripped:
        return None
    return stripped.upper()


def standardize_extension(
    extension: str | None,
) -> str | None:
    if extension is None:
        return None
    cleaned = extension.strip().lstrip(".")
    if not cleaned:
        return None
    return cleaned.lower()


def classify_size(
    size: int | None,
) -> str | None:
    if size is None:
        return None
    if size < 1024:
        return "small"
    if size < 1024 * 1024:
        return "medium"
    return "large"


def is_root_owner(owner: str | None) -> bool:
    if owner is None:
        return False
    return owner.strip().lower() == "root"


def build_file_info(record: tuple) -> FileInfo:
    name, parent, extension, size, owner = record
    return FileInfo(
        name=name,
        parent=format_parent(parent),
        extension=standardize_extension(extension),
        size=size,
        owner=owner,
    )


def describe(info: FileInfo) -> str:
    category = classify_size(info.size)
    parts = [info.name]
    if info.parent is not None:
        parts.append(f"in {info.parent}")
    if category is not None:
        parts.append(f"({category})")
    return " ".join(parts)


def resolve(paths: list[tuple]) -> list[str]:
    resolved = []
    for record in paths:
        info = build_file_info(record)
        if info.extension is None:
            continue
        if is_root_owner(info.owner):
            continue
        resolved.append(info.name)
    return resolved


def main() -> None:
    paths = [("script", "home", "py", 1000, "user")]
    for record in paths:
        print(describe(build_file_info(record)))
    print(resolve(paths))


if __name__ == "__main__":
    main()

