import math
from dataclasses import dataclass

PAGE_SIZE = 25


@dataclass
class Pagination:
    current_page: int
    next_page: int | None = None
    previous_page: int | None = None
    total_count: int | None = None
    page_token: str | None = None


def next_offset(next_page: int | None) -> int | None:
    if next_page is None:
        return None
    return (next_page - 1) * PAGE_SIZE


def previous_offset(previous_page: int | None) -> int | None:
    if previous_page is None:
        return None
    return (previous_page - 1) * PAGE_SIZE


def estimate_total_pages(total_count: int | None) -> int | None:
    if total_count is None:
        return None
    return max(1, math.ceil(total_count / PAGE_SIZE))


def has_token(page_token: str | None) -> bool:
    return bool(page_token and page_token.strip())


def build_pagination(row: tuple) -> Pagination:
    current, nxt, prev, total, token = row
    return Pagination(
        current_page=current,
        next_page=nxt,
        previous_page=prev,
        total_count=total,
        page_token=token,
    )


def describe(page: Pagination) -> str:
    total_pages: int | None = estimate_total_pages(page.total_count)
    back: int | None = previous_offset(page.previous_page)
    parts = [f"page {page.current_page}"]
    if total_pages is not None:
        parts.append(f"of ~{total_pages}")
    if back is not None:
        parts.append(f"prev offset {back}")
    if has_token(page.page_token):
        parts.append(f"token {page.page_token}")
    return ", ".join(parts)


def extract(pages: list[tuple]) -> list[int]:
    result = []
    for row in pages:
        page = build_pagination(row)
        forward: int | None = next_offset(page.next_page)
        if estimate_total_pages(page.total_count) is not None and forward is not None:
            result.append(page.current_page)
    return result


def main() -> None:
    pages = [(1, 2, None, 100, "token")]
    print(extract(pages))
    for row in pages:
        print(describe(build_pagination(row)))


if __name__ == "__main__":
    main()

