import re
from dataclasses import dataclass


@dataclass
class Constraint:
    text: str
    pattern: str | None = None
    start: int | None = None
    end: int | None = None
    case: str | None = None


def format_pattern(
    pattern: str | None,
) -> str | None:
    if pattern is None:
        return None
    stripped = pattern.strip()
    if not stripped:
        return None
    return stripped.upper()


def validate_start(
    start: int | None,
) -> int | None:
    if start is None or start < 0:
        return None
    return start


def validate_end(
    end: int | None,
) -> int | None:
    if end is None or end <= 0:
        return None
    return end


def is_case_sensitive(case: str | None) -> bool:
    if case is None:
        return True
    return case.strip().lower() not in {"insensitive", "ignore", "i"}


def build_constraint(segment: tuple) -> Constraint | None:
    if not segment or not isinstance(segment[0], str):
        return None
    values = list(segment) + [None] * (5 - len(segment))
    return Constraint(values[0], values[1], values[2], values[3], values[4])


def find_match(
    text: str,
    pattern: str,
    start: int,
    end: int | None,
    sensitive: bool,
) -> str | None:
    window = text[start:end] if end is not None else text[start:]
    flags = 0 if sensitive else re.IGNORECASE
    found = re.search(pattern, window, flags)
    if found is None:
        return None
    return found.group(0)


def evaluate(constraint: Constraint) -> str | None:
    pattern = format_pattern(constraint.pattern)
    start = validate_start(constraint.start)
    if pattern is None or start is None:
        return None
    end = validate_end(constraint.end)
    sensitive = is_case_sensitive(constraint.case)
    return find_match(constraint.text, pattern, start, end, sensitive)


def collect(segments: list[tuple]) -> list[tuple[str, str | None]]:
    pairs = []
    for segment in segments:
        constraint = build_constraint(segment)
        if constraint is None:
            continue
        pairs.append((constraint.text, evaluate(constraint)))
    return pairs


def search(segments: list[tuple]) -> list[str]:
    return [text for text, hit in collect(segments) if hit is not None]


def main() -> None:
    print(search([("hello world", "hello", 0, 5, "insensitive")]))


if __name__ == "__main__":
    main()

