from dataclasses import dataclass

CURRENT_YEAR = 2024
SOON_WINDOW = 1
UNKNOWN = "unknown"


@dataclass
class Student:
    name: str
    major: str | None = None
    graduation_year: int | None = None
    advisor: str | None = None
    minor: str | None = None


def format_major(
    major: str | None,
) -> str | None:
    if major is None:
        return None
    cleaned = major.strip()
    if not cleaned:
        return None
    return cleaned.upper()


def is_graduating_soon(
    graduation_year: int | None,
    reference_year: int = CURRENT_YEAR,
) -> bool:
    if graduation_year is None:
        return False
    return reference_year <= graduation_year <= reference_year + SOON_WINDOW


def standardize_advisor(
    advisor: str | None,
) -> str | None:
    if advisor is None:
        return None
    cleaned = " ".join(advisor.split())
    if not cleaned:
        return None
    if cleaned.lower().startswith("dr."):
        cleaned = cleaned[3:].strip()
    return "Dr. " + cleaned.title()


def format_minor(
    minor: str | None,
) -> str | None:
    if minor is None:
        return None
    cleaned = minor.strip()
    if not cleaned:
        return None
    return cleaned.upper()


def build_student(record: tuple) -> Student:
    fields = list(record) + [None] * (5 - len(record))
    name, major, graduation_year, advisor, minor = fields[:5]
    return Student(str(name), major, graduation_year, advisor, minor)


def describe(student: Student) -> str:
    major: str | None = format_major(student.major)
    parts = [f"{student.name}: {major or UNKNOWN}"]
    advisor = standardize_advisor(student.advisor)
    if advisor is not None:
        parts.append(f"advised by {advisor}")
    minor = format_minor(student.minor)
    if minor is not None:
        parts.append(f"minor in {minor}")
    if student.graduation_year is not None:
        parts.append(f"class of {student.graduation_year}")
    return ", ".join(parts)


def track(students: list[tuple]) -> list[str]:
    graduating = []
    for record in students:
        student = build_student(record)
        major = format_major(student.major)
        if major is not None and is_graduating_soon(student.graduation_year):
            graduating.append(student.name)
    return graduating


def main() -> None:
    roster = [("alice", "biology", 2024, "smith", "chemistry")]
    for record in roster:
        print(describe(build_student(record)))
    print(track(roster))


if __name__ == "__main__":
    main()

