from dataclasses import dataclass


@dataclass
class BugReport:
    title: str
    steps: str | None = None
    expected: str | None = None
    screenshot: str | None = None
    operating_system: str | None = None
    browser_version: str | None = None


def platform_tag(
    title: str,
    operating_system: str | None,
) -> str | None:
    if operating_system is None:
        return None
    if operating_system.lower() in title.lower():
        return f"platform:{operating_system.lower().replace(' ', '-')}"
    return None


def quality_score(
    expected: str | None,
) -> int | None:
    if expected is None:
        return None
    text = expected.strip()
    if not text:
        return None
    if len(text) < 20:
        return 1
    if len(text) < 80:
        return 3
    return 5


def priority(bug: BugReport) -> int:
    score = 1
    if bug.steps is not None:
        score += 3
    if bug.screenshot is not None:
        score += 2
    if bug.operating_system is not None:
        score += 1
    if bug.browser_version is not None:
        score += 1
    if platform_tag(bug.title, bug.operating_system) is not None:
        score += 2
    quality: int | None = quality_score(bug.expected)
    if quality is not None:
        score += quality
    return score


def triage(bugs: list[BugReport]) -> list[int]:
    return [priority(bug) for bug in bugs]


def describe(bug: BugReport, score: int) -> str:
    tag: str | None = platform_tag(bug.title, bug.operating_system)
    label = tag if tag is not None else "platform:unknown"
    return f"[{score:>2}] {bug.title} ({label})"


def main() -> None:
    bugs = [
        BugReport(title="Crash on Windows when saving", operating_system="Windows"),
        BugReport(
            title="Login button unresponsive",
            steps="Open /login, click the button twice.",
            expected="The user should be redirected to the dashboard within two seconds.",
            screenshot="login-frozen.png",
            operating_system="macOS",
            browser_version="Safari 17.2",
        ),
        BugReport(title="Typo in footer", expected="Copyright 2026"),
    ]
    scores = triage(bugs)
    print(scores)
    for bug, score in zip(bugs, scores):
        print(describe(bug, score))


if __name__ == "__main__":
    main()

