) -> str | None:
    if comment is None or contact_email is None:
        return None
    text = comment.lower()
    hits = [word for word in NEGATIVE_KEYWORDS if word in text]
    if not hits:
        return None
    if len(hits) > 1:
        return "urgent"
    return "standard"


def generation_label(
    age_bracket: str | None,
) -> str | None:
    if age_bracket is None:
