from dataclasses import dataclass

REGISTRY_PREFIXES = {"981": "Datamars", "900": "Trovan", "985": "HomeAgain"}
SEVERE_ALLERGIES = {"penicillin", "bee venom", "sulfa drugs"}

RAW_RECORDS = """
cat | Domestic Shorthair |  | low-phosphorus diet | penicillin | Dr. Nguyen
dog | Labrador | 981098700123456 |  | bee venom |
rabbit |  | 900008801234567 | timothy hay only |  | Dr. Patel
ferret | | 123456789012345 | | pollen |
"""


@dataclass
class Patient:
    species: str
    breed: str | None = None
    microchip: str | None = None
    diet: str | None = None
    allergy: str | None = None
    preferred_vet: str | None = None


def identify(
    microchip: str | None,
    breed: str | None,
) -> str | None:
    if microchip is None:
        return None
    registry: str | None = REGISTRY_PREFIXES.get(microchip[:3])
    if registry is None:
        return None
    descriptor = breed if breed is not None else "breed unrecorded"
    return f"{descriptor}, {registry} chip {microchip}"


def medical_alert(
    allergy: str | None,
) -> str | None:
    if allergy is None:
        return None
    if allergy.lower() not in SEVERE_ALLERGIES:
        return None
    return f"MEDICAL ALERT: severe {allergy} allergy"


def care_note(
    diet: str | None,
    preferred_vet: str | None,
) -> str | None:
    parts = []
    if diet is not None:
        parts.append(f"diet: {diet}")
    if preferred_vet is not None:
        parts.append(f"preferred vet: {preferred_vet}")
    return ", ".join(parts) if parts else None


def parse_field(raw: str) -> str | None:
    cleaned = raw.strip()
    return cleaned if cleaned else None


def parse_record(line: str) -> Patient | None:
    if not line.strip():
        return None
    fields = [parse_field(part) for part in line.split("|")]
    fields += [None] * (6 - len(fields))
    species = fields[0]
    if species is None:
        raise ValueError(f"record without a species: {line!r}")
    return Patient(species, fields[1], fields[2], fields[3], fields[4], fields[5])


def admit(patients: list[Patient]) -> list[str]:
    sentences = []
    for patient in patients:
        ident: str | None = identify(patient.microchip, patient.breed)
        alert = medical_alert(patient.allergy)
        note = care_note(patient.diet, patient.preferred_vet)
        sentence = f"Admitting {patient.species}"
        if ident is not None:
            sentence += f" ({ident})"
        elif patient.breed is not None:
            sentence += f" ({patient.breed}, unregistered)"
        if alert is not None:
            sentence += f" -- {alert}"
        if note is not None:
            sentence += f" [{note}]"
        sentences.append(sentence + ".")
    return sentences


def main() -> None:
    patients = []
    for line in RAW_RECORDS.splitlines():
        patient = parse_record(line)
        if patient is not None:
            patients.append(patient)
    for sentence in admit(patients):
        print(sentence)


if __name__ == "__main__":
