from dataclasses import dataclass


@dataclass
class Shipment:
    destination: str
    warehouse: str | None = None
    hazard_code: str | None = None
    temperature: float | None = None
    time_window: tuple[str, str] | None = None
    broker: str | None = None


def special_handling(
    temperature: float | None,
    hazard_code: str | None,
) -> str | None:
    """Return a handling note when a cold chain and a hazard class conflict."""
    if temperature is None or hazard_code is None:
        return None
    hazard_class = hazard_code.split(".")[0].strip()
    if temperature <= 8.0 and hazard_class in {"2", "3", "5"}:
        return f"segregated reefer unit required (hazard {hazard_code} at {temperature:.1f}C)"
    return None


def routing_note(
    warehouse: str | None,
) -> str | None:
    if warehouse is None:
        return None
    if "bond" in warehouse.lower():
        return f"clear bonded stock at {warehouse}"
    return None


def window_note(
    time_window: tuple[str, str] | None,
) -> str | None:
    if time_window is None:
        return None
    start, end = time_window
    return f"deliver between {start} and {end}"


def broker_note(
    broker: str | None,
    hazard_code: str | None,
) -> str | None:
    if broker is None:
        return None
    if hazard_code is None:
        return f"file entry via {broker}"
    return f"file entry via {broker} with dangerous-goods declaration {hazard_code}"


def route(shipments: list[Shipment]) -> list[str]:
    directives = []
    for shipment in shipments:
        parts = [
            special_handling(shipment.temperature, shipment.hazard_code),
            routing_note(shipment.warehouse),
            window_note(shipment.time_window),
            broker_note(shipment.broker, shipment.hazard_code),
        ]
        details = [part for part in parts if part is not None]
        if details:
            directives.append(f"{shipment.destination}: " + "; ".join(details))
        else:
            directives.append(f"{shipment.destination}: standard line haul")
    return directives


def main() -> None:
    shipments = [
        Shipment("London", hazard_code="3.2", temperature=4.0),
        Shipment("Rotterdam", warehouse="Bonded Depot 7", time_window=("08:00", "12:00")),
        Shipment("Lyon", broker="Moreau SARL", hazard_code="8.1"),
        Shipment("Porto"),
    ]
    for directive in route(shipments):
        print(directive)


if __name__ == "__main__":
    main()

