from dataclasses import dataclass

NAKED_EYE_LIMIT = 6.0
NORTHERN_CONSTELLATIONS = {
    "Ursa Major", "Ursa Minor", "Cassiopeia", "Cygnus", "Lyra", "Bootes",
    "Perseus", "Draco", "Auriga", "Andromeda",
}


@dataclass
class Observation:
    coordinates: str
    constellation: str | None = None
    apparent_magnitude: float | None = None
    spectral_type: str | None = None
    companion: str | None = None
    note: str | None = None


def classify_visibility(
    apparent_magnitude: float | None,
    spectral_type: str | None,
) -> str | None:
    if apparent_magnitude is None or apparent_magnitude >= NAKED_EYE_LIMIT:
        return None
    label = "brilliant naked-eye" if apparent_magnitude <= 1.5 else "naked-eye"
    if spectral_type is None:
        return label
    return f"{label} type-{spectral_type.upper()}"


def region_label(constellation: str | None) -> str | None:
    if constellation is None:
        return None
    name = constellation.strip().title()
    if name not in NORTHERN_CONSTELLATIONS:
        return None
    return f"northern sky region of {name}"


def describe(observation: Observation) -> str:
    visibility: str | None = classify_visibility(
        observation.apparent_magnitude, observation.spectral_type
    )
    region: str | None = region_label(observation.constellation)
    parts = [f"Object at {observation.coordinates}"]
    if visibility is not None:
        parts.append(f"is a {visibility} target")
    if region is not None:
        parts.append(f"lies in the {region}")
    if observation.companion is not None:
        parts.append(f"is paired with {observation.companion}")
    if observation.note is not None:
        parts.append(f"note: {observation.note}")
    return ", ".join(parts) + "."


def catalog(observations: list[Observation]) -> list[str]:
    return [describe(observation) for observation in observations]


def _field(raw: str) -> str | None:
    value = raw.strip()
    if value in ("", "-"):
        return None
    return value


def parse_magnitude(raw: str) -> float | None:
    value = _field(raw)
    if value is None:
        return None
    return float(value)


def parse_observation(record: str) -> Observation | None:
    line = record.strip()
    if not line or line.startswith("#"):
        return None
    cells = line.split("|")
    if len(cells) != 6:
        raise ValueError(f"malformed record: {record!r}")
    coordinates = cells[0].strip()
    if not coordinates:
        raise ValueError("an observation requires celestial coordinates")
    return Observation(
        coordinates,
        _field(cells[1]),
        parse_magnitude(cells[2]),
        _field(cells[3]),
        _field(cells[4]),
        _field(cells[5]),
    )


RECORDS = """
# coords | constellation | magnitude | spectral | companion | note
11h03m +61d45m | Ursa Major | 1.79 | A1 | Alcor | wide double
14h15m +19d11m | Bootes | -0.05 | K0 | - | photometric standard
06h45m -16d43m | Canis Major | -1.46 | A0 | Sirius B | -
00h42m +41d16m | Andromeda | 3.44 | - | - | extended nebulosity
19h50m +08d52m | Aquila | 8.90 | G2 | - | requires 20cm aperture
"""


def main() -> None:
    observations: list[Observation] = []
    for record in RECORDS.splitlines():
        parsed: Observation | None = parse_observation(record)
        if parsed is not None:
            observations.append(parsed)
    for sentence in catalog(observations):
        print(sentence)


if __name__ == "__main__":
    main()

