from dataclasses import dataclass
from datetime import date

RESTRICTED_ORIGINS = {"Elbonia", "Freedonia", "Syldavia"}


@dataclass
class MaterialBatch:
    batch_id: str
    origin_country: str | None = None
    inspection_date: date | None = None
    quarantine_reason: str | None = None
    customs_clearance_date: date | None = None
    destination_factory: str | None = None


def clearance_status(
    inspection_date: date | None,
    quarantine_reason: str | None = None,
) -> str | None:
    if quarantine_reason is not None:
        return None
    if inspection_date is None:
        return None
    return f"cleared after inspection on {inspection_date.isoformat()}"


def tariff_warning(
    origin_country: str | None,
) -> str | None:
    if origin_country in RESTRICTED_ORIGINS:
        return f"restricted origin {origin_country}: verify tariff schedule"
    return None


def pending_reason(batch: MaterialBatch) -> str | None:
    status = clearance_status(batch.inspection_date, batch.quarantine_reason)
    if status is None:
        if batch.quarantine_reason is not None:
            return f"quarantined ({batch.quarantine_reason})"
        return "awaiting quality inspection"
    if batch.customs_clearance_date is None:
        return "customs clearance missing"
    return None


def routing_note(
    destination_factory: str | None,
) -> str | None:
    if destination_factory is None:
        return None
    return f" -> route to {destination_factory}"


def track(batches: list[MaterialBatch]) -> list[str]:
    actions: list[str] = []
    for batch in batches:
        warning = tariff_warning(batch.origin_country)
        pending = pending_reason(batch)
        if warning is None and pending is None:
            continue
        details = [text for text in (warning, pending) if text is not None]
        note = routing_note(batch.destination_factory)
        line = f"{batch.batch_id}: " + "; ".join(details)
        if note is not None:
            line += note
        actions.append(line)
    return actions


def main() -> None:
    batches = [
        MaterialBatch("B-1001", origin_country="Elbonia",
                      inspection_date=date(2026, 3, 2),
                      customs_clearance_date=date(2026, 3, 5)),
        MaterialBatch("B-1002", origin_country="Norway",
                      inspection_date=date(2026, 3, 3),
                      customs_clearance_date=date(2026, 3, 4),
                      destination_factory="Plant A"),
        MaterialBatch("B-1003", origin_country="Norway",
                      quarantine_reason="moisture damage",
                      destination_factory="Plant B"),
    ]
    for action in track(batches):
        print(action)


if __name__ == "__main__":
    main()

