from __future__ import annotations

from dataclasses import dataclass
from datetime import date

RECENT_WINDOW = 30


@dataclass
class Reference:
    title: str
    authors: list[str] | None = None
    year: int | None = None
    journal: str | None = None
    volume: int | None = None
    doi: str | None = None


def format_authors(
    authors: list[str] | None,
) -> str | None:
    if not authors:
        return None
    if len(authors) > 2:
        return f"{authors[0]} et al."
    return " and ".join(authors)


def author_year_prefix(
    authors: list[str] | None,
    year: int | None,
    current_year: int | None = None,
) -> str | None:
    names = format_authors(authors)
    now = current_year if current_year is not None else date.today().year
    if year is not None and 0 <= now - year <= RECENT_WINDOW:
        if names is None:
            return f"({year})"
        return f"{names} ({year})"
    return names


def publication_context(
    journal: str | None,
    volume: int | None,
) -> str | None:
    if journal is None:
        return None
    if volume is not None and volume > 0:
        return f"{journal}, vol. {volume}"
    return journal


def cite(references: list[Reference]) -> list[str]:
    citations = []
    for ref in references:
        prefix = author_year_prefix(ref.authors, ref.year)
        context = publication_context(ref.journal, ref.volume)
        link = f"doi:{ref.doi.strip()}" if ref.doi else None
        parts = [prefix, ref.title, context, link]
        citations.append(". ".join(part for part in parts if part))
    return citations


def main() -> None:
    references = [
        Reference("Attention Is All You Need", ["Vaswani", "Shazeer", "Parmar"]),
        Reference("A Mathematical Theory of Communication", ["Shannon"], 1948,
                  "Bell System Technical Journal", 27),
        Reference("Deep Residual Learning", ["He", "Zhang"], 2016, "CVPR",
                  doi="10.1109/cvpr.2016.90"),
    ]
    for citation in cite(references):
        print(citation)


if __name__ == "__main__":
    main()

