    entry: datetime | None = None
    exit: datetime | None = None
    escort_badge: str | None = None
    zone: str | None = None
    denial_reason: str | None = None


def compute_duration(
    entry: datetime | None,
    exit_time: datetime | None,
) -> float | None:
    if entry is None or exit_time is None:
        return None
    seconds = (exit_time - entry).total_seconds()
    if seconds < 0:
        return None
    return seconds / 60.0


def check_escort(
    zone: str | None,
    escort_badge: str | None,
) -> str | None:
    if zone is None or zone.strip().lower() not in HIGH_SECURITY_ZONES:
        return None
    if escort_badge:
        return None
    return f"ALERT: unescorted access to {zone}"


def parse_stamp(
    text: str | None,
) -> datetime | None:
    if text is None:
        return None
    return datetime.fromisoformat(text)


def build_event(
    badge_id: str,
    entry: str | None = None,
    exit_time: str | None = None,
    escort_badge: str | None = None,
    zone: str | None = None,
    denial_reason: str | None = None,
) -> AccessEvent:
    return AccessEvent(
        badge_id=badge_id,
        entry=parse_stamp(entry),
        exit=parse_stamp(exit_time),
        escort_badge=escort_badge,
        zone=zone,
        denial_reason=denial_reason,
    )


def monitor(events: list[AccessEvent]) -> list[str]:
    log: list[str] = []
    for event in events:
        parts = [event.badge_id]
        if event.denial_reason:
            parts.append(f"DENIED: {event.denial_reason}")
        minutes = compute_duration(event.entry, event.exit)
        if minutes is not None:
            parts.append(f"{minutes:.1f} min")
        alert = check_escort(event.zone, event.escort_badge)
        if alert is not None:
            parts.append(alert)
        log.append(" | ".join(parts))
    return log


def main() -> None:
    events = [
        build_event("B-1001", zone="vault"),
        build_event("B-1002", entry="2026-09-18T08:00:00", exit_time="2026-09-18T09:30:00",
                    zone="server-room", escort_badge="S-77"),
        build_event("B-1003", zone="lobby", denial_reason="expired badge"),
    ]
    for line in monitor(events):
        print(line)


if __name__ == "__main__":
    main()

