from dataclasses import dataclass

PUMP_CAPACITY = 250.0
SALINITY_PH_LIMITS = {"fresh": 7.6, "brackish": 8.1, "marine": 8.4}


@dataclass
class TankReading:
    tank_id: str
    acidity: float | None = None
    salinity: str | None = None
    temperature: float | None = None
    flow_rate: float | None = None
    dissolved_oxygen: float | None = None


def chemical_imbalance(
    acidity: float | None,
    salinity: str | None,
) -> str | None:
    if acidity is None or salinity is None:
        return None
    limit = SALINITY_PH_LIMITS.get(salinity.lower())
    if limit is None:
        return f"unknown salinity class '{salinity}'"
    if acidity > limit:
        return f"chemical imbalance: pH {acidity:.2f} exceeds {limit:.2f} for {salinity} water"
    return None


def maintenance_required(
    flow_rate: float | None,
) -> str | None:
    if flow_rate is None:
        return None
    if flow_rate < PUMP_CAPACITY:
        deficit = PUMP_CAPACITY - flow_rate
        return f"maintenance required: filter flow {flow_rate:.1f} L/h is {deficit:.1f} L/h below capacity"
    return None


def oxygen_warning(
    oxygen: float | None,
    temperature: float | None,
) -> str | None:
    if oxygen is None:
        return None
    threshold = 5.0 if temperature is None or temperature < 26.0 else 6.0
    if oxygen < threshold:
        return f"low dissolved oxygen: {oxygen:.1f} mg/L below {threshold:.1f} mg/L"
    return None


def check(readings: list[TankReading]) -> list[str]:
    alerts: list[str] = []
    for reading in readings:
        for issue in (
            chemical_imbalance(reading.acidity, reading.salinity),
            maintenance_required(reading.flow_rate),
            oxygen_warning(reading.dissolved_oxygen, reading.temperature),
        ):
            if issue is not None:
                alerts.append(f"{reading.tank_id}: {issue}")
    return alerts


def parse_reading(row: str) -> TankReading | None:
    fields = [part.strip() for part in row.split(",")]
    if not fields[0]:
        return None
    values = [field if field else None for field in fields[1:]]
    while len(values) < 5:
        values.append(None)
    acidity, salinity, temperature, flow_rate, oxygen = values[:5]
    return TankReading(
        tank_id=fields[0],
        acidity=float(acidity) if acidity is not None else None,
        salinity=salinity,
        temperature=float(temperature) if temperature is not None else None,
        flow_rate=float(flow_rate) if flow_rate is not None else None,
        dissolved_oxygen=float(oxygen) if oxygen is not None else None,
    )


def main() -> None:
    rows = [
        "Reef Dome,8.2,marine,25.4,310,6.2",
        "Kelp Wall,,,,180,",
        "Amazon Run,8.0,fresh,27.1,,4.4",
        ",,,,,",
    ]
    readings = [parsed for row in rows if (parsed := parse_reading(row)) is not None]
    for alert in check(readings):
        print(alert)


if __name__ == "__main__":
    main()

