from __future__ import annotations

from typing import Sequence

Rule = tuple[
    str,
    int | None,
    int | None,
    str | None,
    str | None,
    int | None,
]

FIELD_COUNT = 6


def _normalize(rule: Sequence[object]) -> Rule:
    if not rule:
        raise ValueError("a rule needs at least an endpoint")
    if len(rule) > FIELD_COUNT:
        raise ValueError(f"a rule has at most {FIELD_COUNT} fields, got {len(rule)}")
    fields = list(rule) + [None] * (FIELD_COUNT - len(rule))
    return (str(fields[0]), fields[1], fields[2], fields[3], fields[4], fields[5])


def find_by_endpoint(rules: Sequence[Rule], endpoint: str) -> Rule | None:
    for rule in rules:
        if rule[0] == endpoint:
            return rule
    return None


def filter_rules(
    rules: Sequence[Rule],
    max_requests: int | None = None,
    time_window: int | None = None,
    user_tier: str | None = None,
    custom_message: str | None = None,
    priority: int | None = None,
) -> list[Rule]:
    criteria = (max_requests, time_window, user_tier, custom_message, priority)
    matches: list[Rule] = []
    for rule in rules:
        if all(want is None or want == have for want, have in zip(criteria, rule[1:])):
            matches.append(rule)
    return matches


def _priority_rank(priority: int | None) -> tuple[int, int]:
    return (0, 0) if priority is None else (1, priority)


def highest_priority_rule(
    rules: Sequence[Rule],
    user_tier: str | None,
    time_window: int | None,
) -> Rule | None:
    candidates = filter_rules(rules, time_window=time_window, user_tier=user_tier)
    if not candidates:
        return None
    return max(candidates, key=lambda rule: _priority_rank(rule[5]))


def describe(rule: Rule | None) -> str:
    if rule is None:
        return "no matching rule"
    endpoint, max_requests, time_window, user_tier, custom_message, priority = rule
    limit = "unlimited" if max_requests is None else f"{max_requests} req"
    window = "any window" if time_window is None else f"{time_window}s"
    tier = user_tier or "any tier"
    text = f"{endpoint}: {limit}/{window} [{tier}]"
    if priority is not None:
        text += f" p{priority}"
    if custom_message is not None:
        text += f" -- {custom_message}"
    return text


def configure(rules):
    normalized = [_normalize(rule) for rule in rules]
    basic_minute = filter_rules(normalized, time_window=60, user_tier="basic")
    login_rule: Rule | None = find_by_endpoint(normalized, "login")
    top_basic = highest_priority_rule(normalized, "basic", None)
    return basic_minute, login_rule, top_basic


def main() -> None:
    rules = [
        ("login", 5, 60, "basic", "Too many attempts, slow down", 1),
        ("search", None, 60, "basic"),
        ("upload", 10, 3600, "premium", None, 7),
    ]
    basic_minute, login_rule, top_basic = configure(rules)
    print("basic per-minute rules:")
    for rule in basic_minute:
        print("  " + describe(rule))
    print("login rule:", describe(login_rule))
    print("top basic rule:", describe(top_basic))


if __name__ == "__main__":
    main()

