Stop = tuple[
    int,
    str | None,
    bool | None,
    str | None,
    int | None,
    int | None,
]

RouteResult = tuple[
    list[Stop],
    Stop | None,
    Stop | None,
]


def _get(stop: Stop, index: int) -> object | None:
    if index < len(stop):
        return stop[index]
    return None


def route_type(stop: Stop) -> str | None:
    return _get(stop, 1)


def accessibility(stop: Stop) -> bool | None:
    return _get(stop, 2)


def zone(stop: Stop) -> str | None:
    return _get(stop, 3)


def fare_class(stop: Stop) -> int | None:
    return _get(stop, 4)


def capacity(stop: Stop) -> int | None:
    return _get(stop, 5)


def find_stop(stops: list[Stop], stop_id: int) -> Stop | None:
    for stop in stops:
        if stop[0] == stop_id:
            return stop
    return None


def _matches(
    value: object | None,
    criterion: object | None,
) -> bool:
    return criterion is None or value == criterion


def filter_stops(
    stops: list[Stop],
    route_kind: str | None = None,
    accessible: bool | None = None,
    zone_name: str | None = None,
    fare: int | None = None,
    min_capacity: int | None = None,
) -> list[Stop]:
    selected: list[Stop] = []
    for stop in stops:
        if not _matches(route_type(stop), route_kind):
            continue
        if not _matches(accessibility(stop), accessible):
            continue
        if not _matches(zone(stop), zone_name):
            continue
        if not _matches(fare_class(stop), fare):
            continue
        if min_capacity is not None:
            seats = capacity(stop)
            if seats is None or seats < min_capacity:
                continue
        selected.append(stop)
    return selected


def cheapest_stop(
    stops: list[Stop],
    zone_name: str | None,
    route_kind: str | None,
) -> Stop | None:
    best: Stop | None = None
    best_fare: int | None = None
    for stop in filter_stops(stops, route_kind=route_kind, zone_name=zone_name):
        fare = fare_class(stop)
        if fare is None:
            continue
        if best_fare is None or fare < best_fare:
            best, best_fare = stop, fare
    return best


def describe(stop: Stop | None) -> str:
    if stop is None:
        return "no stop"
    return f"#{stop[0]} {route_type(stop) or '?'} in {zone(stop) or '?'} fare {fare_class(stop)}"


def route(stops: list[Stop]) -> RouteResult:
    downtown_buses = filter_stops(stops, route_kind="bus", zone_name="downtown")
    stop_fifty = find_stop(stops, 50)
    cheapest = cheapest_stop(stops, "downtown", "bus")
    return downtown_buses, stop_fifty, cheapest


def main() -> None:
    stops: list[Stop] = [
        (50, "bus", True, "downtown", 1, 40),
        (51, "bus", False, "downtown", 3, 55),
        (52, "tram", True, "downtown", 2, 120),
        (53, "bus", None, "uptown", 1),
        (54,),
    ]
    downtown_buses, stop_fifty, cheapest = route(stops)
    print("downtown buses:", [stop[0] for stop in downtown_buses])
    print("stop 50:", describe(stop_fifty))
    print("cheapest downtown bus:", describe(cheapest))


if __name__ == "__main__":
    main()

