from typing import NamedTuple, Sequence


class Exercise(NamedTuple):
    name: str
    muscle_group: str | None = None
    equipment: str | None = None
    duration: int | None = None
    difficulty: int | None = None
    calories: int | None = None


def to_exercise(record: Sequence) -> Exercise:
    if not record or not isinstance(record[0], str):
        raise ValueError("an exercise record must start with a string name")
    if len(record) > 6:
        raise ValueError("an exercise record has at most six fields")
    padded = list(record) + [None] * (6 - len(record))
    return Exercise(*padded)


def normalize(records: Sequence[Sequence]) -> list[Exercise]:
    return [to_exercise(record) for record in records]


def find_by_name(records: Sequence[Sequence], name: str) -> Exercise | None:
    for exercise in normalize(records):
        if exercise.name == name:
            return exercise
    return None


def filter_exercises(
    records: Sequence[Sequence],
    muscle_group: str | None = None,
    equipment: str | None = None,
    duration: int | None = None,
    difficulty: int | None = None,
    calories: int | None = None,
) -> list[Exercise]:
    selected = []
    for exercise in normalize(records):
        if muscle_group is not None and exercise.muscle_group != muscle_group:
            continue
        if equipment is not None and exercise.equipment != equipment:
