from typing import Sequence

Chemical = tuple[
    str,
    int | None,
    str | None,
    float | None,
    str | None,
    int | None,
]


def _field(chemical: Sequence, index: int):
    if index < len(chemical):
        return chemical[index]
    return None


def hazard_class_of(chemical: Chemical) -> int | None:
    return _field(chemical, 1)


def state_of(chemical: Chemical) -> str | None:
    return _field(chemical, 2)


def quantity_of(chemical: Chemical) -> float | None:
    return _field(chemical, 3)


def location_of(chemical: Chemical) -> str | None:
    return _field(chemical, 4)


def shelf_life_of(chemical: Chemical) -> int | None:
    return _field(chemical, 5)


def find_by_formula(chemicals: list[Chemical], formula: str) -> Chemical | None:
    for chemical in chemicals:
        if chemical[0] == formula:
            return chemical
    return None


def filter_chemicals(
    chemicals: list[Chemical],
    hazard_class: int | None = None,
    physical_state: str | None = None,
    min_quantity: float | None = None,
    storage_location: str | None = None,
    shelf_life: int | None = None,
) -> list[Chemical]:
    selected = []
    for chemical in chemicals:
        quantity = quantity_of(chemical)
        if hazard_class is not None and hazard_class_of(chemical) != hazard_class:
            continue
        if physical_state is not None and state_of(chemical) != physical_state:
            continue
        if min_quantity is not None and (quantity is None or quantity < min_quantity):
            continue
        if storage_location is not None and location_of(chemical) != storage_location:
            continue
        if shelf_life is not None and shelf_life_of(chemical) != shelf_life:
            continue
        selected.append(chemical)
    return selected


def most_abundant(
    chemicals: list[Chemical],
    physical_state: str,
    hazard_class: int,
) -> Chemical | None:
    best: Chemical | None = None
    for chemical in filter_chemicals(
        chemicals, hazard_class=hazard_class, physical_state=physical_state
    ):
        quantity = quantity_of(chemical)
        if quantity is None:
            continue
        best_quantity = quantity_of(best) if best is not None else None
        if best_quantity is None or quantity > best_quantity:
            best = chemical
    return best


def describe(chemical: Chemical | None) -> str:
    if chemical is None:
        return "none"
    quantity = quantity_of(chemical)
    amount = "unknown amount" if quantity is None else f"{quantity:.1f} L"
    return f"{chemical[0]} ({amount}, stored in {location_of(chemical) or 'unknown'})"


def inventory(chemicals: list[Chemical]):
    liquids = filter_chemicals(chemicals, hazard_class=3, physical_state="liquid")
    water = find_by_formula(chemicals, "water")
    largest = most_abundant(chemicals, "liquid", 3)
    return liquids, water, largest


def main() -> None:
    stock: list[Chemical] = [
        ("water", 3, "liquid", 50.0, "shelf A", 365),
        ("ethanol", 3, "liquid", 12.5, "cabinet B", 180),
        ("sodium", 4, "solid", 2.0, "vault C", None),
        ("argon", None, "gas", None, "tank D", 900),
    ]
    liquids, water, largest = inventory(stock)
    print("hazard 3 liquids:", ", ".join(describe(item) for item in liquids))
    print("water entry:", describe(water))
    print("most abundant:", describe(largest))


if __name__ == "__main__":
    main()

