from typing import Any

Actor = tuple[Any, ...]

RosterResult = tuple[
    list[Actor],
    Actor | None,
    Actor | None,
]


def _role(actor: Actor) -> str | None:
    return actor[1] if len(actor) > 1 else None


def _stage(actor: Actor) -> str | None:
    return actor[2] if len(actor) > 2 else None


def _day(actor: Actor) -> int | None:
    return actor[3] if len(actor) > 3 else None


def _tier(actor: Actor) -> str | None:
    return actor[4] if len(actor) > 4 else None


def _duration(actor: Actor) -> int | None:
    return actor[5] if len(actor) > 5 else None


def find_actor(actors: list[Actor], name: str) -> Actor | None:
    for actor in actors:
        if actor[0] == name:
            return actor
    return None


def filter_actors(
    actors: list[Actor],
    role: str | None = None,
    stage: str | None = None,
    day: int | None = None,
    tier: str | None = None,
    duration: int | None = None,
) -> list[Actor]:
    matches: list[Actor] = []
    for actor in actors:
        if role is not None and _role(actor) != role:
            continue
        if stage is not None and _stage(actor) != stage:
            continue
        if day is not None and _day(actor) != day:
            continue
        if tier is not None and _tier(actor) != tier:
            continue
        if duration is not None and _duration(actor) != duration:
            continue
        matches.append(actor)
    return matches


def longest_performer(
    actors: list[Actor],
    day: int | None,
    stage: str | None,
) -> Actor | None:
    best: Actor | None = None
    longest: int | None = None
    for actor in filter_actors(actors, day=day, stage=stage):
        span = _duration(actor)
        if span is None:
            continue
        if longest is None or span > longest:
            best, longest = actor, span
    return best


def describe(actor: Actor | None) -> str:
    if actor is None:
        return "nobody"
    parts = [str(actor[0])]
    role = _role(actor)
    if role is not None:
        parts.append(f"as {role}")
    span = _duration(actor)
    if span is not None:
        parts.append(f"for {span} min")
    return " ".join(parts)


def roster(actors: list[Actor]) -> RosterResult:
    on_main = filter_actors(actors, stage="main", day=1)
    prince = find_actor(actors, "prince")
    headliner = longest_performer(actors, 1, "main")
    return on_main, prince, headliner


def main() -> None:
    cast: list[Actor] = [
