from __future__ import annotations

Vendor = tuple[
    str,
    str | None,
    str | None,
    float | None,
    int | None,
    str | None,
]


def find_vendor(vendors: list[Vendor], name: str) -> Vendor | None:
    for vendor in vendors:
        if vendor[0].casefold() == name.casefold():
            return vendor
    return None


def _matches_text(
    value: str | None,
    wanted: str | None,
) -> bool:
    if wanted is None:
        return True
    return value is not None and value.casefold() == wanted.casefold()


def _matches_rating(
    value: float | None,
    minimum: float | None,
) -> bool:
    if minimum is None:
        return True
    return value is not None and value >= minimum


def _matches_lead_time(
    value: int | None,
    limit: int | None,
) -> bool:
    if limit is None:
        return True
    return value is not None and value <= limit


def filter_vendors(
    vendors: list[Vendor],
    region: str | None = None,
    certification: str | None = None,
    min_rating: float | None = None,
    max_lead_time: int | None = None,
    material: str | None = None,
) -> list[Vendor]:
    selected = []
    for name, vregion, vcert, vrating, vlead, vmaterial in vendors:
        if (
            _matches_text(vregion, region)
            and _matches_text(vcert, certification)
            and _matches_rating(vrating, min_rating)
            and _matches_lead_time(vlead, max_lead_time)
            and _matches_text(vmaterial, material)
        ):
            selected.append((name, vregion, vcert, vrating, vlead, vmaterial))
    return selected


def top_rated(vendors: list[Vendor], region: str, material: str) -> Vendor | None:
    best: Vendor | None = None
    for vendor in filter_vendors(vendors, region=region, material=material):
        rating = vendor[3]
        if rating is None:
            continue
        if best is None or rating > best[3]:
            best = vendor
    return best


def evaluate(vendors):
    western_steel = filter_vendors(vendors, region="west", material="steel")
    named = find_vendor(vendors, "global")
    best = top_rated(vendors, "west", "steel")
    return western_steel, named, best


def describe(vendor: Vendor | None) -> str:
    if vendor is None:
        return "none"
    rating = vendor[3]
    score = "unrated" if rating is None else f"{rating:.1f}"
    return f"{vendor[0]} ({score})"


def main() -> None:
    vendors: list[Vendor] = [
        ("global", "west", "iso9001", 5.0, 12, "steel"),
        ("northforge", "west", None, 4.2, None, "steel"),
        ("castcorp", "east", "iso9001", 4.8, 20, "steel"),
        ("alloyworks", "west", None, None, 7, "aluminium"),
    ]
    matches, named, best = evaluate(vendors)
    print("west/steel:", ", ".join(describe(vendor) for vendor in matches))
    print("by name:", describe(named))
    print("top rated:", describe(best))


if __name__ == "__main__":
    main()

