Seminar = tuple[
    str,
    str | None,
    int | None,
    str | None,
    int | None,
    str | None,
]


def _normalize(raw: tuple) -> Seminar:
    fields = list(raw) + [None] * (6 - len(raw))
    return tuple(fields[:6])


def find_by_code(
    seminars: list[tuple],
    code: str,
) -> Seminar | None:
    for seminar in map(_normalize, seminars):
        if seminar[0] == code:
            return seminar
    return None


def _matches(
    seminar: Seminar,
    subject: str | None,
    difficulty: int | None,
    prerequisite: str | None,
    duration: int | None,
    fmt: str | None,
) -> bool:
    criteria = (subject, difficulty, prerequisite, duration, fmt)
    return all(
        wanted is None or wanted == actual
        for wanted, actual in zip(criteria, seminar[1:])
    )


def filter_seminars(
    seminars: list[tuple],
    subject: str | None = None,
    difficulty: int | None = None,
    prerequisite: str | None = None,
    duration: int | None = None,
    fmt: str | None = None,
) -> list[Seminar]:
    return [
        seminar
        for seminar in map(_normalize, seminars)
        if _matches(seminar, subject, difficulty, prerequisite, duration, fmt)
    ]


def shortest_seminar(
    seminars: list[tuple],
