    species: str | None,
    habitat: str | None,
) -> Sighting | None:
    newest: Sighting | None = None
    newest_date: int | None = None
    for candidate in filter_sightings(sightings, species=species, habitat=habitat):
        moment = candidate[4]
        if moment is None:
            continue
        if newest_date is None or moment > newest_date:
            newest = candidate
            newest_date = moment
    return newest


