from typing import Sequence

Promotion = tuple[
    str,
    str | None,
    float | None,
    int | None,
    int | None,
    int | None,
]


def normalize(promotion: Sequence) -> Promotion:
    fields = list(promotion) + [None] * (6 - len(promotion))
    return (str(fields[0]), fields[1], fields[2], fields[3], fields[4], fields[5])


def find_by_code(promotions: list[Sequence], code: str) -> Promotion | None:
    for promotion in promotions:
        entry = normalize(promotion)
        if entry[0] == code:
            return entry
    return None


def matches(
    entry: Promotion,
    discount_type: str | None,
    min_spend: float | None,
    max_uses: int | None,
    start: int | None,
    end: int | None,
) -> bool:
    kind, spend, uses, begins, ends = entry[1:]
    if discount_type is not None and kind is not None and kind != discount_type:
        return False
    if min_spend is not None and spend is not None and spend > min_spend:
        return False
    if max_uses is not None and uses is not None and uses < max_uses:
        return False
    if start is not None and begins is not None and begins > start:
        return False
    if end is not None and ends is not None and ends < end:
        return False
    return True


def filter_promotions(
    promotions: list[Sequence],
    discount_type: str | None = None,
    min_spend: float | None = None,
    max_uses: int | None = None,
    start: int | None = None,
    end: int | None = None,
) -> list[Promotion]:
    found = []
    for promotion in promotions:
        entry = normalize(promotion)
        if matches(entry, discount_type, min_spend, max_uses, start, end):
            found.append(entry)
    return found


def spend_of(entry: Promotion) -> float:
    spend = entry[2]
    return 0.0 if spend is None else float(spend)


def cheapest(
    promotions: list[Sequence],
    discount_type: str | None,
    start: int | None,
) -> Promotion | None:
    best: Promotion | None = None
    for entry in filter_promotions(promotions, discount_type=discount_type, start=start):
        if best is None or spend_of(entry) < spend_of(best):
            best = entry
    return best


def describe(entry: Promotion | None) -> str:
    if entry is None:
        return "none"
    code, kind, spend, uses, begins, ends = entry
    parts = [code, kind or "any type"]
    parts.append("no minimum" if spend is None else f"min {spend:.2f}")
    if uses is not None:
        parts.append(f"up to {uses} uses")
    parts.append(f"days {begins if begins is not None else '-'}..{ends if ends is not None else '-'}")
    return ", ".join(parts)


def promote(
    promotions: list[Sequence],
) -> tuple[
    list[Promotion],
    Promotion | None,
    Promotion | None,
]:
    return (
        filter_promotions(promotions, discount_type="percentage", start=1),
        find_by_code(promotions, "save"),
        cheapest(promotions, "percentage", 1),
    )


def main() -> None:
    promotions = [
        ("save", "percentage", 10.0, None, 1, None),
        ("bulk", "fixed", 50.0, 3, 1, 9),
        ("summer", "percentage", 25.0, 5, 4, 8),
    ]
    matching, by_code, best = promote(promotions)
    print(f"percentage promotions valid on day 1: {len(matching)}")
    for entry in matching:
        print("  " + describe(entry))
    print("code 'save': " + describe(by_code))
    print("cheapest percentage on day 1: " + describe(best))


if __name__ == "__main__":
    main()

