Menu = tuple[
    str,
    int | None,
    int | None,
    str | None,
    str | None,
    int | None,
]


def find_by_name(menus: list[Menu], name: str) -> Menu | None:
    """Return the first menu with the given name, or None when absent."""
    for menu in menus:
        if menu[0] == name:
            return menu
    return None


def _matches(
    menu: Menu,
    max_calories: int | None,
    min_protein: int | None,
    diet: str | None,
    allergen: str | None,
    max_prep_time: int | None,
) -> bool:
    calories: int | None = menu[1]
    if max_calories is not None and (calories is None or calories > max_calories):
        return False
    protein: int | None = menu[2]
    if min_protein is not None and (protein is None or protein < min_protein):
        return False
    if diet is not None and menu[3] != diet:
        return False
    if allergen is not None and menu[4] != allergen:
        return False
    prep_time: int | None = menu[5]
    if max_prep_time is not None and (prep_time is None or prep_time > max_prep_time):
        return False
    return True


def filter_menus(
    menus: list[Menu],
    max_calories: int | None = None,
    min_protein: int | None = None,
    diet: str | None = None,
    allergen: str | None = None,
    max_prep_time: int | None = None,
) -> list[Menu]:
    """Keep the menus satisfying every criterion that was actually supplied."""
    return [
        menu
        for menu in menus
        if _matches(menu, max_calories, min_protein, diet, allergen, max_prep_time)
    ]


def highest_protein(
    menus: list[Menu],
    diet: str | None,
    allergen: str | None,
) -> Menu | None:
    best: Menu | None = None
    for menu in filter_menus(menus, diet=diet, allergen=allergen):
        protein = menu[2]
        if protein is None:
            continue
        best_protein: int | None = best[2] if best is not None else None
        if best_protein is None or protein > best_protein:
            best = menu
    return best


def format_menu(menu: Menu | None) -> str:
    if menu is None:
        return "no match"
    name, calories, protein, diet, allergen, prep_time = menu
    parts = [name]
    for label, value in (("kcal", calories), ("g protein", protein),
                         ("min prep", prep_time), ("", diet), ("allergen", allergen)):
        if value is not None:
            parts.append(f"{value} {label}".strip())
    return ", ".join(parts)


def filter(
    menus: list[Menu],
) -> tuple[
    list[Menu],
    Menu | None,
    Menu | None,
]:
    vegan_with_nuts = filter_menus(menus, diet="vegan", allergen="nuts")
    salad = find_by_name(menus, "salad")
    richest = highest_protein(menus, "vegan", "nuts")
    return vegan_with_nuts, salad, richest


def main() -> None:
    menus: list[Menu] = [
        ("salad", None, 20, "vegan", "nuts", None),
        ("soup", 300, 8, "vegan", None, 15),
        ("steak", 700, 45, "omnivore", None, 25),
    ]
    vegan_with_nuts, salad, richest = filter(menus)
    print("vegan menus containing nuts:")
    for menu in vegan_with_nuts:
        print("  -", format_menu(menu))
    print("salad:", format_menu(salad))
    print("highest protein:", format_menu(richest))


if __name__ == "__main__":
    main()

