import re
from dataclasses import dataclass

PREFIXES = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof."}
SUFFIXES = {"Jr.", "Sr.", "II", "III", "IV", "PhD", "MD"}
TITLES = ("Engineer", "Manager", "Developer", "Analyst", "Director", "Designer")
EMAIL_RE = re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+")
PHONE_RE = re.compile(r"\+?\d[\d\s().-]{7,}\d")
FAX_RE = re.compile(r"(?:fax|f)[:\s]+(\+?[\d\s().-]{7,}\d)", re.I)
INITIAL_RE = re.compile(r"[A-Z]\.?")


@dataclass
class Contact:
    first_name: str
    last_name: str
    middle_initial: str | None = None
    email: str | None = None
    phone: str | None = None
    company: str | None = None
    job_title: str | None = None
    prefix: str | None = None
    suffix: str | None = None
    fax: str | None = None


def extract_email(text: str) -> str | None:
    match = EMAIL_RE.search(text)
    return match.group(0) if match else None


def extract_phone(text: str) -> str | None:
    match = PHONE_RE.search(FAX_RE.sub(" ", text))
    return re.sub(r"\s+", " ", match.group(0)).strip() if match else None


def extract_middle_initial(tokens: list[str]) -> str | None:
    for token in tokens[1:-1]:
        if INITIAL_RE.fullmatch(token):
            return token[0]
    return None


def extract_fax(text: str) -> str | None:
    match = FAX_RE.search(text)
    return re.sub(r"\s+", " ", match.group(1)).strip() if match else None


def split_parts(line: str) -> list[str]:
    return [part.strip() for part in line.split(",") if part.strip()]


def extract_job_title(parts: list[str]) -> str | None:
    for extra in parts[1:]:
        if any(extra.endswith(title) for title in TITLES):
            return extra
    return None


def extract_company(parts: list[str]) -> str | None:
    company = None
    for extra in parts[1:]:
        if any(extra.endswith(title) for title in TITLES):
            continue
        if not EMAIL_RE.search(extra) and not PHONE_RE.search(extra):
            company = extra
    return company


def parse(lines: list[str]) -> list[Contact]:
    contacts = []
    for line in lines:
        parts = split_parts(line)
        tokens = parts[0].split() if parts else []
        prefix: str | None = tokens[0] if tokens and tokens[0] in PREFIXES else None
        if prefix:
            tokens = tokens[1:]
        suffix: str | None = tokens[-1] if tokens and tokens[-1] in SUFFIXES else None
        if suffix:
            tokens = tokens[:-1]
        names = [t for t in tokens if not INITIAL_RE.fullmatch(t)]
        contacts.append(Contact(
            names[0] if names else "", names[-1] if len(names) > 1 else "",
            extract_middle_initial(tokens), extract_email(line), extract_phone(line),
            extract_company(parts), extract_job_title(parts), prefix, suffix,
            extract_fax(line)))
    return contacts


def main() -> None:
    records = [
        "John Smith",
        "Dr. Alice B. Johnson Jr., Acme Corp, Senior Engineer, alice@acme.com, +1 (555) 123-4567",
        "Bob Lee, Globex, bob.lee@globex.io, 555-987-6543, fax: 555 987 0000",
    ]
    for contact in parse(records):
        print(contact)


if __name__ == "__main__":
    main()

