from __future__ import annotations

from dataclasses import dataclass
from datetime import date

NEIGHBORHOOD_AGENTS = {
    "riverside": "Dana Reyes",
    "old town": "Marcus Li",
    "hillcrest": "Priya Nair",
}
STANDARD_AGENTS = ["Tom Alvarez", "Sara Kim"]
PRIORITY_AGENT = "Elena Voss"
LUXURY_AGENT = "Grant Whitby"
GENERAL_POOL_AGENT = "Pool Desk"


@dataclass
class BuyerProfile:
    client_name: str
    contact_number: str
    neighborhood: str | None = None
    max_budget: int | None = None
    min_bedrooms: int | None = None
    min_bathrooms: int | None = None
    move_in_date: date | None = None
    preapproval: int | None = None
    sale_needed: bool | None = None
    agent: str | None = None


def priority_score(
    preapproval: int | None,
    max_budget: int | None,
) -> int | None:
    if preapproval is None or max_budget is None:
        return None
    if preapproval < 0.8 * max_budget:
        return None
    return round(preapproval / 1000)


def specialist_for(
    neighborhood: str | None,
) -> str | None:
    if neighborhood is None:
        return None
    return NEIGHBORHOOD_AGENTS.get(neighborhood.strip().lower())


def tier_agent(
    max_budget: int | None,
) -> str | None:
    if max_budget is not None and max_budget >= 1_200_000:
        return LUXURY_AGENT
    return None


def urgency_days(
    move_in_date: date | None,
    today: date,
) -> int | None:
    if move_in_date is None:
        return None
    return (move_in_date - today).days


def size_requirement(
    min_bedrooms: int | None,
    min_bathrooms: int | None,
) -> str | None:
    parts = []
    if min_bedrooms is not None:
        parts.append(f"{min_bedrooms}bd+")
    if min_bathrooms is not None:
        parts.append(f"{min_bathrooms}ba+")
    return " ".join(parts) if parts else None


def has_preferences(profile: BuyerProfile) -> bool:
    return any(
        value is not None
        for value in (
            profile.neighborhood,
            profile.max_budget,
            profile.min_bedrooms,
            profile.min_bathrooms,
            profile.move_in_date,
            profile.preapproval,
            profile.sale_needed,
            profile.agent,
        )
    )


def assign(profiles: list[BuyerProfile]) -> list[str]:
    assigned: list[str] = []
    rotation = 0
    for profile in profiles:
        if not profile.client_name or not profile.contact_number:
            raise ValueError("every buyer profile needs a name and contact number")
        chosen: str | None = profile.agent
        if chosen is None:
            if priority_score(profile.preapproval, profile.max_budget) is not None:
                chosen = PRIORITY_AGENT
            elif not has_preferences(profile):
                chosen = GENERAL_POOL_AGENT
            else:
                chosen = specialist_for(profile.neighborhood)
        if chosen is None:
            chosen = tier_agent(profile.max_budget)
        if chosen is None:
            chosen = STANDARD_AGENTS[rotation % len(STANDARD_AGENTS)]
            rotation += 1
        profile.agent = chosen
        assigned.append(chosen)
    return assigned


def describe(profile: BuyerProfile, today: date) -> str:
    parts = [f"{profile.client_name} ({profile.contact_number})"]
    days: int | None = urgency_days(profile.move_in_date, today)
    if days is not None:
        parts.append(f"moves in {days} days")
    size = size_requirement(profile.min_bedrooms, profile.min_bathrooms)
    if size is not None:
        parts.append(size)
    score = priority_score(profile.preapproval, profile.max_budget)
    if score is not None:
        parts.append(f"priority {score}k")
    if profile.sale_needed:
        parts.append("must sell current home")
    return " | ".join(parts)


def main() -> None:
    today = date(2024, 5, 1)
    profiles = [
        BuyerProfile("Ana Duarte", "555-0100", neighborhood="Riverside", min_bedrooms=3),
        BuyerProfile("Ben Osei", "555-0111", max_budget=400_000, preapproval=380_000),
        BuyerProfile("Cara Nguyen", "555-0122"),
        BuyerProfile(
            "Dmitri Park",
            "555-0133",
            max_budget=1_500_000,
            move_in_date=date(2024, 8, 15),
            min_bathrooms=3,
        ),
        BuyerProfile("Efua Mensah", "555-0144", sale_needed=True, min_bedrooms=2),
    ]
    for profile, agent in zip(profiles, assign(profiles)):
        print(f"{describe(profile, today)} -> {agent}")


if __name__ == "__main__":
    main()

