from __future__ import annotations

import datetime
from dataclasses import dataclass
from typing import Optional

BASE_RATES = {"economy": 39.0, "midsize": 52.0, "suv": 78.0, "luxury": 129.0}
INSURANCE_TIERS = {"basic": 12.0, "standard": 21.0, "premium": 35.0}
PROMOTIONS = {"SPRING10": 0.10, "WEEKEND5": 0.05}


@dataclass
class RentalRequest:
    pickup_date: str
    vehicle_class: str
    child_seats: Optional[int] = None
    gps_requested: Optional[bool] = None
    additional_driver: Optional[str] = None
    loyalty_account: Optional[str] = None
    promo_code: Optional[str] = None
    flight_number: Optional[str] = None
    dropoff_location: Optional[str] = None
    insurance_tier: Optional[str] = None


def parse_pickup_date(value: str) -> datetime.date:
    try:
        return datetime.date.fromisoformat(value)
    except ValueError:
        raise ValueError(f"invalid pickup date: {value!r}") from None


def child_seat_fee(
    count: Optional[int],
) -> Optional[float]:
    if count is None:
        return None
    if count < 0 or count > 3:
        raise ValueError("child seat count must be between 0 and 3")
    return 9.5 * count if count else None


def gps_fee(
    requested: Optional[bool],
) -> Optional[float]:
    return 14.0 if requested else None


def additional_driver_fee(
    name: Optional[str],
) -> Optional[float]:
    if name is None:
        return None
    if not name.strip():
        raise ValueError("additional driver name must not be blank")
    return 17.0


def insurance_fee(tier: Optional[str]) -> float:
    if tier is None:
        return 0.0
    try:
        return INSURANCE_TIERS[tier.lower()]
    except KeyError:
        raise ValueError(f"unknown insurance tier: {tier!r}") from None


def airport_pickup_fee(flight_number: Optional[str]) -> float:
    return 22.0 if flight_number else 0.0


def one_way_fee(location: Optional[str]) -> float:
    return 45.0 if location else 0.0


def promo_discount(code: Optional[str], subtotal: float) -> float:
    if code is None:
        return 0.0
    rate = PROMOTIONS.get(code.upper())
    if rate is None:
        raise ValueError(f"unknown promotion code: {code!r}")
    return subtotal * rate


def loyalty_discount(account: Optional[str], subtotal: float) -> float:
    if account is None:
        return 0.0
    if not account.isdigit() or len(account) != 8:
        raise ValueError("loyalty account number must be 8 digits")
    return subtotal * 0.03


def validate(requests):
    totals = []
    for request in requests:
        parse_pickup_date(request.pickup_date)
        rate: Optional[float] = BASE_RATES.get(request.vehicle_class.lower())
        if rate is None:
            raise ValueError(f"unknown vehicle class: {request.vehicle_class!r}")
        total = rate
        add_ons = (
            child_seat_fee(request.child_seats),
            gps_fee(request.gps_requested),
            additional_driver_fee(request.additional_driver),
        )
        for fee in add_ons:
            if fee is not None:
                total += fee
        total += insurance_fee(request.insurance_tier)
        total += airport_pickup_fee(request.flight_number)
        total += one_way_fee(request.dropoff_location)
        total -= promo_discount(request.promo_code, total)
        total -= loyalty_discount(request.loyalty_account, total)
        totals.append(round(total, 2))
    return totals


def dropoff_note(
    location: Optional[str],
) -> Optional[str]:
    if location is None:
        return None
    return f"one-way to {location.title()}"


def format_receipt(request: RentalRequest, total: float) -> str:
    note = dropoff_note(request.dropoff_location)
    suffix = f" [{note}]" if note else ""
    return f"{request.pickup_date} {request.vehicle_class:<8} ${total:>8.2f}{suffix}"


def main() -> None:
    requests = [
        RentalRequest("2026-04-11", "economy"),
        RentalRequest("2026-04-12", "suv", child_seats=2, gps_requested=True),
        RentalRequest(
            "2026-04-15",
            "luxury",
            additional_driver="Dana Reyes",
            loyalty_account="10029384",
            promo_code="spring10",
            flight_number="LH414",
            dropoff_location="denver",
            insurance_tier="premium",
        ),
    ]
    for request, total in zip(requests, validate(requests)):
        print(format_receipt(request, total))


if __name__ == "__main__":
    main()

