from dataclasses import dataclass

ROLE_BUDGETS = {"backend engineer": 120000, "designer": 95000, "data analyst": 90000}
SPONSORED_ROLES = {"backend engineer", "data analyst"}
CURRENT_YEAR, MAX_NOTICE_WEEKS, PASS_SCORE = 2025, 12, 3

@dataclass
class Application:
    name: str
    role: str
    network_profile: str | None = None
    portfolio: str | None = None
    cover_letter: str | None = None
    referral: str | None = None
    needs_visa: bool | None = None
    graduation_year: int | None = None
    notice_weeks: int | None = None
    salary_expectation: int | None = None

def role_budget(role: str) -> int | None:
    return ROLE_BUDGETS.get(role.strip().lower())

def portfolio_score(
    url: str | None,
) -> int | None:
    if url is None:
        return None
    return 2 if url.strip().startswith(("http://", "https://")) else 0

def referral_score(
    employee: str | None,
) -> int | None:
    if employee is None:
        return None
    return 3 if employee.strip() else 0

def graduation_score(
    year: int | None,
) -> int | None:
    if year is None:
        return None
    experience = CURRENT_YEAR - year
    return 0 if experience < 0 else (2 if experience >= 5 else 1)

def bonus_total(app: Application) -> int:
    rules = [
        portfolio_score(app.portfolio),
        referral_score(app.referral),
        graduation_score(app.graduation_year),
    ]
    return sum(score for score in rules if score is not None)

def blocking_reason(app: Application) -> str | None:
    budget = role_budget(app.role)
    if budget is None:
        return f"no open role matching {app.role!r}"
    if app.salary_expectation is not None and app.salary_expectation > budget:
        return f"salary expectation above {budget} budget"
    if app.notice_weeks is not None and app.notice_weeks > MAX_NOTICE_WEEKS:
        return f"notice period of {app.notice_weeks} weeks too long"
    if app.needs_visa and app.role.strip().lower() not in SPONSORED_ROLES:
        return "visa sponsorship unavailable for this role"
    return None

def screen(applications: list[Application]) -> list[bool]:
    return [blocking_reason(a) is None and bonus_total(a) >= PASS_SCORE for a in applications]

def main() -> None:
    applications = [
        Application("Ada Nkemdi", "Backend Engineer", portfolio="https://ada.dev", graduation_year=2016),
        Application("Tom Rye", "Designer"),
        Application("Mira Sol", "Designer", portfolio="mira-sol-folio", referral="Ada Nkemdi", graduation_year=2023),
        Application("Kai Otsu", "Designer", needs_visa=True, referral="Tom Rye"),
    ]
    for app, passed in zip(applications, screen(applications)):
        reason: str | None = blocking_reason(app)
        verdict = "PASS" if passed else (reason or f"bonus score {bonus_total(app)} too low")
        print(f"{app.name} ({app.role}): {verdict}")

if __name__ == "__main__":
    main()

