        return "organization name is missing"
    if app.requested_amount <= 0:
        return "requested amount must be positive"
    return None


def compliance_id(
    tax_exempt_id: Optional[str],
) -> Optional[str]:
    if tax_exempt_id is None:
        return None
    return tax_exempt_id.replace("-", "").strip().upper() or None


def historical_score(
    previous_grant_year: Optional[int],
    matched_funds: Optional[float],
) -> Optional[int]:
    if previous_grant_year is None and matched_funds is None:
        return None
    recency = 0 if previous_grant_year is None else (previous_grant_year - 2015) * 5
    leverage = 0 if matched_funds is None else int(matched_funds // 1000)
    return min(40, max(0, recency)) + min(40, leverage)


def evaluate(applications: list[Application]) -> list[str]:
    statuses: list[str] = []
    for app in applications:
        problem = validate(app)
        if problem is not None:
            statuses.append(f"{app.organization or '<unnamed>'}: rejected ({problem})")
            continue
        details = sum(value is not None for value in (app.tax_exempt_id, app.partner_organization,
                      app.previous_grant_year, app.matched_funds, app.project_website,
                      app.evaluation_plan, app.video_pitch, app.board_members))
        if not details:
            statuses.append(f"{app.organization}: pending - more information requested")
            continue
        history = historical_score(app.previous_grant_year, app.matched_funds)
        points = 5 * details + (history or 0)
        if app.board_members is not None and len(app.board_members) >= 5:
            points += 10
        if compliance_id(app.tax_exempt_id) is None:
            statuses.append(f"{app.organization}: conditional - tax exempt proof needed")
        elif points >= 70 and app.evaluation_plan is not None:
            statuses.append(f"{app.organization}: approved (score {points})")
        else:
            statuses.append(f"{app.organization}: conditional (score {points})")
    return statuses


if __name__ == "__main__":
    grants = [
        Application("Riverside Literacy", 25000, tax_exempt_id="12-3456789", matched_funds=9000,
                    previous_grant_year=2022, evaluation_plan="Quarterly reading assessments",
                    board_members=["A. Ng", "B. Cole", "C. Diaz", "D. Ruiz", "E. Park"]),
        Application("Harbor Youth Arts", 12000),
        Application("", 5000),
    ]
    for status in evaluate(grants):
        print(status)

