) -> float | None:
    if police_report is None and dashcam_link is None:
        return None
    modifier = 1.0
    if police_report is not None:
        modifier += 0.15 if police_report.upper().startswith("PR") else 0.05
    if dashcam_link is not None:
        modifier += 0.20 if dashcam_link.startswith("http") else 0.10
    return modifier


def base_amount(
    repair_estimate: float | None,
) -> float | None:
    if repair_estimate is None or repair_estimate <= 0:
        return None
    return min(repair_estimate, 25000.0)


def contact_digits(
    witness_phone: str | None,
) -> str | None:
    if witness_phone is None:
        return None
    digits = "".join(ch for ch in witness_phone if ch.isdigit())
    return digits if len(digits) >= 7 else None


def witness_bonus(
    witness_name: str | None,
    witness_phone: str | None,
) -> float:
    if witness_name is None:
        return 0.0
    return 250.0 if contact_digits(witness_phone) is not None else 150.0


def medical_uplift(medical_summary: str | None, base: float) -> float:
    if medical_summary is None:
        return 0.0
    severe = any(word in medical_summary.lower() for word in ("fracture", "surgery"))
    return base * (0.35 if severe else 0.15)


def salvage_offset(salvage_yard: str | None, base: float) -> float:
    return base * 0.10 if salvage_yard is not None else 0.0


def third_party_share(third_party_insurer: str | None) -> float:
    return 0.60 if third_party_insurer is not None else 1.0


def adjust(claims):
    payouts = []
    for claim in claims:
        base = base_amount(claim.repair_estimate)
        amount = MINIMUM_PAYOUT if base is None else base
        modifier = fault_modifier(claim.police_report, claim.dashcam_link)
        if modifier is not None:
            amount *= modifier
        amount += witness_bonus(claim.witness_name, claim.witness_phone)
        amount += medical_uplift(claim.medical_summary, amount)
        amount -= salvage_offset(claim.salvage_yard, amount)
        amount *= third_party_share(claim.third_party_insurer)
        payouts.append(round(max(amount, MINIMUM_PAYOUT), 2))
    return payouts


