        Claim("Lena Fox", "2024-05-20", police_report="INT-4",
              repair_estimate=9500.0, medical_summary="Wrist fracture, cast fitted",
              salvage_yard="Bay Area Salvage"),
        Claim("Omar Said", "2024-06-01"),
    ]
    for claim, payout in zip(claims, adjust(claims)):
        modifier = fault_modifier(claim.police_report, claim.dashcam_link)
        print(format_summary(claim.policyholder, payout, modifier))


if __name__ == "__main__":
