from dataclasses import dataclass


@dataclass
class Booking:
    guest_name: str
    party_size: int
    hotel_pickup: str | None = None
    dietary_needs: str | None = None
    language: str | None = None
    mobility_notes: str | None = None
    discount_code: str | None = None
    agent_id: str | None = None
    flight_time: str | None = None
    emergency_phone: str | None = None


def schedule_transport(
    hotel_pickup: str | None,
    mobility_notes: str | None,
) -> str | None:
    if mobility_notes is not None:
        return "lift-equipped van"
    if hotel_pickup is not None:
        return "hotel shuttle"
    return None


def meeting_point(hotel_pickup: str | None) -> str:
    if hotel_pickup is None:
        return "Central Plaza kiosk"
    return f"{hotel_pickup} lobby"


def parse_flight_time(
    flight_time: str | None,
) -> int | None:
    if flight_time is None:
        return None
    hours, _, minutes = flight_time.partition(":")
    return int(hours) * 60 + int(minutes)


def pickup_deadline(
    flight_minutes: int | None,
) -> str | None:
    if flight_minutes is None:
        return None
    latest = max(flight_minutes - 180, 0)
    return f"{latest // 60:02d}:{latest % 60:02d}"


def discount_rate(discount_code: str | None) -> float:
    if discount_code is None:
        return 0.0
    return {"SPRING10": 0.10, "CITY25": 0.25}.get(discount_code.upper(), 0.05)


def contact_note(
    emergency_phone: str | None,
    agent_id: str | None,
) -> str:
    parts = []
    if emergency_phone is not None:
        parts.append(f"emergency {emergency_phone}")
    if agent_id is not None:
        parts.append(f"agent {agent_id}")
    return "; ".join(parts) if parts else "no extra contacts"


def describe_care(
    dietary_needs: str | None,
    language: str | None,
) -> str:
    diet = dietary_needs if dietary_needs is not None else "no dietary notes"
    speech = language if language is not None else "English"
    return f"{diet} / guide language {speech}"


def manifest_line(booking: Booking) -> str:
    if booking.party_size < 1:
        raise ValueError(f"invalid party size for {booking.guest_name}")
    transport = schedule_transport(booking.hotel_pickup, booking.mobility_notes)
    deadline = pickup_deadline(parse_flight_time(booking.flight_time))
    rate = discount_rate(booking.discount_code)
    line = (
        f"{booking.guest_name} (x{booking.party_size}) | "
        f"{meeting_point(booking.hotel_pickup)} | "
        f"{transport or 'standard coach'} | "
        f"{describe_care(booking.dietary_needs, booking.language)} | "
        f"discount {rate:.0%} | "
        f"{contact_note(booking.emergency_phone, booking.agent_id)}"
    )
    if deadline is not None:
        line += f" | must depart tour by {deadline}"
    return line


def organize(bookings: list[Booking]) -> list[str]:
    ordered = sorted(bookings, key=lambda b: (-b.party_size, b.guest_name))
    return [manifest_line(booking) for booking in ordered]


def main() -> None:
    bookings = [
        Booking("Ana Ruiz", 2),
        Booking(
            "Tomas Kelly",
            4,
            hotel_pickup="Grand Riverside",
            dietary_needs="two vegetarian meals",
            language="Spanish",
            discount_code="city25",
            flight_time="19:45",
        ),
        Booking(
            "Mei Lin",
            1,
            mobility_notes="folding wheelchair",
            agent_id="AGT-77",
            emergency_phone="+1-555-0142",
        ),
    ]
    for entry in organize(bookings):
        print(entry)


if __name__ == "__main__":
    main()

