from dataclasses import dataclass

@dataclass
class Container:
    weight: float
    destination: str
    hazmat_class: str | None = None
    reefer_temp: float | None = None
    broker: str | None = None
    port_of_entry: str | None = None
    seal_number: str | None = None
    size_ft: int | None = None
    overweight_permit: str | None = None
    delivery_window: tuple[str, str] | None = None

def hazmat_clearance(
    hazmat_class: str | None,
) -> str | None:
    if hazmat_class is None:
        return None
    normalized = hazmat_class.strip().upper()
    return None if normalized in {"1", "7"} else "HZ-" + normalized

def broker_clearance(
    broker: str | None,
    port_of_entry: str | None,
) -> str | None:
    if broker is None:
        return None
    initials = "".join(word[0] for word in broker.split() if word).upper()
    entry = "" if port_of_entry is None else "-" + port_of_entry.strip().upper()[:3]
    return "BR-" + initials + entry

def permit_required(weight: float, size_ft: int | None) -> bool:
    limit = 30000.0 if size_ft is None or size_ft <= 20 else 45000.0
    return weight > limit

def seal_tier(seal_number: str | None) -> int:
    return 0 if seal_number is None else (2 if len(seal_number) >= 8 else 1)

def window_priority(start: str, end: str) -> int:
    return 1 if start[:2] == end[:2] else 2

def zone_for(container: Container) -> str:
    hazmat = hazmat_clearance(container.hazmat_class)
    if container.hazmat_class is not None and hazmat is None:
        return "REJECT"
    if permit_required(container.weight, container.size_ft):
        permit = container.overweight_permit
        return "DECK-H" + permit[-2:] if permit else "HOLD-WEIGHT"
    if container.reefer_temp is not None:
        return "REEFER-{:+.0f}".format(container.reefer_temp)
    if hazmat is not None:
        return "DECK-TOP-" + hazmat
    broker = broker_clearance(container.broker, container.port_of_entry)
    if broker is not None:
        return "DECK-MID-{}-{}".format(broker, seal_tier(container.seal_number))
    window = container.delivery_window
    if window is not None:
        return "DECK-UPPER-P{}".format(window_priority(*window))
    if container.seal_number is not None or container.size_ft is not None:
        return "DECK-MID-{}".format(seal_tier(container.seal_number))
    return "DECK-LOWER-STD"

def plan(containers: list[Container]) -> list[str]:
    return [zone_for(container) for container in containers]

def main() -> None:
    manifest = [
        Container(12000.0, "Rotterdam"),
        Container(48000.0, "Singapore", size_ft=40, overweight_permit="OW-1147"),
        Container(9800.0, "Oslo", reefer_temp=-18.0),
        Container(15000.0, "Lagos", hazmat_class="3", seal_number="SL-99120"),
        Container(20000.0, "Houston", broker="Ana Maria Ruiz", port_of_entry="Galveston"),
        Container(5000.0, "Kobe", delivery_window=("08:00", "11:30")),
    ]
    for container, zone in zip(manifest, plan(manifest)):
        print("{:<10} {:>9.0f} kg -> {}".format(container.destination, container.weight, zone))

if __name__ == "__main__":
    main()

