from __future__ import annotations

import base64
import hashlib
import hmac
from dataclasses import dataclass
from datetime import date, timedelta
from typing import Sequence

SIGNING_SECRET = b"acme-license-authority-v3"
EDITIONS = {"standard": "STD", "professional": "PRO", "enterprise": "ENT"}
TIER_RANKS = {"bronze": 1, "silver": 2, "gold": 3, "platinum": 4}


@dataclass
class LicenseRequest:
    email: str
    edition: str
    hardware_id: str | None = None
    expires_on: date | None = None
    max_users: int | None = None
    support_tier: str | None = None
    features: Sequence[str] | None = None
    reseller_id: str | None = None
    trial_days: int | None = None
    region: str | None = None


def effective_expiry(
    expires_on: date | None,
    trial_days: int | None,
) -> date | None:
    if trial_days is None:
        return expires_on
    base = expires_on if expires_on is not None else date.today()
    return base + timedelta(days=trial_days)


def limit_payload(
    expiry: date | None,
    max_users: int | None,
) -> str | None:
    parts = []
    if expiry is not None:
        parts.append("exp=" + expiry.isoformat())
    if max_users is not None:
        parts.append(f"seats={max_users}")
    if not parts:
        return None
    return ";".join(parts)


def tier_rank(support_tier: str | None) -> int:
    if support_tier is None:
        return 0
    return TIER_RANKS[support_tier.lower()]


def encode_features(features: Sequence[str] | None) -> str:
    if features is None:
        return "base"
    return "+".join(sorted(f.strip().lower() for f in features))


def bind_tag(hardware_id: str | None) -> str:
    if hardware_id is None:
        return "any"
    return hashlib.sha256(hardware_id.encode()).hexdigest()[:8]


def scope_tag(
    region: str | None,
    reseller_id: str | None,
) -> str:
    return f"{region or 'global'}/{reseller_id or 'direct'}"


def build_claims(request: LicenseRequest) -> str:
    if "@" not in request.email:
        raise ValueError(f"invalid customer email: {request.email!r}")
    code = EDITIONS[request.edition.lower()]
    expiry = effective_expiry(request.expires_on, request.trial_days)
    limits = limit_payload(expiry, request.max_users)
    claims = [
        f"ed={code}",
        f"cu={request.email.strip().lower()}",
        f"hw={bind_tag(request.hardware_id)}",
        f"ft={encode_features(request.features)}",
        f"tr={tier_rank(request.support_tier)}",
        f"sc={scope_tag(request.region, request.reseller_id)}",
        f"lm={limits if limits is not None else 'perpetual'}",
    ]
    return "|".join(claims)


def encrypt_claims(claims: str) -> str:
    digest = hmac.new(SIGNING_SECRET, claims.encode(), hashlib.sha256).digest()
    keystream = hashlib.sha256(SIGNING_SECRET + digest[:8]).digest()
    payload = bytes(b ^ keystream[i % len(keystream)] for i, b in enumerate(claims.encode()))
    blob = base64.b32encode(digest[:5] + payload).decode().rstrip("=")
    return "-".join(blob[i:i + 5] for i in range(0, len(blob), 5))


def generate(requests: Sequence[LicenseRequest]) -> list[str]:
    return [encrypt_claims(build_claims(request)) for request in requests]


def main() -> None:
    batch = [
        LicenseRequest(email="ada@example.com", edition="standard"),
        LicenseRequest(
            email="grace@navy.mil",
            edition="enterprise",
            hardware_id="MB-77-AC-01",
            expires_on=date(2026, 12, 31),
            max_users=250,
            support_tier="platinum",
            features=["clustering", "SSO", "audit"],
            reseller_id="RSL-4471",
            region="eu-central",
        ),
        LicenseRequest(
            email="trial.user@startup.io",
            edition="professional",
            trial_days=30,
            max_users=5,
        ),
    ]
    for request, key in zip(batch, generate(batch)):
        print(f"{request.email:<24} {request.edition:<12} {key}")


if __name__ == "__main__":
    main()

