from dataclasses import dataclass


@dataclass
class Submission:
    title: str
    primary_author: str
    artifact_url: str | None = None
    dataset_repo: str | None = None
    code_repo: str | None = None
    funding_statement: str | None = None
    appendix_pdf: str | None = None
    rebuttal_text: str | None = None
    presentation_format: str | None = None
    student_author: bool | None = None


def normalize(
    value: str | None,
) -> str | None:
    if value is None:
        return None
    return value.strip() or None


def dataset_points(
    dataset_repo: str | None,
) -> int | None:
    repo = normalize(dataset_repo)
    if repo is None:
        return None
    return 4 if repo.startswith("https://") else 2


def code_points(
    code_repo: str | None,
) -> int | None:
    repo = normalize(code_repo)
    if repo is None:
        return None
    return 5 if "git" in repo.lower() else 3


def reproducibility_bonus(
    dataset_repo: str | None,
    code_repo: str | None,
) -> int | None:
    data = dataset_points(dataset_repo)
    code = code_points(code_repo)
    if data is None and code is None:
        return None
    total = (data or 0) + (code or 0)
    if data is not None and code is not None:
        total += 3
    return total


def artifact_points(
    artifact_url: str | None,
) -> int | None:
    url = normalize(artifact_url)
    if url is None:
        return None
    return 3 if url.startswith(("http://", "https://")) else 1


def appendix_points(
    appendix_pdf: str | None,
) -> int | None:
    document = normalize(appendix_pdf)
    if document is None:
        return None
    return 2 if document.lower().endswith(".pdf") else 1


def rebuttal_points(
    rebuttal_text: str | None,
) -> int | None:
    text = normalize(rebuttal_text)
    if text is None:
        return None
    return min(4, len(text.split()) // 20 + 1)


def disclosure_points(funding_statement: str | None) -> int:
    return 2 if normalize(funding_statement) else 0


def format_points(presentation_format: str | None) -> int:
    preferred = normalize(presentation_format)
    if preferred is None:
        return 0
    return {"talk": 2, "poster": 1, "demo": 3}.get(preferred.lower(), 0)


def student_points(student_author: bool | None) -> int:
    return 1 if student_author else 0


def baseline_score(title: str, primary_author: str) -> int:
    if not title.strip() or not primary_author.strip():
        raise ValueError("title and primary author are required")
    return 10 + min(5, len(title.split()))


def score_submission(submission: Submission) -> int:
    total = baseline_score(submission.title, submission.primary_author)
    total += artifact_points(submission.artifact_url) or 0
    total += reproducibility_bonus(submission.dataset_repo, submission.code_repo) or 0
    total += disclosure_points(submission.funding_statement)
    total += appendix_points(submission.appendix_pdf) or 0
    total += rebuttal_points(submission.rebuttal_text) or 0
    total += format_points(submission.presentation_format)
    total += student_points(submission.student_author)
    return total


def score(submissions: list[Submission]) -> list[int]:
    return [score_submission(submission) for submission in submissions]


def main() -> None:
    submissions = [
        Submission("Fast Sparse Attention Kernels", "R. Alvarez"),
        Submission(
            "Reproducible Federated Benchmarks",
            "L. Chen",
            artifact_url="https://artifacts.example.org/fed.zip",
            dataset_repo="https://data.example.org/fedbench",
            code_repo="https://github.com/example/fedbench",
            funding_statement="Funded by the Open Compute Foundation.",
            appendix_pdf="appendix_fedbench.pdf",
            presentation_format="demo",
            student_author=True,
        ),
        Submission(
            "On Cache Aware Graph Traversal",
            "M. Okafor",
            code_repo="svn://internal.example.net/traversal",
            rebuttal_text=" ".join(["clarification"] * 45),
            presentation_format="Poster",
        ),
    ]
    for submission, value in zip(submissions, score(submissions)):
        print(f"{value:3d}  {submission.title} ({submission.primary_author})")


if __name__ == "__main__":
    main()

