from dataclasses import dataclass

STANDARD_START_LIMIT = 1000.0
PROMO_MULTIPLIERS = {"INTRO0": 1.15, "FLEX9": 1.05, "PLAT12": 1.20}


@dataclass
class Application:
    legal_name: str
    annual_income: float
    middle_name: str | None = None
    previous_address: str | None = None
    employer_phone: str | None = None
    secondary_income: float | None = None
    coapplicant_name: str | None = None
    coapplicant_income: float | None = None
    balance_transfer: float | None = None
    promo_rate_code: str | None = None


def secondary_income_limit(
    secondary_income: float | None,
) -> float | None:
    return None if secondary_income is None or secondary_income < 2000 else secondary_income * 0.20


def coapplicant_limit(
    coapplicant_name: str | None,
    coapplicant_income: float,
) -> float | None:
    if coapplicant_name is None or coapplicant_income < 12000:
        return None
    return coapplicant_income * 0.15


def debt_capacity(app: Application) -> float | None:
    granted = [amount for amount in (secondary_income_limit(app.secondary_income),
                                     coapplicant_limit(app.coapplicant_name,
                                                       app.coapplicant_income or 0.0))
               if amount is not None]
    return sum(granted) if granted else None


def transfer_cushion(
    balance_transfer: float | None,
) -> float | None:
    return None if balance_transfer is None else balance_transfer * 1.10


def residency_bonus(
    previous_address: str | None,
    employer_phone: str | None,
) -> float:
    bonus = 500.0 if previous_address else 0.0
    return bonus + (750.0 if employer_phone else 0.0)


def underwrite(applications: list[Application]) -> list[int]:
    limits: list[int] = []
    for app in applications:
        optional = (app.middle_name, app.previous_address, app.employer_phone, app.secondary_income,
                    app.coapplicant_name, app.coapplicant_income, app.balance_transfer, app.promo_rate_code)
        if all(field is None for field in optional):
            limits.append(int(round(min(STANDARD_START_LIMIT, app.annual_income * 0.10))))
            continue
        limit = app.annual_income * 0.30 + residency_bonus(app.previous_address, app.employer_phone)
        extra = debt_capacity(app)
        if extra is not None:
            limit += extra
        limit *= PROMO_MULTIPLIERS.get(app.promo_rate_code or "", 1.0)
        cushion = transfer_cushion(app.balance_transfer)
        if cushion is not None:
            limit = max(limit, cushion)
        limits.append(int(round(limit / 100.0) * 100))
    return limits


def main() -> None:
    applications = [
        Application("Dana Reyes", 64000),
        Application("Samir Patel", 88000, middle_name="Ali", secondary_income=9000, promo_rate_code="INTRO0"),
        Application("Lena Osei", 52000, previous_address="8 Alder Rd", employer_phone="555-0142",
                    coapplicant_name="Kofi Osei", coapplicant_income=41000, balance_transfer=18000),
    ]
    for app, limit in zip(applications, underwrite(applications)):
        print(f"{app.legal_name}: approved limit ${limit:,}")


if __name__ == "__main__":
    main()

