from dataclasses import dataclass

DEFAULT_MEAL = "chicken"
SHUTTLE_DELAY_MINUTES = 45


@dataclass
class Rsvp:
    guest_name: str
    attending: bool
    plus_one: str | None = None
    meal: str | None = None
    dietary_notes: str | None = None
    arrival_flight: str | None = None
    departure_flight: str | None = None
    song_request: str | None = None
    hotel_block: str | None = None
    welcome_dinner: bool | None = None


def _flight_clock(flight: str) -> str | None:
    tokens = flight.split()
    return tokens[-1] if len(tokens) > 1 else None


def _parse_minutes(
    clock: str | None,
) -> int | None:
    if clock is None:
        return None
    hours, _, minutes = clock.partition(":")
    if not (hours.isdigit() and minutes.isdigit()):
        return None
    return int(hours) * 60 + int(minutes)


def shuttle_time(
    arrival_flight: str | None,
    hotel_block: str | None,
) -> str | None:
    if arrival_flight is None or hotel_block is None:
        return None
    landing = _parse_minutes(_flight_clock(arrival_flight))
    if landing is None:
        return None
    pickup = (landing + SHUTTLE_DELAY_MINUTES) % (24 * 60)
    return f"{pickup // 60:02d}:{pickup % 60:02d}"


def departure_note(
    guest_name: str,
    departure_flight: str | None,
) -> str | None:
