    song_request: Optional[str] = None
    hotel_block: Optional[str] = None
    welcome_dinner: Optional[bool] = None


def _flight_clock(flight: str) -> Optional[str]:
    tokens = flight.split()
    return tokens[-1] if len(tokens) > 1 else None


def _parse_minutes(
    clock: Optional[str],
) -> Optional[int]:
    if clock is None:
        return None
    hours, _, minutes = clock.partition(":")
    if not (hours.isdigit() and minutes.isdigit()):
        return None
    return int(hours) * 60 + int(minutes)


