from dataclasses import dataclass

SECTION_PRICES = {"floor": 180.0, "lower": 120.0, "upper": 75.0, "lawn": 45.0}


@dataclass
class Ticket:
    holder: str
    section: str
    vip_lounge: bool | None = None
    backstage: bool | None = None
    parking: bool | None = None
    merch_voucher: float | None = None
    drink_tickets: int | None = None
    meet_greet: str | None = None
    expedited_entrance: bool | None = None
    lanyard: bool | None = None


def as_flag(value: object) -> bool | None:
    return None if value is None else bool(value)


def as_amount(value: object) -> float | None:
    if value is None:
        return None
    if not isinstance(value, (int, float)):
        raise ValueError(f"expected a number, got {value!r}")
    return float(value)


def as_count(value: object) -> int | None:
    if value is None:
        return None
    if not isinstance(value, int) or value < 0:
        raise ValueError(f"expected a non-negative count, got {value!r}")
    return value


def as_slot(value: object) -> str | None:
    if value is None:
        return None
    if not isinstance(value, str) or ":" not in value:
        raise ValueError(f"expected a HH:MM meet-and-greet time, got {value!r}")
    return value


def parse_ticket(record: dict) -> Ticket:
    holder = record.get("holder")
    section = record.get("section")
    if not isinstance(holder, str) or not holder.strip():
        raise ValueError("every ticket needs a holder name")
    if not isinstance(section, str) or section.lower() not in SECTION_PRICES:
        raise ValueError(f"unknown section {section!r}")
    return Ticket(
        holder=holder.strip(),
        section=section.lower(),
        vip_lounge=as_flag(record.get("vip_lounge")),
        backstage=as_flag(record.get("backstage")),
        parking=as_flag(record.get("parking")),
        merch_voucher=as_amount(record.get("merch_voucher")),
        drink_tickets=as_count(record.get("drink_tickets")),
        meet_greet=as_slot(record.get("meet_greet")),
        expedited_entrance=as_flag(record.get("expedited_entrance")),
        lanyard=as_flag(record.get("lanyard")),
    )


def slot_hour(
    slot: str | None,
) -> int | None:
    if slot is None:
        return None
    hour, _, minute = slot.partition(":")
    return int(hour) + (1 if int(minute) >= 30 else 0)


def backstage_fee(
    backstage: bool | None,
) -> float | None:
    return 95.0 if backstage else None


def meet_greet_fee(
    slot: str | None,
) -> float | None:
    hour = slot_hour(slot)
    if hour is None:
        return None
    return 140.0 if hour < 18 else 110.0


def package_fee(
    backstage: bool | None,
    slot: str | None,
) -> float | None:
    stage = backstage_fee(backstage)
    greet = meet_greet_fee(slot)
    if stage is None and greet is None:
        return None
    return (stage or 0.0) + (greet or 0.0)


def extras_total(ticket: Ticket) -> float:
    total = 0.0
    if ticket.vip_lounge:
        total += 60.0
    package = package_fee(ticket.backstage, ticket.meet_greet)
    if package is not None:
        total += package
    if ticket.parking:
        total += 25.0
    voucher: float | None = ticket.merch_voucher
    if voucher is not None:
        total += voucher * 0.8
    drinks: int | None = ticket.drink_tickets
    if drinks is not None:
        total += drinks * 9.0
    if ticket.expedited_entrance:
        total += 15.0
    if ticket.lanyard:
        total += 12.0
    return total


def describe_extras(ticket: Ticket) -> str | None:
    labels = []
    if ticket.vip_lounge:
        labels.append("vip lounge")
    if ticket.backstage:
        labels.append("backstage")
    if ticket.meet_greet:
        labels.append(f"meet & greet {ticket.meet_greet}")
    if ticket.parking:
        labels.append("parking")
    if ticket.merch_voucher:
        labels.append(f"merch voucher {ticket.merch_voucher:.0f}")
    if ticket.drink_tickets:
        labels.append(f"{ticket.drink_tickets} drinks")
    if ticket.expedited_entrance:
        labels.append("express entrance")
    if ticket.lanyard:
        labels.append("lanyard")
    return ", ".join(labels) if labels else None


def receipt_line(ticket: Ticket, price: float) -> str:
    extras: str | None = describe_extras(ticket)
    detail = extras if extras is not None else "base section price"
    return f"{ticket.holder} ({ticket.section}): {price:.2f} [{detail}]"


def upgrade(tickets: list) -> list[float]:
    prices = []
    for record in tickets:
        ticket = parse_ticket(record)
        prices.append(round(SECTION_PRICES[ticket.section] + extras_total(ticket), 2))
    return prices


def main() -> None:
    records = [
        {"holder": "Ada Vance", "section": "floor", "vip_lounge": True,
         "backstage": True, "meet_greet": "17:45", "drink_tickets": 2},
        {"holder": "Ben Ortiz", "section": "lower", "parking": True,
         "merch_voucher": 50, "lanyard": True},
        {"holder": "Cleo Mars", "section": "upper", "expedited_entrance": True,
         "meet_greet": "19:00"},
        {"holder": "Dov Reyes", "section": "lawn"},
    ]
    prices = upgrade(records)
    for record, price in zip(records, prices):
        print(receipt_line(parse_ticket(record), price))
    print(f"event revenue: {sum(prices):.2f}")


if __name__ == "__main__":
    main()

