from dataclasses import dataclass


@dataclass
class ContractParameters:
    contractor: str
    hourly_rate: float
    client: str | None = None
    signatory_title: str | None = None
    termination_days: int | None = None
    noncompete_months: int | None = None
    state: str | None = None
    arbitration_city: str | None = None
    late_fee_percent: float | None = None
    deposit: float | None = None


def money(amount: float) -> str:
    return f"${amount:,.2f}"


def parties_paragraph(
    contractor: str,
    client: str | None,
) -> str:
    if client is None:
        return f"This Agreement is made between {contractor} (\"Contractor\") and the Client."
    return f"This Agreement is made between {contractor} (\"Contractor\") and {client} (\"Client\")."


def compensation_paragraph(
    hourly_rate: float,
    late_fee_percent: float | None,
    deposit: float | None,
) -> str:
    text = f"Contractor shall be paid {money(hourly_rate)} per hour for services rendered."
    if deposit is not None:
        text += f" A non-refundable deposit of {money(deposit)} is due before work commences."
    if late_fee_percent is not None:
        text += f" Invoices unpaid after thirty (30) days accrue {late_fee_percent:.1f}% interest per month."
    return text


def termination_paragraph(
    termination_days: int | None,
    state: str | None,
) -> str | None:
    if termination_days is None:
        return None
    text = f"Either party may terminate this Agreement upon {termination_days} days' prior written notice."
    if state is not None:
        text += f" Such notice shall be delivered in the manner required by the laws of {state}."
    return text


def noncompete_paragraph(
    noncompete_months: int | None,
) -> str | None:
    if noncompete_months is None:
        return None
    return (
        f"For {noncompete_months} months following termination, Contractor shall not solicit "
        "the Client's customers or engage in directly competing work."
    )


def dispute_paragraph(
    arbitration_city: str | None,
    state: str | None,
) -> str | None:
    if arbitration_city is not None:
        venue = arbitration_city if state is None else f"{arbitration_city}, {state}"
        return f"Any dispute shall be resolved by binding arbitration held in {venue}."
    if state is not None:
        return f"This Agreement is governed by the laws of {state}, and its courts shall have exclusive venue."
    return None


def signature_block(
    contractor: str,
    signatory_title: str | None,
) -> str:
    signer = "Client Representative" if signatory_title is None else signatory_title
    return f"Signed:\n    ____________________  {contractor}, Contractor\n    ____________________  {signer}"


def draft(parameters: list[ContractParameters]) -> list[str]:
    documents = []
    for spec in parameters:
        if spec.hourly_rate <= 0:
            raise ValueError(f"hourly rate for {spec.contractor} must be positive")
        sections = [
            parties_paragraph(spec.contractor, spec.client),
            compensation_paragraph(spec.hourly_rate, spec.late_fee_percent, spec.deposit),
            termination_paragraph(spec.termination_days, spec.state),
            noncompete_paragraph(spec.noncompete_months),
            dispute_paragraph(spec.arbitration_city, spec.state),
        ]
        body = "\n\n".join(part for part in sections if part is not None)
        documents.append(
            "INDEPENDENT CONTRACTOR AGREEMENT\n\n"
            + body
            + "\n\n"
            + signature_block(spec.contractor, spec.signatory_title)
        )
    return documents


def main() -> None:
    specs = [
        ContractParameters("Dana Reyes", 95.0),
        ContractParameters(
            "Miles Okonkwo",
            140.0,
            client="Harbor Analytics LLC",
            signatory_title="Chief Operating Officer",
            termination_days=14,
            noncompete_months=6,
            state="Delaware",
            arbitration_city="Wilmington",
            late_fee_percent=1.5,
            deposit=2500.0,
        ),
    ]
    for document in draft(specs):
        print(document)
        print("=" * 60)


if __name__ == "__main__":
    main()

