    if value is None:
        return None
    if isinstance(value, int):
        return value
    text = value.strip().lower()
    if text.isdigit():
        return int(text)
    return WORD_NUMBERS.get(text)


def condition_risk(condition: str) -> int | None:
    return RISK_BY_CONDITION.get(condition.strip().lower())


def risk_score(
    medical_condition: str | None,
    origin_city: str | None,
) -> int | None:
    if medical_condition is None or not medical_condition.strip():
        return None
    score = condition_risk(medical_condition)
