from dataclasses import dataclass


@dataclass
class PlantReport:
    species: str
    discoloration: str | None = None
    stem_damage: int | None = None
    root_rot: float | None = None
    acidity: float | None = None


def diagnose_leaf(
    discoloration: str | None,
    acidity: float | None,
) -> str | None:
    """Name the disease implied by leaf discoloration under a given soil acidity."""
    if discoloration is None or acidity is None:
        return None
    shade = discoloration.strip().lower()
    if shade in ("yellow", "yellowing"):
        return "chlorosis" if acidity >= 7.0 else "nitrogen deficiency"
    if shade in ("brown", "bronze"):
        return "leaf scorch" if acidity < 5.5 else "anthracnose"
    if shade in ("white", "grey", "gray"):
        return "powdery mildew"
    if shade in ("black", "dark"):
        return "black spot"
    return "unidentified blight"


def critical_health_index(
    stem_damage: int | None,
    root_rot: float | None,
) -> float | None:
    """Blend stem damage severity and root rot score into a single index."""
    if stem_damage is None or root_rot is None:
        return None
    return round(0.6 * float(stem_damage) + 0.4 * (root_rot * 10.0), 2)


def severity_label(index: float | None) -> str:
    """Describe a critical health index, or report that it cannot be computed."""
    if index is None:
        return "index unavailable"
    if index >= 8.0:
        return "critical"
    if index >= 4.0:
        return "declining"
    return "stable"


def classify(plants: list[PlantReport]) -> list[tuple[str, str]]:
    """Pair each species with its diagnosed disease, or 'healthy' when unknown."""
    results: list[tuple[str, str]] = []
    for plant in plants:
        disease = diagnose_leaf(plant.discoloration, plant.acidity)
        results.append((plant.species, disease if disease is not None else "healthy"))
    return results


def format_report(plant: PlantReport) -> str:
    """Render one inspection report as a single human-readable line."""
    disease = diagnose_leaf(plant.discoloration, plant.acidity)
    index = critical_health_index(plant.stem_damage, plant.root_rot)
    name = disease if disease is not None else "healthy"
    shown = "n/a" if index is None else f"{index:.2f}"
    return f"{plant.species:<10} {name:<22} index={shown:<6} {severity_label(index)}"


def main() -> None:
    inspections = [
        PlantReport("rose", stem_damage=2),
        PlantReport("maple", discoloration="Yellow", stem_damage=7, root_rot=0.9, acidity=7.4),
        PlantReport("basil", discoloration="brown", root_rot=0.3, acidity=5.1),
        PlantReport("fern", discoloration="grey", stem_damage=3, root_rot=0.2, acidity=6.0),
        PlantReport("olive", stem_damage=5, root_rot=0.55, acidity=6.8),
    ]
    for plant in inspections:
        print(format_report(plant))
    print(classify(inspections))


if __name__ == "__main__":
    main()

