from dataclasses import dataclass
from typing import Iterable, Sequence


@dataclass
class Observation:
    """A single log entry; everything but the target name may be missing."""

    target: str
    right_ascension: float | None = None
    declination: float | None = None
    magnitude: float | None = None
    observer: str | None = None


def _as_float(value: object) -> float | None:
    """Turn a raw log field into a float, treating blanks as missing."""
    if value is None or (isinstance(value, str) and not value.strip()):
        return None
    return float(value)


def _as_name(value: object) -> str | None:
    if value is None or not str(value).strip():
        return None
    return str(value).strip()


def parse_observation(row: Sequence[object]) -> Observation:
    target, ra, dec, mag, observer = row
    return Observation(
        target=str(target).strip(),
        right_ascension=_as_float(ra),
        declination=_as_float(dec),
        magnitude=_as_float(mag),
        observer=_as_name(observer),
    )


def celestial_sector(
    right_ascension: float | None,
    declination: float | None,
) -> int | None:
    """Sector index 0..23, or missing when a coordinate was not logged."""
    if right_ascension is None or declination is None:
        return None
    hour_band = int((right_ascension % 360.0) // 30.0)
    hemisphere = 0 if declination >= 0.0 else 1
    return hour_band * 2 + hemisphere


def brightness_category(
    magnitude: float | None,
    observer: str | None,
) -> str | None:
    if magnitude is None:
        return None
    if magnitude < 1.0:
        label = "brilliant"
    elif magnitude < 6.0:
        label = "naked-eye"
    else:
        label = "telescopic"
    if observer is None:
        return f"{label} (unattributed)"
    return f"{label} (confirmed by {observer})"


def describe(observation: Observation) -> str:
    sector: int | None = celestial_sector(
        observation.right_ascension, observation.declination
    )
    category = brightness_category(observation.magnitude, observation.observer)
    sector_text = "?" if sector is None else str(sector)
    return f"{observation.target}: sector {sector_text}, {category or 'unrated'}"


def validate(observations: Iterable[Observation]) -> list[str]:
    cleaned = []
    for observation in observations:
        sector = celestial_sector(
            observation.right_ascension, observation.declination
        )
        category = brightness_category(observation.magnitude, observation.observer)
        if sector is not None and category is not None:
            cleaned.append(observation.target)
    return cleaned


def main() -> None:
    rows = [
        ("moon", "", None, "", None),
        ("vega", 279.23, 38.78, 0.03, "Hipparchus"),
        ("betelgeuse", 88.79, 7.41, 0.45, ""),
        ("sirius", 101.29, None, -1.46, "Ptolemy"),
    ]
    logs = [parse_observation(row) for row in rows]
    for log in logs:
        print(describe(log))
    print(validate(logs))


if __name__ == "__main__":
    main()

