from dataclasses import dataclass

METALLIC_STREAKS = {"black", "gray", "grey", "dark gray", "reddish brown", "greenish black"}

FIELD_DATA = """
quartz, missing, 7.0, missing, missing
galena, gray, 2.5, 3, uneven
pyrite, greenish black, 6.2, 0, conchoidal
native copper, reddish brown, 2.8, 0, hackly
calcite, white, 3.0, 3, uneven
hematite, reddish brown, 5.5, missing, missing
magnetite, black, 6.0, 0, uneven
"""


@dataclass
class Mineral:
    name: str
    streak: str | None
    hardness: float | None
    cleavage: int | None
    fracture: str | None


def parse_text(raw: str) -> str | None:
    value = raw.strip()
    if not value or value.lower() == "missing":
        return None
    return value


def parse_float(raw: str) -> float | None:
    text = parse_text(raw)
    if text is None:
        return None
    return float(text)


def parse_int(raw: str) -> int | None:
    text = parse_text(raw)
    if text is None:
        return None
    return int(text)


def parse_record(line: str) -> Mineral | None:
    fields = line.split(",")
    if len(fields) != 5 or not fields[0].strip():
        return None
    return Mineral(
        name=fields[0].strip(),
        streak=parse_text(fields[1]),
        hardness=parse_float(fields[2]),
        cleavage=parse_int(fields[3]),
        fracture=parse_text(fields[4]),
    )


def durability_class(
    hardness: float | None,
    cleavage: int | None,
) -> str | None:
    if hardness is None or cleavage is None:
        return None
    if cleavage == 0:
        return "tough" if hardness >= 5.0 else "soft"
    if hardness >= 6.0:
        return "brittle-hard"
    return "friable"


def guess_metallic(
    streak: str | None,
    fracture: str | None,
) -> bool | None:
    if streak is None:
        return None
    if streak.strip().lower() in METALLIC_STREAKS:
        return True
    return fracture is not None and fracture.strip().lower() == "hackly"


def describe(
    name: str,
    durability: str | None,
    metallic: bool | None,
) -> str:
    label = durability if durability is not None else "untested"
    if metallic is None:
        metal = "unknown"
    else:
        metal = "yes" if metallic else "no"
    return f"{name:<14} durability={label:<13} metallic={metal}"


def classify(minerals) -> list[str]:
    selected = []
    for mineral in minerals:
        durability = durability_class(mineral.hardness, mineral.cleavage)
        metallic = guess_metallic(mineral.streak, mineral.fracture)
        if durability is not None and metallic:
            selected.append(mineral.name)
    return selected


def main() -> None:
    minerals = []
    for line in FIELD_DATA.splitlines():
        record = parse_record(line)
        if record is not None:
            minerals.append(record)
    for mineral in minerals:
        print(describe(
            mineral.name,
            durability_class(mineral.hardness, mineral.cleavage),
            guess_metallic(mineral.streak, mineral.fracture),
        ))
    print("metallic with known durability:", classify(minerals))


if __name__ == "__main__":
    main()

