    hardness: Optional[float],
    cleavage: Optional[int],
) -> Optional[str]:
    if hardness is None or cleavage is None:
        return None
    if cleavage == 0:
        return "tough" if hardness >= 5.0 else "soft"
    if hardness >= 6.0:
        return "brittle-hard"
    return "friable"


def guess_metallic(
    streak: Optional[str],
    fracture: Optional[str],
) -> Optional[bool]:
    if streak is None:
        return None
    if streak.strip().lower() in METALLIC_STREAKS:
        return True
    return fracture is not None and fracture.strip().lower() == "hackly"


def describe(
    name: str,
    durability: Optional[str],
    metallic: Optional[bool],
) -> str:
    label = durability if durability is not None else "untested"
    if metallic is None:
        metal = "unknown"
    else:
        metal = "yes" if metallic else "no"
    return f"{name:<14} durability={label:<13} metallic={metal}"


def classify(minerals) -> list[str]:
    selected = []
    for mineral in minerals:
        durability = durability_class(mineral.hardness, mineral.cleavage)
        metallic = guess_metallic(mineral.streak, mineral.fracture)
        if durability is not None and metallic:
            selected.append(mineral.name)
    return selected


def main() -> None:
    minerals = []
    for line in FIELD_DATA.splitlines():
        record = parse_record(line)
        if record is not None:
            minerals.append(record)
    for mineral in minerals:
        print(describe(
            mineral.name,
            durability_class(mineral.hardness, mineral.cleavage),
            guess_metallic(mineral.streak, mineral.fracture),
        ))
    print("metallic with known durability:", classify(minerals))


if __name__ == "__main__":
    main()

