    score = 0
    if port in SENSITIVE_PORTS:
        score += 5
    elif port is not None:
        score += 2
    if exfil_size is not None:
        score += 2 if exfil_size < 1024.0 else 5
    return score


def attack_vector(
    address: str | None,
    malware_hash: str | None,
) -> str | None:
    if malware_hash is None:
        return None
    if address is None:
        return "staged-dropper"
    if address.startswith(("10.", "192.168.")):
