    for incident in incidents:
        severity = threat_severity(incident.port, incident.exfil_size)
        if severity is None or severity < HIGH_SEVERITY_THRESHOLD:
            continue
        if attack_vector(incident.address, incident.malware_hash) is not None:
            flagged.append(incident.event_id)
    return flagged


def main() -> None:
