from __future__ import annotations

from datetime import date, datetime

XRAY_VALID_DAYS = 730
STANDARD_FEE = 180.0
DEFAULT_COPAY = 25.0
DATE_FORMAT = "%Y-%m-%d"


def text_field(profile: dict, key: str) -> str | None:
    """Return a trimmed string field, or a missing value when blank/absent."""
    raw = profile.get(key)
    if not isinstance(raw, str):
        return None
    cleaned = raw.strip()
    return cleaned or None


def copay_field(profile: dict) -> float | None:
    raw = profile.get("copay")
    if isinstance(raw, (int, float)):
        return float(raw)
    if isinstance(raw, str) and raw.strip():
        try:
            return float(raw)
        except ValueError:
            return None
    return None


def parse_xray_date(
    raw: str | None,
) -> date | None:
    if raw is None:
        return None
    try:
        return datetime.strptime(raw.strip(), DATE_FORMAT).date()
    except ValueError:
        return None


def needs_new_xray(
    xray_date: str | None,
    previous_dentist: str | None,
    today: date | None = None,
) -> bool | None:
    """True when a fresh x-ray is required, None when the date is unknown."""
    taken = parse_xray_date(xray_date)
    if taken is None:
        return None
    reference = today if today is not None else date.today()
    if (reference - taken).days > XRAY_VALID_DAYS:
        return True
    return previous_dentist is None


def out_of_pocket(
    insurance: str | None,
    copay: float | None,
) -> float | None:
    if insurance is None and copay is None:
        return None
    if insurance is None:
        return STANDARD_FEE
    if copay is None:
        return DEFAULT_COPAY
    return round(copay, 2)


def describe(
    name: str,
    xray_flag: bool | None,
    cost: float | None,
) -> str:
    xray_text = "unknown" if xray_flag is None else ("yes" if xray_flag else "no")
    cost_text = "unknown" if cost is None else f"${cost:.2f}"
    return f"{name}: new x-ray {xray_text}, out of pocket {cost_text}"


def analyze(patients: list[dict], today: date | None = None) -> list[str]:
    scheduled = []
    for profile in patients:
        name = text_field(profile, "name")
        if name is None:
            continue
        xray_flag = needs_new_xray(
            text_field(profile, "xray_date"),
            text_field(profile, "previous_dentist"),
            today,
        )
        cost = out_of_pocket(text_field(profile, "insurance"), copay_field(profile))
        if xray_flag and cost is not None:
            scheduled.append(name)
    return scheduled


def main() -> None:
    patients = [
        {"name": "charlie"},
        {"name": "dana", "xray_date": "2019-04-02", "insurance": "Delta", "copay": 30.0},
        {"name": "eli", "previous_dentist": "Dr. Kim", "xray_date": "2025-01-10"},
        {"name": "fay", "xray_date": "2025-02-20", "copay": 15.0},
    ]
    reference = date(2025, 6, 1)
    for profile in patients:
        flag = needs_new_xray(
            text_field(profile, "xray_date"),
            text_field(profile, "previous_dentist"),
            reference,
        )
        cost = out_of_pocket(text_field(profile, "insurance"), copay_field(profile))
        print(describe(profile["name"], flag, cost))
    print(analyze(patients, reference))


if __name__ == "__main__":
    main()

