        parse_threshold(raw.get("threshold")),
        normalise_text(raw.get("text")),
        normalise_text(raw.get("fallback")),
    )


def meets_requirements(
    item: str | None,
    threshold: int | None,
    inventory: set[str],
    relationship: int,
) -> bool | None:
    if item is None and threshold is None:
        return None
    if item is not None and item not in inventory:
        return False
    if threshold is not None and relationship < threshold:
        return False
    return True


def resolve_text(
