from dataclasses import dataclass

SKILL_LEVELS = {
    "cooking": "basic",
    "first aid": "intermediate",
    "driving": "advanced",
    "fundraising": "basic",
    "logistics": "intermediate",
}


@dataclass
class Shift:
    event: str
    start: int | None = None
    end: int | None = None
    skill: str | None = None
    vehicle: bool | None = None


def _as_hour(value: object) -> int | None:
    if value is None:
        return None
    hour = int(str(value))
    if not 0 <= hour <= 24:
        raise ValueError(f"hour out of range: {hour}")
    return hour


def _as_flag(value: object) -> bool | None:
    if value is None:
        return None
    if isinstance(value, str):
        return value.strip().lower() in {"yes", "true", "1"}
    return bool(value)


def _as_skill(value: object) -> str | None:
    if value is None:
        return None
    text = str(value).strip().lower()
    return text or None


def parse_shift(record: dict[str, object]) -> Shift:
    event = str(record["event"]).strip()
    if not event:
        raise ValueError("every shift request needs an event name")
    return Shift(
        event=event,
        start=_as_hour(record.get("start")),
        end=_as_hour(record.get("end")),
        skill=_as_skill(record.get("skill")),
        vehicle=_as_flag(record.get("vehicle")),
    )


def total_duration(
    start: int | None,
    end: int | None,
) -> int | None:
    if start is None or end is None:
        return None
    return end - start if end >= start else (24 - start) + end


def required_training(
    skill: str | None,
    vehicle: bool | None,
) -> str | None:
    if skill is None:
        return None
    level = SKILL_LEVELS.get(skill, "basic")
    if vehicle and level != "advanced":
        return "advanced"
    return level


def organize(shifts: list[Shift]) -> list[str]:
    assigned = []
    for shift in shifts:
        hours = total_duration(shift.start, shift.end)
        level = required_training(shift.skill, shift.vehicle)
        if hours is not None and hours >= 4 and level is not None:
            assigned.append(shift.event)
    return assigned


def format_report(shifts: list[Shift]) -> str:
    lines = []
    for shift in shifts:
        hours = total_duration(shift.start, shift.end)
        level = required_training(shift.skill, shift.vehicle)
        span = "unknown" if hours is None else f"{hours}h"
        training = "unknown" if level is None else level
        lines.append(f"{shift.event}: duration={span}, training={training}")
    return "\n".join(lines)


def main() -> None:
    records: list[dict[str, object]] = [
        {"event": "gala", "start": 9},
        {"event": "food drive", "start": 8, "end": 14, "skill": "cooking"},
        {"event": "transport run", "start": 22, "end": 3, "skill": "driving", "vehicle": "yes"},
        {"event": "clinic", "start": 10, "end": 12, "skill": "first aid"},
        {"event": "warehouse", "start": 6, "end": 15, "vehicle": True},
    ]
    shifts = [parse_shift(record) for record in records]
    print(format_report(shifts))
    print("assigned:", organize(shifts))


if __name__ == "__main__":
    main()

