from typing import Iterable, NamedTuple

MISSING_TOKENS = {"", "na", "n/a", "none", "missing", "-"}


class Reading(NamedTuple):
    block: str
    nitrogen: float | None
    phosphorus: float | None
    potassium: float | None
    moisture: float | None
    temperature: float | None


def parse_measurement(token: str) -> float | None:
    cleaned = token.strip()
    if cleaned.lower() in MISSING_TOKENS:
        return None
    return float(cleaned)


def parse_reading(line: str) -> Reading | None:
    fields = [part.strip() for part in line.split(",")]
    if len(fields) != 6 or not fields[0]:
        return None
    return Reading(fields[0], *(parse_measurement(field) for field in fields[1:]))


def fertilizer_recommendation(
    nitrogen: float | None,
    phosphorus: float | None,
    potassium: float | None,
) -> str | None:
    if nitrogen is None or phosphorus is None or potassium is None:
        return None
    levels = (("N", nitrogen), ("P", phosphorus), ("K", potassium))
    deficient = [name for name, value in levels if value < 20.0]
    if not deficient:
        return "balanced: maintain current program"
    return "apply " + "-".join(deficient) + " fertilizer"


def irrigation_need(
    moisture: float | None,
    temperature: float | None,
) -> str | None:
    if moisture is None or temperature is None:
        return None
    if moisture < 15.0:
        return "urgent irrigation" if temperature >= 30.0 else "irrigation needed"
    if moisture < 30.0:
        return "monitor closely"
    return "no irrigation"


def analyze(sensors: Iterable[Reading]) -> list[tuple[str, str | None]]:
    report: list[tuple[str, str | None]] = []
    for reading in sensors:
        if irrigation_need(reading.moisture, reading.temperature) is None:
            continue
        report.append((reading.block, fertilizer_recommendation(
            reading.nitrogen, reading.phosphorus, reading.potassium)))
    return report


def format_entry(block: str, recommendation: str | None) -> str:
    return f"{block}: {recommendation or 'nutrient data incomplete'}"


