    raw = [
        "a,10,missing,missing,missing,missing",
        "b,12,45,18,11,32",
        "c,34,40,38,42,21",
        "d,25,na,30,28,19",
    ]
    readings = [parsed for line in raw if (parsed := parse_reading(line)) is not None]
    results = analyze(readings)
    print(results)
    for block, recommendation in results:
        print(format_entry(block, recommendation))


if __name__ == "__main__":
    main()

