from datetime import date


def normalize(
    text: str | None,
) -> str | None:
    """Trim a possibly missing text field, treating blanks as missing."""
    if text is None:
        return None
    cleaned = text.strip().lower()
    return cleaned or None


def parse_year(
    value: str | int | None,
) -> int | None:
    """Accept a year as an integer, a numeric string, or a missing value."""
    if value is None or isinstance(value, int):
        return value
    cleaned = value.strip()
    if not cleaned.isdigit():
        return None
    return int(cleaned)


def mechanism_complexity(
    pendulum: str | None,
    gear_material: str | None,
) -> str | None:
    """Describe the movement; unknown without a pendulum type."""
    pend = normalize(pendulum)
    if pend is None:
        return None
    gear = normalize(gear_material)
    if gear is None:
        return f"{pend} pendulum on unspecified gearing"
    return f"{pend} pendulum on {gear} gearing"


def chime_weight(chime: str | None) -> int:
    """Count the distinct strikes in a chime sequence."""
    sequence = normalize(chime)
    if sequence is None:
        return 0
    return len(sequence.replace("-", " ").replace(",", " ").split())


def clock_age(
    serviced_year: int | None,
    reference_year: int,
) -> int | None:
    if serviced_year is None:
        return None
    return max(reference_year - serviced_year, 0)


def service_priority(
    chime: str | None,
    serviced_year: int | None,
    reference_year: int,
) -> int | None:
    age = clock_age(serviced_year, reference_year)
    if age is None:
        return None
    return age * 2 + chime_weight(chime) * 5


def describe(clock: dict, reference_year: int) -> str:
    mechanism = mechanism_complexity(clock.get("pendulum"), clock.get("gear"))
    year = parse_year(clock.get("serviced"))
    priority = service_priority(clock.get("chime"), year, reference_year)
    return "{:<10} {:<40} {}".format(
        clock["maker"],
        mechanism if mechanism is not None else "unknown mechanism",
        f"priority {priority}" if priority is not None else "priority unknown",
    )


def log(clocks: list[dict], reference_year: int | None = None) -> list[str]:
    year_now = reference_year if reference_year is not None else date.today().year
    overdue = []
    for clock in clocks:
        if mechanism_complexity(clock.get("pendulum"), clock.get("gear")) is None:
            continue
        age = clock_age(parse_year(clock.get("serviced")), year_now)
        if age is not None and age > 50:
            overdue.append(clock["maker"])
    return overdue


def main() -> None:
    clocks = [
        {"maker": "smith", "pendulum": None, "gear": "brass", "chime": None, "serviced": None},
        {"maker": "ansonia", "pendulum": "mercury", "gear": "steel", "chime": "ding-dong-ding", "serviced": "1958"},
        {"maker": "vulliamy", "pendulum": "gridiron", "gear": None, "chime": "bim-bam", "serviced": 1902},
        {"maker": "seth", "pendulum": "wooden rod", "gear": "iron", "chime": "westminster", "serviced": 2019},
    ]
    for clock in clocks:
        print(describe(clock, 2024))
    print(log(clocks, 2024))


if __name__ == "__main__":
    main()

