from __future__ import annotations

import sys

BestNibId = int | None
AverageWidth = float | None
Selection = tuple[BestNibId, AverageWidth]


def validate_nib(
    nib: tuple[int, float, float, float],
    max_width: float | None,
    min_flexibility: float | None,
) -> tuple[int, float, float, float] | None:
    """Return the nib when it respects both optional limits, otherwise nothing."""
    _, stroke_width, flexibility, _ = nib
    if max_width is not None and stroke_width > max_width:
        return None
    if min_flexibility is not None and flexibility < min_flexibility:
        return None
    return nib


def best_flowing_nib(
    nibs: list[tuple[int, float, float, float]],
    max_flow: float | None,
) -> BestNibId:
    """Id of the nib with the lowest flow rate within the optional flow limit."""
    best_id: BestNibId = None
    best_flow: float | None = None
    for nib_id, _, _, flow_rate in nibs:
        if max_flow is not None and flow_rate > max_flow:
            continue
        if best_flow is None or flow_rate < best_flow:
            best_id, best_flow = nib_id, flow_rate
    return best_id


def select(
    nibs: list[tuple[int, float, float, float]],
    width: float | None,
    flexibility: float | None,
    flow: float | None,
) -> Selection:
    conforming = [
        nib for nib in nibs if validate_nib(nib, width, flexibility) is not None
    ]
    if not conforming:
        return None, None
    average_width = sum(nib[1] for nib in conforming) / len(conforming)
    return best_flowing_nib(conforming, flow), average_width


def parse_limit(text: str) -> float | None:
    """Read a limit from the command line, where '-' means the limit is absent."""
    if text == "-":
        return None
    return float(text)


def format_selection(
    nib_id: BestNibId,
    average_width: AverageWidth,
) -> str:
    chosen = "none" if nib_id is None else f"#{nib_id}"
    if average_width is None:
        return f"best flowing nib: {chosen}, average stroke width: none"
    return f"best flowing nib: {chosen}, average stroke width: {average_width:.2f} mm"


def main(argv: list[str]) -> int:
    catalog = [
        (7, 2.0, 80.0, 5.0),
        (3, 0.8, 65.0, 2.4),
        (11, 1.0, 95.0, 3.1),
        (4, 0.4, 40.0, 1.7),
    ]
    limits = argv[1:4] if len(argv) >= 4 else ["-", "-", "-"]
    width = parse_limit(limits[0])
    flexibility = parse_limit(limits[1])
    flow = parse_limit(limits[2])
    nib_id, average_width = select(catalog, width, flexibility, flow)
    print(format_selection(nib_id, average_width))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

