NoteId = int | None
MeanRate = float | None
Note = tuple[int, float, float, float]
BlendResult = tuple[NoteId, MeanRate]


def parse_note(text: str) -> Note | None:
    """Turn 'id, volatility, intensity, price' into a note tuple, or None if malformed."""
    parts = [part.strip() for part in text.split(",")]
    if len(parts) != 4:
        return None
    try:
        return (int(parts[0]), float(parts[1]), float(parts[2]), float(parts[3]))
    except ValueError:
        return None


def parse_limit(text: str) -> float | None:
    """An empty field means the limit was left out."""
    stripped = text.strip()
    if not stripped:
        return None
    return float(stripped)


def check_note(
    note: Note,
    max_volatility: float | None,
    min_intensity: float | None,
) -> Note | None:
    _, rate, aroma, _price = note
    if max_volatility is not None and rate > max_volatility:
        return None
    if min_intensity is not None and aroma < min_intensity:
        return None
    return note


def cheapest_id(notes: list[Note], max_cost: float | None) -> NoteId:
    affordable = [n for n in notes if max_cost is None or n[3] <= max_cost]
    if not affordable:
        return None
    return min(affordable, key=lambda n: n[3])[0]


def average_volatility(notes: list[Note]) -> MeanRate:
    if not notes:
        return None
    return sum(n[1] for n in notes) / len(notes)


def blend(
    notes: list[Note],
    volatility: float | None = None,
    intensity: float | None = None,
    cost: float | None = None,
) -> BlendResult:
    valid = [n for n in notes if check_note(n, volatility, intensity) is not None]
    within_budget = [n for n in valid if cost is None or n[3] <= cost]
    return cheapest_id(valid, cost), average_volatility(within_budget)


def format_summary(note_id: NoteId, mean_rate: MeanRate) -> str:
    left = "none" if note_id is None else f"#{note_id}"
    right = "none" if mean_rate is None else f"{mean_rate:.2f}"
    return f"cheapest base: {left} | mean volatility: {right}"


def main() -> None:
    raw_notes = [
        "3, 15, 8, 20",
        "7, 4, 9, 6",
        "12, 9, 5, 4",
        "bad row",
        "21, 2, 10, 11",
    ]
    notes = []
    for row in raw_notes:
        parsed = parse_note(row)
        if parsed is None:
            print(f"skipping unreadable note: {row!r}")
        else:
            notes.append(parsed)
    for volatility, intensity, cost in [("", "", "10"), ("10", "7", ""), ("5", "8", "10")]:
        result = blend(notes, parse_limit(volatility), parse_limit(intensity), parse_limit(cost))
        print(format_summary(*result))


if __name__ == "__main__":
    main()

