def parse_piece(text: str) -> Piece | None:
    fields = [field.strip() for field in text.split(",")]
    if len(fields) != 4:
        return None
    try:
        piece_id, thickness, temperature, minutes = (int(field) for field in fields)
    except ValueError:
        return None
    return (piece_id, thickness, temperature, minutes)


def verify_piece(
    piece: Piece,
    max_thickness: float | None,
    max_temperature: float | None,
) -> Piece | None:
    _, thickness, temperature, _ = piece
    if max_thickness is not None and thickness > max_thickness:
        return None
    if max_temperature is not None and temperature > max_temperature:
        return None
    return piece


def longest_annealing(pieces: list[Piece], min_time: float | None) -> PieceId:
    best: Piece | None = None
    for piece in pieces:
        if min_time is not None and piece[3] < min_time:
            continue
        if best is None or piece[3] > best[3]:
            best = piece
    if best is None:
        return None
    return best[0]


def average_thickness(pieces: list[Piece]) -> AvgThickness:
    if not pieces:
        return None
    return sum(piece[1] for piece in pieces) / len(pieces)


