    time: float | None = None,
) -> ScheduleResult:
    verified: list[Piece] = []
    for piece in pieces:
        checked = verify_piece(piece, thickness, temperature)
        if checked is not None:
            verified.append(checked)
    return longest_annealing(verified, time), average_thickness(verified)


def format_report(
    longest: int | None,
