def validate_dough(
    dough: Dough,
    min_hydration: int | None,
    max_temperature: int | None,
) -> Dough | None:
    _, hydration, temperature, _ = dough
    if min_hydration is not None and hydration < min_hydration:
        return None
    if max_temperature is not None and temperature > max_temperature:
        return None
    return dough


def most_expanded(
    doughs: list[Dough],
    min_volume: int | None,
) -> int | None:
    best_id = None
    best_volume = None
    for dough_id, _, _, volume in doughs:
        if min_volume is not None and volume <= min_volume:
            continue
        if best_volume is None or volume > best_volume:
            best_id = dough_id
            best_volume = volume
    return best_id


def average_hydration(doughs: list[Dough]) -> float | None:
    if not doughs:
        return None
    return round(mean(dough[1] for dough in doughs), 2)


def proof(
    doughs: list[Dough],
    hydration: int | None,
    temperature: int | None,
    volume: int | None,
) -> ProofResult:
    conforming: list[Dough] = []
    for dough in doughs:
        checked = validate_dough(dough, hydration, temperature)
        if checked is not None:
            conforming.append(checked)
    return (most_expanded(conforming, volume), average_hydration(conforming))


def format_report(
    dough_id: int | None,
    avg_hydration: float | None,
) -> str:
    if dough_id is None and avg_hydration is None:
        return "no dough finished proofing"
    if dough_id is None:
        return f"no dough expanded enough; average hydration {avg_hydration}%"
    return f"dough {dough_id} leads; average hydration {avg_hydration}%"


