    return batch


def thickest_wick(
    valid: list[Batch],
    max_thickness: float | None = None,
) -> int | None:
    best_id: int | None = None
    best_wick = 0
    for batch_id, _melt, _fragrance, wick in valid:
        if max_thickness is not None and wick > max_thickness:
            continue
        if best_id is None or wick > best_wick:
            best_id, best_wick = batch_id, wick
    return best_id


def average_melt(valid: list[Batch]) -> float | None:
    if not valid:
        return None
    return sum(batch[1] for batch in valid) / len(valid)


def pour(
    batches: list[Batch],
    melt: float | None = None,
    fragrance: float | None = None,
    thickness: float | None = None,
) -> tuple[
    int | None,
    float | None,
]:
    valid: list[Batch] = []
    for batch in batches:
        kept = check_batch(batch, melt, fragrance)
        if kept is not None:
            valid.append(kept)
    return thickest_wick(valid, thickness), average_melt(valid)


def parse_limit(
    raw: str | None,
) -> float | None:
    if raw is None or raw.strip() in ("", "-"):
        return None
    return float(raw)


def format_report(
