from typing import Sequence

Billet = tuple[int, float, float, float]
BilletId = int | None
CarbonMean = float | None


def parse_billet(record: Sequence[object]) -> Billet:
    """Normalise a raw record into a (id, carbon, temperature, weight) tuple."""
    if len(record) != 4:
        raise ValueError(f"a billet record needs 4 fields, got {len(record)}")
    billet_id, carbon, temperature, weight = record
    return (int(billet_id), float(carbon), float(temperature), float(weight))


def check_billet(
    billet: Billet,
    carbon: float | None = None,
    temperature: float | None = None,
) -> Billet | None:
    """Return the billet when it meets both optional minimums, else nothing."""
    if carbon is not None and billet[1] < carbon:
        return None
    if temperature is not None and billet[2] < temperature:
        return None
    return billet


def heaviest_billet_id(
    valid_billets: list[Billet],
    weight: float | None = None,
) -> BilletId:
    """Locate the heaviest billet staying under the optional weight cap."""
    best_id: BilletId = None
    best_weight: float | None = None
    for billet in valid_billets:
        if weight is not None and billet[3] > weight:
            continue
        if best_weight is None or billet[3] > best_weight:
            best_id = billet[0]
            best_weight = billet[3]
    return best_id


def average_carbon(valid_billets: list[Billet]) -> CarbonMean:
    if not valid_billets:
        return None
    return sum(billet[1] for billet in valid_billets) / len(valid_billets)


def heat(
    billets: list[Billet],
    carbon: float | None = None,
    temperature: float | None = None,
    weight: float | None = None,
) -> tuple[BilletId, CarbonMean]:
    valid_billets = []
    for billet in billets:
        checked = check_billet(billet, carbon, temperature)
        if checked is not None:
            valid_billets.append(checked)
    return (heaviest_billet_id(valid_billets, weight), average_carbon(valid_billets))


def format_report(
    billet_id: BilletId,
    mean_carbon: CarbonMean,
) -> str:
    heaviest = "none" if billet_id is None else f"#{billet_id}"
    mean = "none" if mean_carbon is None else f"{mean_carbon:.2f}%"
    return f"heaviest valid billet: {heaviest}, average carbon: {mean}"


def main() -> None:
    raw_records = [
        (7, 80, 1200, 50),
        (8, 65, 1550, 120),
        (9, 92, 1600, 95),
        (10, 88, 1480, 70),
    ]
    charge = [parse_billet(record) for record in raw_records]
    print(format_report(*heat(charge[:1], temperature=1500)))
    print(format_report(*heat(charge)))
    print(format_report(*heat(charge, carbon=70, temperature=1500)))
    print(format_report(*heat(charge, carbon=70, temperature=1500, weight=100)))


if __name__ == "__main__":
    main()

