from __future__ import annotations

Mushroom = tuple[int, float, float, float]
MushroomId = int | None
AverageDiameter = float | None


def parse_mushroom(line: str) -> Mushroom | None:
    """Turn a "id, diameter, weight, toxicity" record into a mushroom tuple."""
    parts = [part.strip() for part in line.split(",")]
    if len(parts) != 4:
        return None
    try:
        identifier = int(parts[0])
        diameter = float(parts[1])
        weight = float(parts[2])
        toxicity = float(parts[3])
    except ValueError:
        return None
    return identifier, diameter, weight, toxicity


def check_mushroom(
    mushroom: Mushroom,
    diameter: float | None,
    weight: float | None,
) -> Mushroom | None:
    """Return the mushroom when it clears the size limits, otherwise nothing."""
    _, cap, grams, _toxicity = mushroom
    if diameter is not None and cap < diameter:
        return None
    if weight is not None and grams > weight:
        return None
    return mushroom


def safest_mushroom(mushrooms: list[Mushroom], toxicity: float | None) -> MushroomId:
    """Id of the least toxic mushroom respecting the toxicity cap, if any."""
    best: Mushroom | None = None
    for mushroom in mushrooms:
        if toxicity is not None and mushroom[3] > toxicity:
            continue
        if best is None or mushroom[3] < best[3]:
            best = mushroom
    if best is None:
        return None
    return best[0]


def average_diameter(mushrooms: list[Mushroom]) -> float | None:
    if not mushrooms:
        return None
    return sum(mushroom[1] for mushroom in mushrooms) / len(mushrooms)


def sort(
    mushrooms: list[Mushroom],
    diameter: float | None = None,
    weight: float | None = None,
    toxicity: float | None = None,
) -> tuple[MushroomId, AverageDiameter]:
    passing: list[Mushroom] = []
    for mushroom in mushrooms:
        accepted = check_mushroom(mushroom, diameter, weight)
        if accepted is not None:
            passing.append(accepted)
    return safest_mushroom(passing, toxicity), average_diameter(passing)


def format_report(
    best: int | None,
    average: float | None,
) -> str:
    chosen = "none" if best is None else str(best)
    size = "n/a" if average is None else f"{average:.1f} cm"
    return f"safest: {chosen}, average cap: {size}"


def main() -> None:
    records = ["13, 10, 50, 1", "7, 12, 90, 4", "21, 8, 40, 0", "broken row"]
    basket = [parsed for line in records if (parsed := parse_mushroom(line)) is not None]
    print(format_report(*sort(basket)))
    print(format_report(*sort(basket, diameter=9, weight=80, toxicity=2)))
    print(format_report(*sort(basket, diameter=30)))


if __name__ == "__main__":
    main()

