from statistics import mean

Swatch = tuple[int, int, int, int]
BestId = int | None
AvgGauge = float | None
Result = tuple[BestId, AvgGauge]
Limit = int | None


def check_swatch(
    swatch: Swatch,
    min_stitches: int | None = None,
    min_rows: int | None = None,
) -> Swatch | None:
    """Return the swatch when it meets the given gauge minimums, else None."""
    _, stitches_per_inch, rows_per_inch, _ = swatch
    if min_stitches is not None and stitches_per_inch < min_stitches:
        return None
    if min_rows is not None and rows_per_inch < min_rows:
        return None
    return swatch


def best_tensioned(
    valid: list[Swatch],
    max_tension: int | None = None,
) -> int | None:
    """Return the id of the loosest (lowest tension) swatch under the cap."""
    eligible = [
        swatch
        for swatch in valid
        if max_tension is None or swatch[3] <= max_tension
    ]
    if not eligible:
        return None
    return min(eligible, key=lambda swatch: swatch[3])[0]


def average_stitches(valid: list[Swatch]) -> float | None:
    """Average stitches per inch over the verified swatches."""
    if not valid:
        return None
    return float(mean(swatch[1] for swatch in valid))


def knit(
    swatches: list[Swatch],
    stitches: int | None = None,
    rows: Limit = None,
    tension: Limit = None,
) -> Result:
    verified = []
    for swatch in swatches:
        kept = check_swatch(swatch, stitches, rows)
        if kept is not None:
            verified.append(kept)
    return best_tensioned(verified, tension), average_stitches(verified)


def format_result(best_id: BestId, avg: AvgGauge) -> str:
    label = f"swatch {best_id}" if best_id is not None else "no swatch"
    gauge = f"{avg:.1f} sts/in" if avg is not None else "no gauge data"
    return f"{label}, {gauge}"


def main() -> None:
    stash: list[Swatch] = [
        (3, 20, 28, 5),
        (7, 18, 24, 3),
        (11, 22, 30, 8),
        (12, 14, 18, 2),
    ]
    trials: list[tuple[Limit, Limit, Limit]] = [
        (None, None, None),
        (18, 24, None),
        (18, 24, 4),
        (30, None, None),
    ]
    for min_sts, min_rows, max_tension in trials:
        result = knit(stash, min_sts, min_rows, max_tension)
        print(result, "->", format_result(*result))


if __name__ == "__main__":
