    min_carat: Optional[float],
) -> MaybeStone:
    _, clarity, carat, _ = stone
    if min_clarity is not None and clarity < min_clarity:
        return None
    if min_carat is not None and carat < min_carat:
        return None
    return stone


def hardest_stone_id(
    stones: list[Stone],
    min_hardness: Optional[int],
) -> MaybeId:
    best_id: MaybeId = None
    best_hardness = 0
    for stone_id, _, _, hardness in stones:
        if min_hardness is not None and hardness < min_hardness:
            continue
        if best_id is None or hardness > best_hardness:
            best_id = stone_id
            best_hardness = hardness
    return best_id


def average_clarity(stones: list[Stone]) -> MaybeScore:
    if not stones:
        return None
    return sum(stone[1] for stone in stones) / len(stones)


def facet(
    rough: list[Stone],
    clarity: Optional[int] = None,
    carat: Optional[float] = None,
    hardness: Optional[int] = None,
) -> FacetResult:
    kept: list[Stone] = []
    for stone in rough:
        accepted = check_stone(stone, clarity, carat)
        if accepted is not None:
            kept.append(accepted)
    return (hardest_stone_id(kept, hardness), average_clarity(kept))


def describe(result: FacetResult) -> str:
    stone_id, mean_clarity = result
    if mean_clarity is None:
        return "no stones passed the sieve"
    if stone_id is None:
        return f"no stone hard enough, average clarity {mean_clarity:.1f}"
    return f"hardest stone {stone_id}, average clarity {mean_clarity:.1f}"


def main() -> None:
    batch: list[Stone] = [
        (9, 85, 2.0, 8),
        (12, 70, 4.5, 9),
        (13, 92, 3.2, 7),
        (21, 60, 5.0, 10),
    ]
    runs = [
        ("everything", None, None, None),
        ("carat >= 3", None, 3.0, None),
        ("clarity >= 80, hardness >= 8", 80, None, 8),
        ("hardness >= 11", None, None, 11),
    ]
    for label, min_clarity, min_carat, min_hardness in runs:
        outcome = facet(batch, min_clarity, min_carat, min_hardness)
        print(f"{label}: {describe(outcome)}")
    print(f"single stone, carat >= 3: {facet([(9, 85, 2.0, 8)], carat=3.0)}")


if __name__ == "__main__":
    main()

