from statistics import mean

Joint = tuple[int, int, float, float]


def parse_joint(raw: str) -> Joint | None:
    """Turn a "id, layers, thickness, stress" record into a joint tuple."""
    parts = [part.strip() for part in raw.split(",")]
    if len(parts) != 4:
        return None
    try:
        joint_id = int(parts[0])
        layer_count = int(parts[1])
        total_thickness = float(parts[2])
        stress_rating = float(parts[3])
    except ValueError:
        return None
    return (joint_id, layer_count, total_thickness, stress_rating)


def check_joint(
    joint: Joint,
    max_layers: int | None,
    max_thickness: float | None,
) -> Joint | None:
    """Return the joint when it respects both optional limits, else nothing."""
    _, layer_count, total_thickness, _ = joint
    if max_layers is not None and layer_count > max_layers:
        return None
    if max_thickness is not None and total_thickness > max_thickness:
        return None
    return joint


def lowest_stress_joint(
    joints: list[Joint],
    max_stress: float | None,
) -> int | None:
    """Id of the least stressed joint under the optional stress ceiling."""
    eligible = [j for j in joints if max_stress is None or j[3] <= max_stress]
    if not eligible:
        return None
    return min(eligible, key=lambda joint: joint[3])[0]


def average_layers(joints: list[Joint]) -> float | None:
    if not joints:
        return None
    return mean(joint[1] for joint in joints)


def rivet(
    joints: list[Joint],
    layers: int | None,
    thickness: float | None,
    stress: float | None,
) -> tuple[
    int | None,
    float | None,
]:
    conforming = [
        checked
        for joint in joints
        if (checked := check_joint(joint, layers, thickness)) is not None
    ]
    return lowest_stress_joint(conforming, stress), average_layers(conforming)


def format_report(
    joint_id: int | None,
    avg_layers: float | None,
) -> str:
    best = "none" if joint_id is None else f"#{joint_id}"
    mean_layers = "none" if avg_layers is None else f"{avg_layers:.2f}"
    return f"lowest stress joint: {best}, average layers: {mean_layers}"


def main() -> None:
    records = [
        "8, 3, 10, 50",
        "11, 2, 4, 35",
        "12, 5, 4.5, 60",
        "broken record",
        "13, 4, 3.5, 22",
    ]
    parsed = [joint for line in records if (joint := parse_joint(line)) is not None]
    print(format_report(*rivet(parsed, None, 5, None)))
    print(format_report(*rivet(parsed, 4, 5, 30)))
    print(format_report(*rivet([(8, 3, 10, 50)], None, 5, None)))


if __name__ == "__main__":
    main()

