def parse_limit(
    text: str | None,
) -> int | None:
    """Turn a command line argument into a numeric limit, if one was given."""
    if text is None or not text.strip():
        return None
    return int(text)


def check_string(
    row: Row,
    max_gauge: int | None = None,
    max_tension: int | None = None,
) -> Row | None:
    """Return the string tuple when it respects both optional ceilings."""
    _sid, wire_gauge, tension_weight, _sustain = row
    if max_gauge is not None and wire_gauge > max_gauge:
        return None
    if max_tension is not None and tension_weight > max_tension:
        return None
    return row


def longest_sustain(
    rows: list[Row],
    min_sustain: int | None = None,
) -> StringId:
    """Id of the string that rings longest while clearing the optional floor."""
    best_id: int | None = None
    best_duration = 0
    for sid, _gauge, _tension, duration in rows:
        if min_sustain is not None and duration < min_sustain:
            continue
        if best_id is None or duration > best_duration:
            best_id, best_duration = sid, duration
    return best_id


def string(
    strings: list[Row],
    gauge: int | None = None,
    tension: int | None = None,
    sustain: int | None = None,
) -> Result:
    verified: list[Row] = []
    for row in strings:
        passed = check_string(row, gauge, tension)
        if passed is not None:
            verified.append(passed)
    if not verified:
        return (None, None)
    average = sum(row[1] for row in verified) / len(verified)
    return (longest_sustain(verified, sustain), average)


def format_report(best_id: StringId, average: AverageGauge) -> str:
    winner = "none" if best_id is None else f"#{best_id}"
    mean = "n/a" if average is None else f"{average:.2f}"
    return f"longest sustaining string: {winner}, average gauge: {mean}"


def main(argv: list[str]) -> None:
    catalogue: list[Row] = [
        (1, 12, 160, 15),
        (2, 14, 185, 22),
        (3, 16, 210, 19),
        (4, 11, 140, 9),
    ]
    limits = argv[1:4] + [""] * (3 - len(argv[1:4]))
    result = string(
        catalogue,
        parse_limit(limits[0]),
        parse_limit(limits[1]),
        parse_limit(limits[2]),
    )
