from __future__ import annotations


class Branch:
    def __init__(
        self,
        length: int,
        fruit: str | None = None,
        left: Branch | None = None,
        right: Branch | None = None,
        parent: Branch | None = None,
    ) -> None:
        self.length = length
        self.fruit = fruit
        self.left = left
        self.right = right
        self.parent = parent
        for child in (left, right):
            if child is not None:
                child.parent = self

    def graft(self, side: str, child: Branch) -> Branch:
        if side == "left":
            self.left = child
        elif side == "right":
            self.right = child
        else:
            raise ValueError("side must be 'left' or 'right'")
        child.parent = self
        return child

    def __repr__(self) -> str:
        return f"Branch(length={self.length}, fruit={self.fruit!r})"


def find_fruit(branch: Branch, target: str) -> Branch | None:
    if branch.fruit == target:
        return branch
    for child in (branch.left, branch.right):
        if child is not None:
            found = find_fruit(child, target)
            if found is not None:
                return found
    return None


def highest_ancestor(branch: Branch) -> Branch | None:
    current = branch.parent
    if current is None:
        return None
    while current.parent is not None:
        current = current.parent
    return current


def prune(branch: Branch) -> Branch | None:
    if branch.fruit is None and branch.length < 10:
        return None
    return branch


def describe(result: Branch | None) -> str:
    if result is None:
        return "nothing"
    return repr(result)


def main() -> None:
    trunk = Branch(30)
    limb = trunk.graft("left", Branch(14))
    twig = limb.graft("right", Branch(5))
    bearing = trunk.graft("right", Branch(8, fruit="apple"))

    for branch in (twig, bearing):
        print(f"prune({branch!r}) -> {describe(prune(branch))}")

    print(f"search for 'apple' -> {describe(find_fruit(trunk, 'apple'))}")
    print(f"search for 'plum' -> {describe(find_fruit(trunk, 'plum'))}")
    print(f"root above twig -> {describe(highest_ancestor(twig))}")
    print(f"root above trunk -> {describe(highest_ancestor(trunk))}")


if __name__ == "__main__":
    main()

