from __future__ import annotations


class Room:
    def __init__(self, room_id: int) -> None:
        self.room_id = room_id
        self.north: Room | None = None
        self.south: Room | None = None
        self.up: Room | None = None
        self.key_item: str | None = None

    def connect_north(self, other: Room | None) -> None:
        self.north = other
        if other is not None:
            other.south = self

    def connect_up(self, other: Room | None) -> None:
        self.up = other

    def __repr__(self) -> str:
        return f"Room({self.room_id})"


def find_key_nearby(
    room: Room | None,
    key_item: str,
) -> Room | None:
    if room is None:
        return None
    for candidate in (room, room.north, room.south, room.up):
        if candidate is not None and candidate.key_item == key_item:
            return candidate
    return None


def northernmost(
    room: Room | None,
) -> Room | None:
