from __future__ import annotations


class Tower:
    """A single sand tower that may rest on a foundation and carry walls."""

    def __init__(
        self,
        height: int,
        foundation: Tower | None = None,
        left: Tower | None = None,
        right: Tower | None = None,
        flag: str | None = None,
    ) -> None:
        if height <= 0:
            raise ValueError("a tower must have a positive height")
        self.height = height
        self.foundation = foundation
        self.left = left
        self.right = right
        self.flag = flag


def lowest_base(tower: Tower) -> Tower | None:
    """Descend through the foundations and return the deepest one."""
    base = tower.foundation
    if base is None:
        return None
    while base.foundation is not None:
        base = base.foundation
    return base


def red_flag_wall(tower: Tower) -> Tower | None:
    """Return the first wall tower flying a red flag."""
    for wall in (tower.left, tower.right):
        if wall is not None and wall.flag == "red":
            return wall
    return None


def inspect(tower: Tower) -> str:
    base = lowest_base(tower)
    if base is None:
        return ""
    return base.flag or ""


def total_height(tower: Tower | None) -> int:
    """Sum the heights of a tower and everything attached to it."""
    if tower is None:
        return 0
    return (
        tower.height
        + total_height(tower.foundation)
        + total_height(tower.left)
        + total_height(tower.right)
    )


def warning_for(tower: Tower) -> str | None:
    wall = red_flag_wall(tower)
    if wall is None:
        return None
    return f"red flag raised on a {wall.height}-unit wall tower"


def is_stable(tower: Tower) -> bool:
    base = lowest_base(tower)
    if base is None:
        return True
    return base.height >= tower.height


def report(tower: Tower, name: str | None = None) -> str:
    label = name or "unnamed castle"
    lines = [f"{label}: crown height {tower.height}, total sand {total_height(tower)}"]
    base = lowest_base(tower)
    if base is not None:
        lines.append(f"  lowest foundation height: {base.height}")
    lines.append(f"  foundation flag: {inspect(tower) or '(none)'}")
    warning = warning_for(tower)
    if warning is not None:
        lines.append(f"  warning: {warning}")
    lines.append(f"  stable: {is_stable(tower)}")
    return "\n".join(lines)


def main() -> None:
    bedrock = Tower(9, flag="red")
    plinth = Tower(6, foundation=bedrock)
    keep = Tower(4, foundation=plinth, left=Tower(3, flag="red"), right=Tower(3))
    print(report(keep, "seaside keep"))

    lonely = Tower(5, left=Tower(2, flag="blue"))
    print(report(lonely, "sand pillar"))
    print(f"lonely flag: '{inspect(lonely)}'")


if __name__ == "__main__":
    main()

