from __future__ import annotations


class WaterJet:
    def __init__(
        self,
        pressure: int,
        main: WaterJet | None = None,
        secondary: WaterJet | None = None,
        light: str | None = None,
        music: str | None = None,
    ) -> None:
        self.pressure = pressure
        self.main = main
        self.secondary = secondary
        self.light = light
        self.music = music

    def describe(self) -> str:
        parts = [f"{self.pressure} bar"]
        if self.light is not None:
            parts.append(self.light)
        if self.music is not None:
            parts.append(f"cue={self.music}")
        return " / ".join(parts)


def find_blue_light(jet: WaterJet) -> WaterJet | None:
    for nozzle in (jet.main, jet.secondary):
        if nozzle is not None and nozzle.light == "blue":
            return nozzle
    return None


def main_music_cue(jet: WaterJet) -> str | None:
    main = jet.main
    if main is None:
        return None
    return main.music


def splash(jet: WaterJet) -> list[str]:
    colors: list[str] = []
    for source in (jet, jet.main, jet.secondary):
        if source is None:
            continue
        color: str | None = source.light
        if color is None:
            continue
        colors.append(color)
    return colors


def total_pressure(jet: WaterJet | None) -> int:
    if jet is None:
        return 0
    return jet.pressure + total_pressure(jet.main) + total_pressure(jet.secondary)


def sequence_report(jet: WaterJet) -> str:
    lines = [f"root: {jet.describe()}", f"lights: {', '.join(splash(jet)) or 'none'}"]
    blue: WaterJet | None = find_blue_light(jet)
    lines.append("blue nozzle: " + (blue.describe() if blue is not None else "absent"))
    cue = main_music_cue(jet)
    lines.append("main cue: " + (cue if cue is not None else "silent"))
    lines.append(f"total pressure: {total_pressure(jet)} bar")
    return "\n".join(lines)


def main() -> None:
    main_nozzle = WaterJet(4, light="blue", music="waltz")
    secondary_nozzle = WaterJet(3, light="green")
    fountain = WaterJet(9, main=main_nozzle, secondary=secondary_nozzle)
    print(sequence_report(fountain))
    quiet = WaterJet(2, secondary=WaterJet(1))
    print()
    print(sequence_report(quiet))


if __name__ == "__main__":
    main()

