from __future__ import annotations


class Cog:
    def __init__(self, teeth: int) -> None:
        self.teeth = teeth
        self.driving: Cog | None = None
        self.driven: Cog | None = None
        self.cam: str | None = None
        self.tension: int | None = None

    def link(self, driven: Cog, cam: str | None = None) -> Cog:
        self.driven = driven
        driven.driving = self
        driven.cam = cam
        return driven

    def __repr__(self) -> str:
        return f"Cog({self.teeth})"


def find_spring(cog: Cog) -> Cog | None:
    current: Cog | None = cog
    while current is not None:
        if current.tension is not None:
            return current
        current = current.driving
    return None


def driven_cam(cog: Cog) -> str | None:
    if cog.driven is None:
        return None
    return cog.driven.cam


def wind(cog: Cog) -> int:
    total = cog.teeth
    driver: Cog | None = cog.driving
    if driver is not None:
        total += driver.teeth
    return total


def spring_tension(cog: Cog) -> int | None:
    source = find_spring(cog)
    if source is None:
        return None
    return source.tension


def describe(cog: Cog) -> str:
    cam = driven_cam(cog)
    cam_text = cam if cam is not None else "no cam"
    tension = spring_tension(cog)
    tension_text = str(tension) if tension is not None else "unsprung"
    return f"{cog!r}: wind={wind(cog)}, cam={cam_text}, tension={tension_text}"


def build_train(tooth_counts: list[int], cams: list[str]) -> Cog | None:
    if not tooth_counts:
        return None
    head = Cog(tooth_counts[0])
    tail = head
    for index, teeth in enumerate(tooth_counts[1:]):
        cam: str | None = cams[index] if index < len(cams) else None
        tail = tail.link(Cog(teeth), cam)
    return head


def main() -> None:
    head = build_train([20, 40, 12], ["heart", "snail"])
    if head is None:
        print("empty gear train")
        return
    head.tension = 7
    print(describe(head))
    middle = head.driven
    if middle is not None:
        print(describe(middle))
    print(describe(Cog(15)))


if __name__ == "__main__":
    main()

