from __future__ import annotations


class SuspensionLine:
    """A single rigging line, optionally linked to neighbouring lines."""

    def __init__(
        self,
        strength: int,
        canopy_attachment: SuspensionLine | None = None,
        harness_attachment: SuspensionLine | None = None,
        toggle_color: str | None = None,
        slider_ring_material: str | None = None,
    ) -> None:
        if strength <= 0:
            raise ValueError("line strength must be a positive number of pounds")
        self.strength = strength
        self.canopy_attachment = canopy_attachment
        self.harness_attachment = harness_attachment
        self.toggle_color = toggle_color
        self.slider_ring_material = slider_ring_material


def find_toggle_line(
    line: SuspensionLine | None,
) -> SuspensionLine | None:
    """Follow canopy attachments upward until a line carrying a toggle is found."""
    current = line
    while current is not None:
        if current.toggle_color is not None:
            return current
        current = current.canopy_attachment
    return None


def harness_slider_material(
    line: SuspensionLine | None,
) -> str | None:
    """Read the slider ring material of the harness attachment line."""
    if line is None or line.harness_attachment is None:
        return None
    return line.harness_attachment.slider_ring_material


def weakest_strength(
    line: SuspensionLine | None,
) -> int | None:
    """Smallest strength along the canopy chain, or nothing for an absent line."""
    current = line
    weakest: int | None = None
    while current is not None:
        if weakest is None or current.strength < weakest:
            weakest = current.strength
        current = current.canopy_attachment
    return weakest


def verify(line: SuspensionLine | None) -> tuple[str, str]:
    toggle_line = find_toggle_line(line)
    color: str | None = toggle_line.toggle_color if toggle_line is not None else None
    material = harness_slider_material(line)
    return (color or "", material or "")


def format_report(label: str, line: SuspensionLine | None) -> str:
    color, material = verify(line)
    weakest = weakest_strength(line)
    load = "no line mounted" if weakest is None else f"{weakest} lbf"
    return (
        f"{label}: toggle={color or '(none)'}, "
        f"slider={material or '(none)'}, weakest={load}"
    )


def main() -> None:
    upper = SuspensionLine(750, toggle_color="yellow")
    harness_end = SuspensionLine(900, slider_ring_material="stainless")
    complete = SuspensionLine(820, canopy_attachment=upper, harness_attachment=harness_end)
    bare_harness = SuspensionLine(880)
    missing_slider = SuspensionLine(
        820, canopy_attachment=upper, harness_attachment=bare_harness
    )
    print(format_report("left front riser", complete))
    print(format_report("right front riser", missing_slider))
    print(format_report("spare slot", None))
    print(verify(missing_slider))


if __name__ == "__main__":
    main()

