from __future__ import annotations


class Glyph:
    """A single glyph with its metrics and its place in a run of text."""

    def __init__(
        self,
        advance: int,
        char: str,
        left: Glyph | None = None,
        right: Glyph | None = None,
        ligature: str | None = None,
        kerning: int | None = None,
    ) -> None:
        if not isinstance(advance, int):
            raise TypeError("advance width must be an integer")
        self.advance = advance
        self.char = char
        self.left = left
        self.right = right
        self.ligature = ligature
        self.kerning = kerning


def find_ligature(glyph: Glyph) -> Glyph | None:
    """Return the nearest glyph to the right carrying a ligature replacement."""
    right = glyph.right
    if right is None:
        return None
    if right.ligature is not None:
        return right
    beyond = right.right
    if beyond is not None and beyond.ligature is not None:
        return beyond
    return None


def left_kerning(glyph: Glyph) -> int | None:
    """Return the kerning offset stored on the left neighbour, if any."""
    left = glyph.left
    if left is None:
        return None
    return left.kerning


def kern(glyph: Glyph) -> int:
    total = glyph.advance
    for neighbour in (glyph.left, glyph.right):
        total += neighbour.advance if neighbour is not None else 0
    return total


def build_chain(
    metrics: dict[str, int],
    text: str,
    ligatures: dict[str, str] | None = None,
    pairs: dict[str, int] | None = None,
) -> Glyph | None:
    glyphs: list[Glyph] = []
    for char in text:
        advance: int | None = metrics.get(char)
        if advance is None:
            raise KeyError(f"no advance width for {char!r}")
        glyphs.append(Glyph(advance, char))
    for index, glyph in enumerate(glyphs):
        glyph.left = glyphs[index - 1] if index > 0 else None
        glyph.right = glyphs[index + 1] if index + 1 < len(glyphs) else None
        pair = text[index : index + 2]
        if ligatures is not None:
            glyph.ligature = ligatures.get(pair)
        if pairs is not None:
            glyph.kerning = pairs.get(pair)
    return glyphs[0] if glyphs else None


def format_row(glyph: Glyph) -> str:
    match = find_ligature(glyph)
    replacement: str | None = match.ligature if match is not None else None
    offset = left_kerning(glyph)
    return "{:<4}{:>7}{:>8}{:>8}".format(
        glyph.char,
        kern(glyph),
        replacement if replacement is not None else "-",
        offset if offset is not None else "-",
    )


def main() -> None:
    metrics = {"o": 500, "f": 600, "i": 300, "c": 480, "e": 520, " ": 250, "t": 340}
    ligatures = {"ff": "\ufb00", "fi": "\ufb01"}
    pairs = {"of": -20, "ic": 15, "ff": -35}
    head = build_chain(metrics, "office fit", ligatures, pairs)
    print("char   total    liga  kerning")
    current: Glyph | None = head
    while current is not None:
        print(format_row(current))
        current = current.right


if __name__ == "__main__":
    main()

