from __future__ import annotations


class Peg:
    """A single peg of a knitting loom, linked to its neighbours on the ring."""

    def __init__(
        self,
        tension: int,
        clockwise: Peg | None = None,
        counterclockwise: Peg | None = None,
        yarn: str | None = None,
        marker: str | None = None,
    ) -> None:
        if tension < 0:
            raise ValueError("tension must be non-negative")
        self.tension = tension
        self.clockwise = clockwise
        self.counterclockwise = counterclockwise
        self.yarn = yarn
        self.marker = marker


def find_marked_peg(
    peg: Peg | None,
) -> Peg | None:
    """Walk clockwise from ``peg`` until a peg carrying a stitch marker is found."""
    start = peg
    current = peg
    while current is not None:
        if current.marker is not None:
            return current
        current = current.clockwise
        if current is start:
            break
    return None


def counterclockwise_yarn(
    peg: Peg | None,
) -> str | None:
    """Return the active yarn colour held by the counterclockwise neighbour."""
    if peg is None or peg.counterclockwise is None:
        return None
    return peg.counterclockwise.yarn


def knit(peg: Peg | None) -> tuple[str, str]:
    marked = find_marked_peg(peg)
    marker: str | None = marked.marker if marked is not None else None
    yarn = counterclockwise_yarn(peg)
    return (marker or "", yarn or "")


def build_ring(
    tensions: list[int],
    yarns: list[str | None],
    markers: list[str | None],
) -> Peg | None:
    if not tensions:
        return None
    pegs = [Peg(t, yarn=y, marker=m) for t, y, m in zip(tensions, yarns, markers)]
    for index, current in enumerate(pegs):
        current.clockwise = pegs[(index + 1) % len(pegs)]
        current.counterclockwise = pegs[index - 1]
    return pegs[0]


def describe(peg: Peg | None) -> str:
    if peg is None:
        return "empty loom"
    marker, yarn = knit(peg)
    return f"tension={peg.tension} marker={marker!r} yarn={yarn!r}"


def main() -> None:
    plain = build_ring([4, 5, 6], [None, None, None], [None, "lifeline", None])
    print(describe(plain))
    dressed = build_ring([3, 3], ["teal", "rust"], ["start", None])
    print(describe(dressed))
    print(describe(build_ring([], [], [])))
    print(knit(None))


if __name__ == "__main__":
    main()

