from __future__ import annotations


class LiftLevel:
    """A single landing in a mine shaft, linked to its neighbours."""

    def __init__(
        self,
        depth: int,
        up: LiftLevel | None = None,
        down: LiftLevel | None = None,
        miner: str | None = None,
        hazard: str | None = None,
    ) -> None:
        if not isinstance(depth, int):
            raise TypeError("depth must be an integer")
        self.depth = depth
        self.up = up
        self.down = down
        self.miner = miner
        self.hazard = hazard

    def __repr__(self) -> str:
        return f"LiftLevel({self.depth}m)"


def couple(upper: LiftLevel, lower: LiftLevel) -> None:
    """Join two landings so the lift can travel between them."""
    upper.down = lower
    lower.up = upper


def build_shaft(
    depths: list[int],
    miners: dict[int, str] | None = None,
    hazards: dict[int, str] | None = None,
) -> LiftLevel:
    """Create the linked chain of landings and return the topmost one."""
    if not depths:
        raise ValueError("a shaft needs at least one level")
    miners = miners or {}
    hazards = hazards or {}
    ordered = sorted(depths)
    levels = [LiftLevel(d, miner=miners.get(d), hazard=hazards.get(d)) for d in ordered]
    for upper, lower in zip(levels, levels[1:]):
        couple(upper, lower)
    return levels[0]


def find_waiting_miner(level: LiftLevel) -> LiftLevel | None:
    """Search this level and everything above it for a waiting miner."""
    node: LiftLevel | None = level
    while node is not None:
        if node.miner:
            return node
        node = node.up
    return None


def hazard_below(level: LiftLevel) -> str | None:
    """Report the hazard alert posted on the next level down, if any."""
    below = level.down
    if below is None:
        return None
    return below.hazard


def hoist(level: LiftLevel) -> tuple[str, str]:
    found = find_waiting_miner(level)
    alert = hazard_below(level)
    return (found.miner if found is not None and found.miner else "", alert or "")


def find_level(top: LiftLevel, depth: int) -> LiftLevel | None:
    node = top
    while node.depth != depth:
        if node.down is None:
            return None
        node = node.down
    return node


def describe(depth: int, miner: str, hazard: str) -> str:
    who = miner or "nobody waiting"
    warning = hazard or "no hazard"
    return f"{depth:>4}m -> hoisting {who}; {warning}"


def main() -> None:
    top = build_shaft(
        [0, 50, 100, 150, 200],
        miners={150: "John", 50: "Aisha"},
        hazards={200: "gas leak"},
    )
    for depth in (150, 100, 175, 50):
        start: LiftLevel | None = find_level(top, depth)
        if start is None:
            print(f"{depth:>4}m -> no such level in this shaft")
            continue
        miner, hazard = hoist(start)
        print(describe(depth, miner, hazard))


if __name__ == "__main__":
    main()

