from __future__ import annotations

from dataclasses import dataclass

ZONES = {
    "London": 1,
    "Berlin": 2,
    "Chicago": 3,
    "Beijing": 4,
}


@dataclass
class Find:
    species: str
    age: int | None = None
    bone: str | None = None
    weight: float | None = None
    museum: str | None = None
    complete: bool | None = None


def classify_era(
    age: int | None,
) -> str | None:
    if age is None or age <= 0:
        return None
    if age >= 252:
        return "Paleozoic"
    if age >= 66:
        return "Mesozoic"
    return "Cenozoic"


def shipping_zone(
    museum: str | None,
) -> int | None:
    if museum is None:
        return None
    return ZONES.get(museum.strip().title())


def heavy_enough(weight: float | None) -> bool:
    return weight is not None and weight > 10.0


def summarize(
    find: Find,
    era: str | None,
    zone: int | None,
) -> str:
    era_text = era if era is not None else "undated"
    zone_text = f"zone {zone}" if zone is not None else "unshippable"
    detail = find.bone if find.bone is not None else "unspecified bone"
    skeleton = "full skeleton" if find.complete else "partial"
    return f"{find.species}: {era_text}, {zone_text}, {detail}, {skeleton}"


def register(finds: list[Find], urgency: bool | None = None) -> int:
    header = "PRIORITY REGISTRATION" if urgency else "routine registration"
    print(header)
    valid = 0
    for find in finds:
        era = classify_era(find.age)
        zone = shipping_zone(find.museum)
        print("  " + summarize(find, era, zone))
        if era is not None and zone is not None and heavy_enough(find.weight):
            valid += 1
    print(f"  valid finds: {valid}")
    return valid


def main() -> None:
    raptor_batch = [Find("Raptor", bone="femur", weight=12.5)]
    register(raptor_batch)
    mixed_batch = [
