from __future__ import annotations

from dataclasses import dataclass
from typing import Optional

ZONES = {
    "London": 1,
    "Berlin": 2,
    "Chicago": 3,
    "Beijing": 4,
}


@dataclass
class Find:
    species: str
    age: Optional[int] = None
    bone: Optional[str] = None
    weight: Optional[float] = None
    museum: Optional[str] = None
    complete: Optional[bool] = None


def classify_era(
    age: Optional[int],
) -> Optional[str]:
    if age is None or age <= 0:
        return None
    if age >= 252:
        return "Paleozoic"
    if age >= 66:
        return "Mesozoic"
    return "Cenozoic"


def shipping_zone(
    museum: Optional[str],
) -> Optional[int]:
    if museum is None:
        return None
    return ZONES.get(museum.strip().title())


def heavy_enough(weight: Optional[float]) -> bool:
    return weight is not None and weight > 10.0


def summarize(
    find: Find,
    era: Optional[str],
    zone: Optional[int],
) -> str:
    era_text = era if era is not None else "undated"
    zone_text = f"zone {zone}" if zone is not None else "unshippable"
    detail = find.bone if find.bone is not None else "unspecified bone"
    skeleton = "full skeleton" if find.complete else "partial"
    return f"{find.species}: {era_text}, {zone_text}, {detail}, {skeleton}"


def register(finds: list[Find], urgency: Optional[bool] = None) -> int:
    header = "PRIORITY REGISTRATION" if urgency else "routine registration"
    print(header)
    valid = 0
    for find in finds:
        era = classify_era(find.age)
        zone = shipping_zone(find.museum)
        print("  " + summarize(find, era, zone))
        if era is not None and zone is not None and heavy_enough(find.weight):
            valid += 1
    print(f"  valid finds: {valid}")
    return valid


def main() -> None:
    raptor_batch = [Find("Raptor", bone="femur", weight=12.5)]
    register(raptor_batch)
    mixed_batch = [
        Find("Triceratops", 68, "skull", 240.0, "berlin", True),
        Find("Trilobite", 400, "carapace", 0.4, "London", True),
        Find("Mammoth", 10, "tusk", 30.0, "Chicago"),
        Find("Stegosaurus", 150, "plate", 18.0, "Atlantis"),
    ]
    register(mixed_batch, urgency=True)


if __name__ == "__main__":
    main()

