    carriage_return_ok: bool | None = None
    rusted_parts: bool | None = None


def rarity_score(
    year: int | None,
) -> int | None:
    if year is None:
        return None
    age = 2026 - year
    score = max(age, 0) // 5
    if year < 1900:
        score += 20
    return score


def repair_cost(
    missing_keys: int | None,
) -> float | None:
    if missing_keys is None:
        return 0.0
    if missing_keys > 5:
        return None
    return 18.5 * missing_keys


def apply_discount(cost: float, discount: float | None) -> float:
    if discount is None:
        return cost
    return cost * (1.0 - discount)


def ribbon_label(color: str | None) -> str:
    if color is None:
        return "unribboned"
    return color.strip().lower()


def condition_note(
    rusted: bool | None,
) -> str | None:
    if rusted is None:
        return None
    return "needs derusting" if rusted else "clean"


def describe(machine: Typewriter, discount: float | None = None) -> str:
    score = rarity_score(machine.year)
    cost = repair_cost(machine.missing_keys)
    parts = [machine.brand, ribbon_label(machine.ribbon_color)]
    parts.append("rarity ?" if score is None else f"rarity {score}")
    if cost is None:
        parts.append("beyond repair")
    else:
        parts.append(f"${apply_discount(cost, discount):.2f}")
    note = condition_note(machine.rusted_parts)
    if note is not None:
        parts.append(note)
    return " | ".join(parts)


def assess(machines: list[Typewriter], discount: float | None = None) -> list[str]:
    keepers = []
    for machine in machines:
        if rarity_score(machine.year) is None:
            continue
        if repair_cost(machine.missing_keys) is None:
            continue
        if not machine.carriage_return_ok:
            continue
        keepers.append(machine.brand)
    if discount is not None and discount > 0.5:
        keepers.reverse()
    return keepers


