@dataclass
class Score:
    composer: str
    completion_year: int | None = None
    tempo_marking: str | None = None
    key_signature: str | None = None
    dedication: str | None = None
    missing_pages: int | None = None


def period(
    completion_year: int | None,
) -> str | None:
    if completion_year is None:
        return None
    if completion_year < 1600:
        return "renaissance"
    if completion_year < 1750:
        return "baroque"
    if completion_year < 1820:
        return "classical"
    if completion_year < 1900:
        return "romantic"
    return "modern"


def restoration_effort(
    missing_pages: int | None,
) -> float | None:
    if missing_pages is None:
        return None
    if missing_pages > 10:
        return None
    return round(missing_pages * 1.75 + 0.5, 2)


def tempo_label(tempo_marking: str | None) -> str:
    if tempo_marking is None:
        return "tempo unmarked"
    return tempo_marking.strip().lower()


def dedication_note(dedication: str | None) -> str:
    if dedication is None:
        return "no dedicatee"
    return "dedicated to " + dedication


def apply_limit(composers: list[str], limit: int | None) -> list[str]:
    if limit is None:
        return composers
    if limit < 0:
        raise ValueError("display limit must not be negative")
    return composers[:limit]


def catalog(scores: list[Score], limit: int | None = None) -> list[str]:
    selected: list[str] = []
    for score in scores:
        if period(score.completion_year) is None:
            continue
        if restoration_effort(score.missing_pages) is None:
            continue
        if score.key_signature is None:
            continue
        selected.append(score.composer)
    return apply_limit(selected, limit)


def describe(score: Score) -> str:
    era: str | None = period(score.completion_year)
    effort: float | None = restoration_effort(score.missing_pages)
    parts = [score.composer, era or "period unknown", tempo_label(score.tempo_marking)]
    parts.append(score.key_signature or "key unknown")
    parts.append(dedication_note(score.dedication))
    parts.append("restoration hours: %s" % ("n/a" if effort is None else effort))
    return " | ".join(parts)


def main() -> None:
    library = [
        Score("Bach", tempo_marking="Allegro", key_signature="D minor"),
        Score("Mozart", 1788, "Molto allegro", "G minor", "Baron van Swieten", 2),
        Score("Brahms", 1876, key_signature="C minor", missing_pages=14),
        Score("Vivaldi", 1725, "Presto", "F major", missing_pages=0),
    ]
    print(catalog([library[0]]))
    print(catalog(library))
    print(catalog(library, 1))
    for score in library:
        print(describe(score))


if __name__ == "__main__":
    main()

