from dataclasses import dataclass


@dataclass
class DiveRecord:
    vessel: str
    depth: int | None = None
    visibility: int | None = None
    artifact: str | None = None
    current_speed: float | None = None
    hazard_warning: bool | None = None


def certification_requirement(
    depth: int | None,
) -> str | None:
    if depth is None:
        return None
    if depth < 18:
        return "Open Water"
    if depth < 40:
        return "Advanced Open Water"
    return "Technical Trimix"


def safety_rating(
    visibility: int | None,
) -> float | None:
    if visibility is None or visibility < 5:
        return None
    return round(min(10.0, visibility / 3.0), 2)


def is_approved(dive: DiveRecord) -> bool:
    certification: str | None = certification_requirement(dive.depth)
    rating: float | None = safety_rating(dive.visibility)
    return certification is not None and rating is not None and not dive.hazard_warning


def describe(dive: DiveRecord) -> str:
    certification = certification_requirement(dive.depth)
    rating = safety_rating(dive.visibility)
    parts = [dive.vessel]
    parts.append(certification if certification else "depth unknown")
    parts.append(f"rating {rating}" if rating is not None else "rating unavailable")
    speed: float | None = dive.current_speed
    if speed is not None:
        parts.append(f"{speed:.1f} kn current")
    artifact: str | None = dive.artifact
    if artifact is not None:
        parts.append(f"recovered {artifact}")
    return " | ".join(parts)


def review(dives: list[DiveRecord], vessel_filter: str | None = None) -> int:
    approved = 0
    for dive in dives:
        if vessel_filter is not None and vessel_filter.lower() not in dive.vessel.lower():
            continue
        if is_approved(dive):
            approved += 1
    return approved


def deepest_vessel(dives: list[DiveRecord]) -> str | None:
    best: DiveRecord | None = None
    for dive in dives:
        if dive.depth is None:
            continue
        if best is None or dive.depth > best.depth:
            best = dive
    return best.vessel if best is not None else None


def main() -> None:
    dives = [
        DiveRecord("Titanic"),
        DiveRecord("Andrea Doria", depth=75, visibility=12, current_speed=1.4),
        DiveRecord("Vasa", depth=32, visibility=9, artifact="bronze cannon"),
        DiveRecord("Lusitania", depth=93, visibility=7, hazard_warning=True),
        DiveRecord("Thistlegorm", depth=30, visibility=3, current_speed=0.8),
    ]
    for dive in dives:
        print(describe(dive))
    print("approved overall:", review(dives))
    print("approved (titanic):", review(dives, "titanic"))
    print("deepest:", deepest_vessel(dives))


if __name__ == "__main__":
    main()

