from dataclasses import dataclass


INTENSITY_ORDER = ["weak", "moderate", "strong", "storm"]


@dataclass
class CelestialEvent:
    shower_name: str
    peak_rate: int | None = None
    radiant: str | None = None
    moon_illumination: float | None = None
    parent_comet: str | None = None
    cloud_cover: bool | None = None


def classify_rate(
    peak_rate: int | None,
) -> str | None:
    if peak_rate is None or peak_rate == 0:
        return None
    if peak_rate <= 20:
        return "weak"
    if peak_rate <= 60:
        return "moderate"
    if peak_rate <= 100:
        return "strong"
    return "storm"


def visibility_multiplier(
    moon_illumination: float | None,
) -> float | None:
    if moon_illumination is None:
        return None
    if moon_illumination > 0.8:
        return None
    return round(1.0 - moon_illumination * 0.75, 3)


def intensity_rank(category: str | None) -> int:
    if category is None:
        return -1
    return INTENSITY_ORDER.index(category)


def describe(event: CelestialEvent, multiplier: float | None) -> str:
    parent = event.parent_comet or "unknown parent"
    if multiplier is None:
        return f"{event.shower_name}: moonlight or lunar data unusable ({parent})"
    radiant = event.radiant or "unplotted radiant"
    return f"{event.shower_name}: x{multiplier:.2f} from {radiant} ({parent})"


def analyze(events: list[CelestialEvent], min_intensity: str | None = None) -> int:
    threshold = intensity_rank(min_intensity)
    favorable = 0
    for event in events:
        category = classify_rate(event.peak_rate)
        if category is None or intensity_rank(category) < threshold:
            continue
        multiplier = visibility_multiplier(event.moon_illumination)
        if multiplier is None or event.cloud_cover:
            continue
        favorable += 1
    return favorable


def main() -> None:
    events = [
        CelestialEvent("Perseids"),
        CelestialEvent("Geminids", 120, "Gemini", 0.15, "3200 Phaethon", False),
        CelestialEvent("Orionids", 20, "Orion", 0.4, "1P/Halley", True),
        CelestialEvent("Quadrantids", 80, moon_illumination=0.95, cloud_cover=False),
        CelestialEvent("Lyrids", 18, "Lyra", 0.3, "C/1861 G1", False),
    ]
    for event in events:
        print(describe(event, visibility_multiplier(event.moon_illumination)))
    print("favorable (any intensity):", analyze(events))
    print("favorable (strong+):", analyze(events, "strong"))
    print("Perseids alone:", analyze([events[0]]))


if __name__ == "__main__":
    main()

