from typing import Sequence

LAYERS = ("ground", "understory", "midstory", "canopy")


@dataclass
class NestRecord:
    species: str
    tree_type: str | None = None
    egg_count: int | None = None
    nest_height: float | None = None
    material: str | None = None
    predator_present: bool | None = None


def viability_score(
    egg_count: int | None = None,
) -> float | None:
    if egg_count is None or egg_count == 0:
        return None
    return round(min(egg_count, 6) / 6.0, 3)


def canopy_layer(
    nest_height: float | None = None,
) -> str | None:
    if nest_height is None:
        return None
    if nest_height < 1.5:
        return "ground"
    if nest_height < 5.0:
        return "understory"
    if nest_height < 12.0:
        return "midstory"
    return "canopy"


def parse_count(
    raw: str | None,
) -> int | None:
    if raw is None or not raw.strip():
        return None
    return int(raw.strip())


def parse_height(
    raw: str | None,
) -> float | None:
    if raw is None or not raw.strip():
        return None
    return float(raw.strip())


def parse_flag(raw: str | None) -> bool:
    if raw is None or not raw.strip():
        return False
    return raw.strip().lower() in ("yes", "true", "1")


def record_from_row(row: Sequence[str | None]) -> NestRecord:
    species, tree, eggs, height, material, predator = row
    if species is None or not species.strip():
        raise ValueError("a survey record needs a bird species")
    return NestRecord(
        species=species.strip(),
        tree_type=tree.strip() if tree and tree.strip() else None,
        egg_count=parse_count(eggs),
        nest_height=parse_height(height),
        material=material.strip() if material and material.strip() else None,
        predator_present=parse_flag(predator),
    )


def is_secure(nest: NestRecord, target_layer: str | None = None) -> bool:
    if viability_score(nest.egg_count) is None:
        return False
    layer = canopy_layer(nest.nest_height)
    if layer is None:
        return False
    if target_layer is not None and layer != target_layer:
        return False
    return not bool(nest.predator_present)


def describe(nest: NestRecord) -> str:
    score = viability_score(nest.egg_count)
    layer = canopy_layer(nest.nest_height)
    tree = nest.tree_type or "unidentified tree"
    stuff = nest.material or "unrecorded material"
    return (
        f"{nest.species} in {tree} ({stuff}): "
        f"score={score if score is not None else 'n/a'}, "
        f"layer={layer if layer is not None else 'n/a'}"
    )


def survey(nests: Sequence[NestRecord], target_layer: str | None = None) -> int:
    return sum(1 for nest in nests if is_secure(nest, target_layer))


def main() -> None:
    rows: list[Sequence[str | None]] = [
        ("Robin", "oak", None, None, "twigs and mud", "no"),
        ("Blue Tit", "birch", "8", "3.2", "moss", "no"),
        ("Rook", "elm", "4", "18.0", None, "yes"),
        ("Wren", None, "5", "1.0", "grass", ""),
        ("Chaffinch", "pine", "0", "7.5", "lichen", "no"),
    ]
    nests = [record_from_row(row) for row in rows]
    for nest in nests:
        print(describe(nest))
    print("secure nests:", survey(nests))
    for layer in LAYERS:
        print(f"secure {layer} nests:", survey(nests, layer))
    print("robin only:", survey(nests[:1]))


if __name__ == "__main__":
    main()

