from dataclasses import dataclass


@dataclass
class TastingNote:
    origin_region: str
    flush_season: str | None = None
    liquor_color: str | None = None
    steeping_time: int | None = None
    flavor_note: str | None = None
    astringent: bool | None = None


QUALITY_TIERS = {"first flush": 3, "second flush": 2, "monsoon": 1, "autumnal": 2}


def brew_strength(
    steeping_time: int | None,
) -> str | None:
    if steeping_time is None or steeping_time < 60:
        return None
    if steeping_time < 150:
        return "light"
    if steeping_time < 300:
        return "balanced"
    return "robust"


def quality_tier(
    flush_season: str | None,
) -> int | None:
    if flush_season is None:
        return None
    return QUALITY_TIERS.get(flush_season.strip().lower())


def color_matches(
    liquor_color: str | None,
    expected_color: str | None,
) -> bool:
    if expected_color is None:
        return True
    if liquor_color is None:
        return False
    return liquor_color.strip().lower() == expected_color.strip().lower()


def evaluate(
    teas: list[TastingNote],
    expected_color: str | None = None,
) -> list[str]:
    selected = []
    for tea in teas:
        if brew_strength(tea.steeping_time) is None:
            continue
        if quality_tier(tea.flush_season) is None:
            continue
        if tea.astringent:
            continue
        if not color_matches(tea.liquor_color, expected_color):
            continue
        selected.append(tea.origin_region)
    return selected


def describe(tea: TastingNote) -> str:
    strength = brew_strength(tea.steeping_time)
    tier = quality_tier(tea.flush_season)
    parts = [tea.origin_region]
    parts.append(f"strength={strength or 'unknown'}")
    parts.append(f"tier={tier if tier is not None else 'unrated'}")
    if tea.flavor_note is not None:
        parts.append(f"note={tea.flavor_note}")
    return " | ".join(parts)


def main() -> None:
    teas = [
        TastingNote("Darjeeling", liquor_color="amber", flavor_note="muscatel"),
        TastingNote("Assam", "second flush", "coppery", 240, "malty", False),
        TastingNote("Nilgiri", "monsoon", "amber", 320, astringent=True),
        TastingNote("Kangra", "first flush", "pale gold", 180, "floral"),
    ]
    for tea in teas:
        print(describe(tea))
    print("all matching:", evaluate(teas))
    print("amber only:", evaluate(teas, "amber"))


if __name__ == "__main__":
    main()

