from dataclasses import dataclass


@dataclass
class GlacierSurvey:
    name: str
    retreat_rate: float | None = None
    terminus_elevation: int | None = None
    meltwater_volume: float | None = None
    flow_speed: float | None = None
    bedrock_exposed: bool | None = None


def danger_level(
    retreat_rate: float | None,
) -> str | None:
    if retreat_rate is None:
        return None
    if retreat_rate >= 30.0:
        return "critical"
    if retreat_rate >= 15.0:
        return "severe"
    if retreat_rate >= 5.0:
        return "elevated"
    return None


def climate_zone(
    terminus_elevation: int | None,
) -> str | None:
    if terminus_elevation is None or terminus_elevation < 500:
        return None
    if terminus_elevation < 1500:
        return "temperate"
    if terminus_elevation < 2500:
        return "subalpine"
    return "alpine"


def _parse_float(text: str) -> float | None:
    text = text.strip()
    return float(text) if text else None


def _parse_int(text: str) -> int | None:
    text = text.strip()
    return int(text) if text else None


def _parse_bool(text: str) -> bool | None:
    text = text.strip().lower()
    if text in ("yes", "true", "1"):
        return True
    if text in ("no", "false", "0"):
        return False
    return None


def parse_survey(line: str) -> GlacierSurvey | None:
    fields = line.split(",")
    if len(fields) != 6 or not fields[0].strip():
        return None
    return GlacierSurvey(
        name=fields[0].strip(),
        retreat_rate=_parse_float(fields[1]),
        terminus_elevation=_parse_int(fields[2]),
        meltwater_volume=_parse_float(fields[3]),
        flow_speed=_parse_float(fields[4]),
        bedrock_exposed=_parse_bool(fields[5]),
    )


def monitor(glaciers: list[GlacierSurvey], level: str | None = None) -> list[str]:
    flagged: list[str] = []
    for glacier in glaciers:
        danger: str | None = danger_level(glacier.retreat_rate)
        if danger is None or (level is not None and danger != level):
            continue
        zone = climate_zone(glacier.terminus_elevation)
        if zone is None or glacier.bedrock_exposed:
            continue
        flagged.append(glacier.name)
    return flagged


def total_meltwater(glaciers: list[GlacierSurvey]) -> float | None:
    reported = [g.meltwater_volume for g in glaciers if g.meltwater_volume is not None]
    return sum(reported) if reported else None


def fastest_flow(glaciers: list[GlacierSurvey]) -> str | None:
    measured = [g for g in glaciers if g.flow_speed is not None]
    if not measured:
        return None
    return max(measured, key=lambda g: g.flow_speed).name


def main() -> None:
    raw = [
        "Rhone,18.4,2100,0.62,41.0,no",
        "Aletsch,7.1,1600,1.85,58.5,false",
        "Pasterze,32.0,2400,0.41,33.2,yes",
        "Hidden Ice,,,,,",
        "Briksdal,21.9,300,0.95,,no",
    ]
    surveys = [s for s in (parse_survey(line) for line in raw) if s is not None]
    print("all flagged:", monitor(surveys))
    print("severe only:", monitor(surveys, "severe"))
    print("critical only:", monitor(surveys, "critical"))
    volume = total_meltwater(surveys)
    print("meltwater:", "unreported" if volume is None else f"{volume:.2f} km3")
    print("fastest flow:", fastest_flow(surveys))


if __name__ == "__main__":
    main()

