from dataclasses import dataclass


@dataclass
class Album:
    artist: str
    pressing_year: int | None = None
    sleeve_condition: str | None = None
    media_grade: str | None = None
    rpm_speed: int | None = None
    scratched: bool | None = None


def vintage_status(pressing_year: int | None) -> str | None:
    if pressing_year is None:
        return None
    if pressing_year > 2000:
        return None
    if pressing_year < 1960:
        return "antique pressing"
    if pressing_year < 1980:
        return "classic pressing"
    return "late vintage pressing"


def market_value(media_grade: str | None) -> float | None:
    if media_grade is None:
        return None
    grade = media_grade.strip().lower()
    table = {"mint": 120.0, "near mint": 90.0, "very good": 55.0, "good": 30.0}
    if grade in ("poor", "fair"):
        return None
    return table.get(grade, 20.0)


def sleeve_bonus(sleeve_condition: str | None) -> float:
    if sleeve_condition is None:
        return 0.0
    return 15.0 if sleeve_condition.strip().lower() in ("mint", "near mint") else 0.0


def appraise(album: Album) -> float | None:
    value = market_value(album.media_grade)
    if value is None:
        return None
    return value + sleeve_bonus(album.sleeve_condition)


def describe(album: Album) -> str:
    status = vintage_status(album.pressing_year)
    value = appraise(album)
    parts = [album.artist]
    parts.append(status if status is not None else "modern pressing")
    parts.append(f"${value:.2f}" if value is not None else "unpriced")
    if album.rpm_speed is not None:
        parts.append(f"{album.rpm_speed} rpm")
    return " | ".join(parts)


def grade(albums: list[Album], minimum_value: float | None = None) -> int:
    threshold = 0.0 if minimum_value is None else minimum_value
    premium = 0
    for album in albums:
        if vintage_status(album.pressing_year) is None:
            continue
        value = appraise(album)
        if value is None or value < threshold:
            continue
        if album.scratched:
            continue
        premium += 1
    return premium


def main() -> None:
    collection = [
        Album("Miles Davis", 1959, "near mint", "mint", 33, False),
        Album("Fleetwood Mac", 1977, "good", "very good", 33, True),
        Album("The Clash", 1979, None, "good", 45, False),
        Album("Unknown Artist"),
        Album("Modern Act", 2015, "mint", "mint", 33, False),
    ]
    for album in collection:
        print(describe(album))
    print("premium (any value):", grade(collection))
    print("premium (>= 100):", grade(collection, 100.0))


if __name__ == "__main__":
    main()

