@dataclass
class AntiqueTool:
    blade_brand: str
    blade_width: float | None = None
    sole_material: str | None = None
    tote_condition: str | None = None
    frog_angle: int | None = None
    rusted_body: bool = False


def usage_category(
    blade_width: float | None,
) -> str | None:
    if blade_width is None:
        return None
    if blade_width <= 0.0 or blade_width > 3.5:
        return None
    if blade_width < 1.5:
        return "trimming"
    if blade_width < 2.5:
        return "general"
    return "jointing"


def smoothing_performance(
    frog_angle: int | None,
) -> float | None:
    if frog_angle is None:
        return None
    if frog_angle < 35 or frog_angle > 60:
        return None
    return round(1.0 - abs(frog_angle - 45) / 45.0, 3)


def parse_width(
    text: str | None,
) -> float | None:
    if text is None or not text.strip():
        return None
    return float(text)


def parse_angle(
    text: str | None,
) -> int | None:
    if text is None or not text.strip():
        return None
    return int(text)


def build_tool(
    brand: str,
    width_text: str | None,
    material: str | None,
    tote: str | None,
    angle_text: str | None,
    rusted: bool,
) -> AntiqueTool:
    return AntiqueTool(
        blade_brand=brand,
        blade_width=parse_width(width_text),
        sole_material=material,
        tote_condition=tote,
        frog_angle=parse_angle(angle_text),
        rusted_body=rusted,
    )


def describe_tote(tote_condition: str | None) -> str:
    return tote_condition if tote_condition else "unrecorded"


def format_row(tool: AntiqueTool) -> str:
    category = usage_category(tool.blade_width)
    score = smoothing_performance(tool.frog_angle)
    score_text = "--" if score is None else format(score, ".2f")
    return "{:<14} {:<9} {:<5} tote={}".format(
        tool.blade_brand, category or "--", score_text, describe_tote(tool.tote_condition)
    )


def review(tools: list[AntiqueTool], material: str | None = None) -> list[str]:
    brands = []
    for tool in tools:
        if tool.rusted_body:
            continue
        if material is not None and tool.sole_material != material:
            continue
        if usage_category(tool.blade_width) is None:
            continue
        if smoothing_performance(tool.frog_angle) is None:
            continue
        brands.append(tool.blade_brand)
    return brands


def main() -> None:
    raw_records = [
        ("Stanley", "", "cast iron", "cracked", "", False),
        ("Record", "2.0", "cast iron", "sound", "45", False),
        ("Millers Falls", "1.25", "bronze", None, "50", True),
        ("Sargent", "2.75", "cast iron", "sound", "42", False),
    ]
    tools = [build_tool(*record) for record in raw_records]
    for tool in tools:
        print(format_row(tool))
    print("cast iron picks:", review(tools, "cast iron"))
    print("any material:", review(tools))
    print("stanley only:", review([tools[0]]))


if __name__ == "__main__":
