from dataclasses import dataclass


@dataclass
class Panel:
    location: str
    came_thickness: float | None = None
    glass_color: str | None = None
    flux_type: str | None = None
    crack_length: float | None = None
    bowing_warped: bool = False


def structural_rating(
    came_thickness: float | None,
) -> str | None:
    if came_thickness is None or came_thickness < 1.5:
        return None
    if came_thickness < 3.0:
        return "adequate"
    if came_thickness < 5.0:
        return "sturdy"
    return "reinforced"


def repair_urgency(
    crack_length: float | None,
) -> int | None:
    if crack_length is None or crack_length <= 10.0:
        return None
    return min(5, 1 + int((crack_length - 10.0) // 15.0))


def is_critical(panel: Panel, urgency_limit: int | None) -> bool:
    rating = structural_rating(panel.came_thickness)
    urgency = repair_urgency(panel.crack_length)
    if rating is None or urgency is None or not panel.bowing_warped:
        return False
    if urgency_limit is not None and urgency < urgency_limit:
        return False
    return True


def assess(panels: list[Panel], urgency_limit: int | None = None) -> int:
    return sum(1 for panel in panels if is_critical(panel, urgency_limit))


def describe(panel: Panel) -> str:
    rating = structural_rating(panel.came_thickness)
    urgency = repair_urgency(panel.crack_length)
    parts = [panel.location]
    parts.append(f"rating={rating or 'unrated'}")
    parts.append(f"urgency={urgency if urgency is not None else '-'}")
    parts.append(f"color={panel.glass_color or 'unknown'}")
    if panel.flux_type is not None:
        parts.append(f"flux={panel.flux_type}")
    if panel.bowing_warped:
        parts.append("bowing")
    return " | ".join(parts)


def worst_location(panels: list[Panel]) -> str | None:
    scored = [
        (urgency, p.location)
        for urgency, p in ((repair_urgency(p.crack_length), p) for p in panels)
        if urgency is not None
    ]
    if not scored:
        return None
    return max(scored)[1]


def main() -> None:
    panels = [
        Panel("north transept", 4.2, "cobalt", "rosin", 38.0, True),
        Panel("west rose", 2.0, "ruby", None, 12.5, True),
        Panel("south aisle", None, "amber", "oleic", None, True),
        Panel("clerestory 3", 6.0, None, "rosin", 70.0, False),
        Panel("vestry", 1.2, "green", None, 55.0, True),
    ]
    for panel in panels:
        print(describe(panel))
    print("critical:", assess(panels))
    print("critical (urgency >= 3):", assess(panels, 3))
    print("worst:", worst_location(panels) or "none")


if __name__ == "__main__":
    main()

