@dataclass
class Pen:
    model: str
    nib_size: int | None = None
    filling_mechanism: str | None = None
    barrel_material: str | None = None
    ink_capacity: float | None = None
    cracked_section: bool | None = None


NIB_STROKES = {1: "extra-fine", 2: "fine", 3: "medium", 4: "broad"}


def stroke_width(
    nib_size: int | None,
) -> str | None:
    if nib_size is None:
        return None
    return NIB_STROKES.get(nib_size)


def writing_duration(
    ink_capacity: float | None,
) -> float | None:
    if ink_capacity is None or ink_capacity < 0.3:
        return None
    return round(ink_capacity * 4.5, 2)


def grade(pens: list[Pen], target: str | None = None) -> list[str]:
    good: list[str] = []
    for pen in pens:
        stroke = stroke_width(pen.nib_size)
        if stroke is None:
            continue
        if target is not None and stroke != target:
            continue
        if writing_duration(pen.ink_capacity) is None:
            continue
        if pen.cracked_section:
            continue
        good.append(pen.model)
    return good


def describe(pen: Pen) -> str:
    stroke = stroke_width(pen.nib_size)
    hours: float | None = writing_duration(pen.ink_capacity)
    parts = [pen.model, stroke if stroke is not None else "unknown stroke"]
    if hours is not None:
        parts.append(f"{hours} h of writing")
    if pen.barrel_material is not None:
        parts.append(pen.barrel_material)
    if pen.filling_mechanism is not None:
        parts.append(pen.filling_mechanism)
    return " | ".join(parts)


def heaviest_barrel(pens: list[Pen]) -> str | None:
    materials = sorted({p.barrel_material for p in pens if p.barrel_material})
    if not materials:
        return None
    return materials[-1]


def main() -> None:
    inventory = [
        Pen("Heron 200", 3, "piston", "resin", 1.4, False),
        Pen("Sable 51", 2, "aerometric", "brass", 0.9),
        Pen("Kestrel Slim", 9, "cartridge", "aluminium", 1.1, False),
