        Pen("Cracked Classic", 4, "eyedropper", "ebonite", 2.0, True),
        Pen("Dry Wanderer", 1, "cartridge", "steel", 0.1, False),
    ]
    for pen in inventory:
        print(describe(pen))
    print("all good:", grade(inventory))
    print("medium only:", grade(inventory, "medium"))
    print("no nib, no ink:", grade([Pen("Mystery Blank")]))
    print("barrel pick:", heaviest_barrel(inventory))


if __name__ == "__main__":
    main()

