from dataclasses import dataclass

HEAVY_FORCE_LIMIT = 75.0
SOUND_PROFILES = {"linear": 2, "tactile": 4, "clicky": 7, "silent": 1}


@dataclass
class KeyboardBuild:
    layout: str
    switch_type: str | None = None
    keycap_profile: str | None = None
    plate_material: str | None = None
    actuation_force: float | None = None
    foam_dampened: bool | None = None


def typing_feel(
    force: float | None,
) -> str | None:
    if force is None or force > HEAVY_FORCE_LIMIT:
        return None
    if force < 45.0:
        return "feather"
    if force < 60.0:
        return "balanced"
    return "firm"


def sound_profile(
    switch: str | None,
) -> int | None:
    if switch is None:
        return None
    return SOUND_PROFILES.get(switch.strip().lower())


def _optional_text(raw: str) -> str | None:
    text = raw.strip()
    return text or None


def _optional_force(raw: str) -> float | None:
    text = _optional_text(raw)
    if text is None:
        return None
    return float(text)


def _optional_flag(raw: str) -> bool | None:
    text = _optional_text(raw)
    if text is None:
        return None
    return text.lower() in {"yes", "true", "1"}


def parse_build(row: str) -> KeyboardBuild:
    cells = row.split(",")
    if len(cells) != 6:
        raise ValueError(f"expected 6 fields, got {len(cells)}: {row!r}")
    layout = _optional_text(cells[0])
    if layout is None:
        raise ValueError(f"layout name is required: {row!r}")
    return KeyboardBuild(
        layout=layout,
        switch_type=_optional_text(cells[1]),
        keycap_profile=_optional_text(cells[2]),
        plate_material=_optional_text(cells[3]),
        actuation_force=_optional_force(cells[4]),
        foam_dampened=_optional_flag(cells[5]),
    )


def describe(build: KeyboardBuild) -> str:
    feel: str | None = typing_feel(build.actuation_force)
    profile: int | None = sound_profile(build.switch_type)
    plate = build.plate_material or "unspecified plate"
    return (
        f"{build.layout}: feel={feel or 'none'}, sound={profile if profile is not None else 'none'}, "
        f"{plate}, foam={'yes' if build.foam_dampened else 'no'}"
    )


def evaluate(builds: list[KeyboardBuild], preferred_feel: str | None = None) -> int:
    premium = 0
    for build in builds:
        feel = typing_feel(build.actuation_force)
        if feel is None or (preferred_feel is not None and feel != preferred_feel):
            continue
        if sound_profile(build.switch_type) is None:
            continue
        if build.foam_dampened:
            premium += 1
    return premium


def main() -> None:
    rows = [
        "65% Aluminium,tactile,cherry,brass,58,yes",
        "TKL Acrylic,clicky,OEM,,67,yes",
        "Split Ergo,,MT3,FR4,,no",
        "75% Wooden,silent,MT3,polycarbonate,42,yes",
        "1800 Compact,unobtainium,cherry,aluminium,55,yes",
    ]
    builds = [parse_build(row) for row in rows]
    for build in builds:
        print(describe(build))
    print("premium builds:", evaluate(builds))
    print("premium 'firm' builds:", evaluate(builds, "firm"))


if __name__ == "__main__":
    main()

