from dataclasses import dataclass


@dataclass
class Vessel:
    name: str
    mast_height: float | None = None
    sail_area: float | None = None
    hull_wood: str | None = None
    cannon_count: int | None = None
    barnacle_encrusted: bool | None = None


def wind_class(
    mast_height: float | None,
) -> str | None:
    if mast_height is None or mast_height < 8.0:
        return None
    if mast_height < 16.0:
        return "breeze"
    if mast_height < 28.0:
        return "gale"
    return "storm"


def firepower(
    cannon_count: int | None,
) -> float | None:
    if cannon_count is None or cannon_count == 0:
        return None
    return round(cannon_count * 1.75, 2)


def sail_efficiency(
    sail_area: float | None,
    mast_height: float | None,
) -> float | None:
    if sail_area is None or mast_height is None:
        return None
    if mast_height <= 0:
        return None
    return round(sail_area / mast_height, 2)


def matches_hull(vessel: Vessel, hull_type: str | None) -> bool:
    if hull_type is None:
        return True
    if vessel.hull_wood is None:
        return False
    return vessel.hull_wood.casefold() == hull_type.casefold()


def is_formidable(vessel: Vessel) -> bool:
    if wind_class(vessel.mast_height) is None:
        return False
    if firepower(vessel.cannon_count) is None:
        return False
    return not vessel.barnacle_encrusted


def review(
    ships: list[Vessel],
    hull_type: str | None = None,
) -> list[str]:
    return [
        ship.name
        for ship in ships
        if matches_hull(ship, hull_type) and is_formidable(ship)
    ]


def describe(vessel: Vessel) -> str:
    wind = wind_class(vessel.mast_height) or "becalmed"
    power = firepower(vessel.cannon_count)
    guns = "unarmed" if power is None else f"{power} firepower"
    drag = sail_efficiency(vessel.sail_area, vessel.mast_height)
    rig = "unrigged" if drag is None else f"{drag} m of sail per metre of mast"
    return f"{vessel.name}: {wind}, {guns}, {rig}"


def main() -> None:
    fleet = [
        Vessel("Windrunner", 22.5, 410.0, "oak", 34, False),
        Vessel("Kraken's Bane", 30.0, 520.0, "teak", 48, True),
        Vessel("Little Otter", 6.0, 40.0, "pine", 2, False),
        Vessel("Ghost Barque", hull_wood="oak"),
        Vessel("Silent Trader", 17.0, 300.0, "oak", 0, False),
    ]
    for vessel in fleet:
        print(describe(vessel))
    print("Formidable:", review(fleet))
    print("Formidable oak:", review(fleet, "oak"))


if __name__ == "__main__":
    main()

