from dataclasses import dataclass


@dataclass
class FermentationLog:
    batch: str
    tea: str | None = None
    sugar: float | None = None
    ambient: float | None = None
    days: int | None = None
    mold: bool | None = None


def sweetness_profile(
    sugar: float | None,
) -> str | None:
    """Sweetness wording for a sugar concentration in g/100 ml, if usable."""
    if sugar is None or sugar < 2.0 or sugar > 12.0:
        return None
    if sugar < 5.0:
        return "dry"
    if sugar < 9.0:
        return "balanced"
    return "sweet"


def tartness_score(
    days: int | None,
) -> float | None:
    """Acidity estimate for a fermentation length, unusable past 30 days."""
    if days is None or days < 0 or days > 30:
        return None
    return round(days * 0.31, 2)


def _as_float(value: object) -> float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    return float(value)


def _as_int(value: object) -> int | None:
    if isinstance(value, bool) or not isinstance(value, int):
        return None
    return value


def _as_text(value: object) -> str | None:
    if isinstance(value, str) and value.strip():
        return value.strip()
    return None


def parse_log(record: dict) -> FermentationLog:
    mold = record.get("mold") if isinstance(record.get("mold"), bool) else None
    return FermentationLog(
        batch=str(record["batch"]),
        tea=_as_text(record.get("tea")),
        sugar=_as_float(record.get("sugar")),
        ambient=_as_float(record.get("ambient")),
        days=_as_int(record.get("days")),
        mold=mold,
    )


def effective_temperature(
    log: FermentationLog,
    fallback: float | None,
) -> float | None:
    return log.ambient if log.ambient is not None else fallback


def describe(log: FermentationLog, fallback: float | None = None) -> str:
    score = tartness_score(log.days)
    temperature = effective_temperature(log, fallback)
    parts = [
        f"{log.batch} ({log.tea or 'unknown tea'})",
        f"sweetness={sweetness_profile(log.sugar) or 'n/a'}",
        f"tartness={score if score is not None else 'n/a'}",
        f"temp={temperature if temperature is not None else 'n/a'}",
        f"mold={'yes' if log.mold else 'no' if log.mold is not None else 'n/a'}",
    ]
    return " | ".join(parts)


def track(logs: list[FermentationLog]) -> int:
    """Count batches with a sweetness profile, a tartness score and no mold."""
    successes = 0
    for log in logs:
        if sweetness_profile(log.sugar) is None or tartness_score(log.days) is None:
            continue
        if log.mold:
            continue
        successes += 1
    return successes


def main() -> None:
    records = [
        {"batch": "B-01", "tea": "green", "sugar": 7.5, "days": 12, "mold": False, "ambient": 24.0},
        {"batch": "B-02", "tea": "black", "sugar": 6.0, "days": 9, "mold": False},
        {"batch": "B-03", "tea": "oolong", "mold": False},
        {"batch": "B-04", "sugar": 8.0, "days": 40, "mold": True, "ambient": 21.5},
    ]
    logs = [parse_log(record) for record in records]
    for log in logs:
        print(describe(log, 22.0))
    print(f"successful batches: {track(logs)}")


if __name__ == "__main__":
    main()

