from dataclasses import dataclass

MONTH_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
REGION_MULTIPLIERS = {"kyoto": 1.35, "suzhou": 1.2, "bursa": 1.1, "assam": 0.95}
BASE_PRICES = {"A": 18.0, "B": 14.0, "C": 10.0}
DIET_FACTORS = {"mulberry": 1.1, "oak": 1.0, "castor": 0.9}


@dataclass
class SilkBatch:
    batch_id: str
    cocoon_weight: float | None = None
    thread_length: float | None = None
    diet: str | None = None
    region: str | None = None
    harvest_month: int | None = None


def _parse_month(value: object) -> int | None:
    if isinstance(value, int):
        return value if 1 <= value <= 12 else None
    if isinstance(value, str):
        name = value.strip().lower()
        if name in MONTH_NAMES:
            return MONTH_NAMES.index(name) + 1
    return None


def build_batch(record: tuple) -> SilkBatch:
    fields = list(record) + [None] * (6 - len(record))
    batch_id, weight, length, diet, region, month = fields[:6]
    return SilkBatch(str(batch_id), weight, length, diet, region, _parse_month(month))


def thread_yield(batch: SilkBatch) -> float | None:
    if batch.cocoon_weight is None or batch.thread_length is None:
        return None
    if batch.cocoon_weight <= 0:
        return None
    return batch.thread_length / batch.cocoon_weight


def silk_grade(batch: SilkBatch) -> str | None:
    ratio = thread_yield(batch)
    if ratio is None:
        return None
    if ratio >= 250:
        return "A"
    if ratio >= 150:
        return "B"
    return "C"


def adjusted_price(standard_price: float, region: str | None) -> float:
    if region is None:
        return round(standard_price, 2)
    return round(standard_price * REGION_MULTIPLIERS.get(region.strip().lower(), 1.0), 2)


def _diet_factor(diet: str | None) -> float:
    if diet is None:
        return 1.0
    return DIET_FACTORS.get(diet.strip().lower(), 1.0)


def _month_bonus(month: int | None) -> float:
    if month is None:
        return 0.0
    return 0.5 if month in (4, 5, 6) else -0.25


def quality_score(batch: SilkBatch) -> float | None:
    ratio = thread_yield(batch)
    if ratio is None:
        return None
    base = min(ratio / 30.0, 9.0)
    return round(base * _diet_factor(batch.diet) + _month_bonus(batch.harvest_month), 2)


def _format_score(score: float | None) -> str:
    return "unrated" if score is None else f"{score:.2f}"


def grade(batches) -> list[str]:
    summaries = []
    for record in batches:
        batch = build_batch(record)
        label = silk_grade(batch)
        price = adjusted_price(BASE_PRICES.get(label, 8.0), batch.region)
        summaries.append(
            f"Batch {batch.batch_id}: grade {label or 'ungraded'}, "
            f"price {price:.2f}, quality {_format_score(quality_score(batch))}"
        )
    return summaries


def main() -> None:
    for line in grade([("Alpha", 5, 1000, None, "Kyoto", None)]):
        print(line)


if __name__ == "__main__":
    main()

