CURRENT_YEAR = 2024

MATERIAL_FEE_FACTORS = {"gut": 1.15, "steel": 0.95, "nylon": 1.0}
CRANK_WOOD_DAMPING = {"maple": 0.9, "walnut": 0.8, "pine": 1.1}
TONE_BY_MATERIAL = {"gut": "warm", "steel": "bright", "nylon": "mellow"}


class HurdyGurdy:
    def __init__(
        self,
        owner: str,
        wheel_diameter: float | None = None,
        rosin_buildup: int | None = None,
        string_material: str | None = None,
        crank_wood: str | None = None,
        last_service_year: int | None = None,
    ) -> None:
        self.owner = owner
        self.wheel_diameter = wheel_diameter
        self.rosin_buildup = rosin_buildup
        self.string_material = string_material
        self.crank_wood = crank_wood
        self.last_service_year = last_service_year

    @classmethod
    def from_tuple(cls, record: tuple) -> "HurdyGurdy":
        values = list(record) + [None] * (6 - len(record))
        if not isinstance(values[0], str) or not values[0].strip():
            raise ValueError("every instrument record needs an owner name")
        return cls(*values[:6])


def rotational_friction(instrument: HurdyGurdy) -> float | None:
    if instrument.wheel_diameter is None:
        return None
    buildup: int | None = instrument.rosin_buildup
    drag = 1.0 if buildup is None else 1.0 + buildup / 10
    return round(instrument.wheel_diameter * 0.6 * drag, 2)


def sound_profile(instrument: HurdyGurdy) -> str | None:
    material: str | None = instrument.string_material
    if material is None:
        return None
    tone = TONE_BY_MATERIAL.get(material.lower(), "neutral")
    if instrument.crank_wood is None:
        return tone
    return f"{tone} with {instrument.crank_wood} crank"


def adjusted_fee(
    baseline: float,
    string_material: str | None,
) -> float:
    if string_material is None:
        return round(baseline * 1.1, 2)
    return round(baseline * MATERIAL_FEE_FACTORS.get(string_material.lower(), 1.05), 2)


def tuning_stability(instrument: HurdyGurdy) -> float | None:
    if instrument.last_service_year is None:
        return None
    age = max(CURRENT_YEAR - instrument.last_service_year, 0)
    score = 10.0 - age * 0.8
    wood: str | None = instrument.crank_wood
    if wood is not None:
        score *= CRANK_WOOD_DAMPING.get(wood.lower(), 1.0)
    return round(max(score, 0.0), 2)


def describe_friction(friction: float | None) -> str:
    if friction is None:
        return "friction unknown (wheel diameter missing)"
    return f"friction {friction}"


def inspect(instruments: list[tuple]) -> list[str]:
    actions = []
    for record in instruments:
        instrument = HurdyGurdy.from_tuple(record)
        friction: float | None = rotational_friction(instrument)
        fee = adjusted_fee(40.0, instrument.string_material)
        parts = [f"{instrument.owner}: {describe_friction(friction)}"]
        parts.append(f"maintenance fee {fee:.2f}")
        profile: str | None = sound_profile(instrument)
        if profile is not None:
            parts.append(f"sound {profile}")
        stability = tuning_stability(instrument)
        if stability is not None:
            parts.append(f"tuning stability {stability}")
        actions.append(", ".join(parts))
    return actions


if __name__ == "__main__":
    for action in inspect([("Bard", 15, None, "gut", None, None)]):
        print(action)

