from __future__ import annotations


class Chandelier:
    """A grand chandelier; every detail after the hall location may be missing."""

    def __init__(
        self,
        hall: str,
        crystal_count: int | None = None,
        tier_height: float | None = None,
        glass_type: str | None = None,
        frame_metal: str | None = None,
        install_century: int | None = None,
    ) -> None:
        if not hall:
            raise ValueError("a chandelier must be tied to a hall location")
        self.hall = hall
        self.crystal_count = crystal_count
        self.tier_height = tier_height
        self.glass_type = glass_type
        self.frame_metal = frame_metal
        self.install_century = install_century


def estimate_polish_time(chandelier: Chandelier) -> float | None:
    """Hours of hand polishing, or nothing when the crystal count is unknown."""
    if chandelier.crystal_count is None:
        return None
    hours = chandelier.crystal_count * 0.04
    height: float | None = chandelier.tier_height
    if height is not None:
        hours += height * 0.75
    return round(hours, 2)


def classify_refractive_index(chandelier: Chandelier) -> str | None:
    """Refractive category of the glass, or nothing when the glass is unknown."""
    glass = chandelier.glass_type
    if glass is None:
        return None
    table = {"lead": "high", "crystal": "very high", "soda-lime": "standard"}
    return table.get(glass.lower(), "uncatalogued")


def final_labor_cost(base_cost: float, frame_metal: str | None) -> float:
    """Apply the metal-specific handling surcharge to a base labor cost."""
    surcharges = {"bronze": 1.10, "brass": 1.05, "wrought iron": 1.20, "silver": 1.35}
    if frame_metal is None:
        return round(base_cost * 1.25, 2)
    return round(base_cost * surcharges.get(frame_metal.lower(), 1.15), 2)


def fragility_index(chandelier: Chandelier) -> float | None:
    """Fragility score, or nothing when the installation century is unknown."""
    century: int | None = chandelier.install_century
    if century is None:
        return None
    age_factor = max(1, 21 - century) * 0.5
    crystals = chandelier.crystal_count if chandelier.crystal_count is not None else 100
    return round(age_factor * (crystals / 100.0), 2)


def describe_measure(value: float | None, unit: str) -> str:
    return f"{value} {unit}" if value is not None else "unknown"


def schedule(chandeliers: list[tuple]) -> list[str]:
    instructions: list[str] = []
    for row in chandeliers:
        piece = Chandelier(*row)
        polish = estimate_polish_time(piece)
        fragility = fragility_index(piece)
        category: str | None = classify_refractive_index(piece)
        base = (polish if polish is not None else 3.0) * 48.0
        cost = final_labor_cost(base, piece.frame_metal)
        instructions.append(
            f"{piece.hall}: polish {describe_measure(polish, 'h')}, "
            f"fragility {describe_measure(fragility, 'idx')}, "
            f"refraction {category or 'unclassified'}, labor ${cost}"
        )
    return instructions


def main() -> None:
    rows = [("Ballroom", 500, None, "lead", None, 18)]
    for line in schedule(rows):
        print(line)


if __name__ == "__main__":
    main()

