import math
from dataclasses import dataclass


@dataclass
class Sousaphone:
    tag: str
    bell_diameter: float | None
    tubing_length: float | None
    alloy: str | None = None
    valve_count: int | None = None
    purchase_year: int | None = None


def acoustic_resonance(horn: Sousaphone) -> float | None:
    if horn.bell_diameter is None or horn.tubing_length is None:
        return None
    return round(343.0 / (2.0 * horn.tubing_length / 100.0) * math.sqrt(horn.bell_diameter / 26.0), 2)


def visual_condition(horn: Sousaphone) -> str | None:
    if horn.purchase_year is None:
        return None
    age = 2024 - horn.purchase_year
    if age < 5:
        return "parade ready"
    if age < 15:
        return "scuffed"
    if age < 40:
        return "heavily tarnished"
    return "museum piece"


def dent_time(base_hours: float, alloy: str | None) -> float:
    factors = {
        "yellow brass": 1.0,
        "rose brass": 1.2,
        "nickel silver": 1.45,
        "sterling silver": 1.6,
    }
    if alloy is None:
        return round(base_hours * 1.3, 2)
    return round(base_hours * factors.get(alloy.lower(), 1.15), 2)


def salvageability(horn: Sousaphone) -> float | None:
    resonance = acoustic_resonance(horn)
    condition = visual_condition(horn)
    if resonance is None and condition is None:
        return None
    score = 50.0
    if resonance is not None:
        score += min(25.0, resonance / 8.0)
    if condition is not None:
        penalties = {"parade ready": 0.0, "scuffed": 8.0, "heavily tarnished": 20.0, "museum piece": 35.0}
        score -= penalties[condition]
    if horn.valve_count is not None:
        score += (horn.valve_count - 3) * 4.0
    return round(max(0.0, min(100.0, score)), 2)


def estimate(horns):
    orders = []
    for record in horns:
        padded = tuple(record) + (None,) * (6 - len(record))
        horn = Sousaphone(*padded[:6])
        base = 4.0 if horn.bell_diameter is None else 2.0 + horn.bell_diameter / 10.0
        hours = dent_time(base, horn.alloy)
        if horn.valve_count is not None:
            hours += horn.valve_count * 0.75
        score: float | None = salvageability(horn)
        score_text = "unknown" if score is None else f"{score:.2f}"
        condition = visual_condition(horn)
        state = condition if condition is not None else "condition unrecorded"
        orders.append(f"{horn.tag}: {state}, repair time {hours:.2f}h, salvageability {score_text}")
    return orders


def main() -> None:
    inventory = [
        ("Marching Pride", 26.0, None, "yellow brass", None, 1990),
        ("Thunder Row", 24.0, 520.0, "nickel silver", 4, 2021),
        ("Old Faithful",),
    ]
    for line in estimate(inventory):
        print(line)


if __name__ == "__main__":
    main()

