from __future__ import annotations

from dataclasses import dataclass
from datetime import date

PRESSURE_DEPTH = {"low": 0.35, "medium": 0.60, "high": 0.90}
FEED_PENALTY = {"hand feed": 12, "friction feed": 6, "vacuum feed": 3}
SOLVENT_WEAR = {"kerosene": 0.05, "citrus": 0.12, "mineral spirits": 0.02}


@dataclass
class LetterPress:
    model: str
    platen_pressure: str | None = None
    roller_diameter: float | None = None
    ink_solvent: str | None = None
    paper_feed: str | None = None
    restoration_date: str | None = None


def impression_depth(press: LetterPress) -> float | None:
    """Impression depth in millimetres, or nothing if the pressure is unknown."""
    base = PRESSURE_DEPTH.get((press.platen_pressure or "").lower())
    if base is None:
        return None
    diameter: float | None = press.roller_diameter
    if diameter is not None:
        base *= 1.0 + (diameter - 50.0) / 200.0
    return round(base, 3)


def recommended_stock(press: LetterPress) -> str | None:
    depth = impression_depth(press)
    if depth is None:
        return None
    if depth >= 0.85:
        return "300gsm cotton rag"
    if depth >= 0.55:
        return "220gsm laid book"
    return "120gsm smooth text"


def finalize_setup_time(standard_minutes: int, paper_feed: str | None = None) -> int:
    return standard_minutes + FEED_PENALTY.get((paper_feed or "").lower(), 15)


def _years_since(
    restoration_date: str | None,
) -> int | None:
    if restoration_date is None:
        return None
    try:
        restored = date.fromisoformat(restoration_date)
    except ValueError:
        return None
    return max(0, (date.today() - restored).days // 365)


def reliability_rating(press: LetterPress) -> float | None:
    age = _years_since(press.restoration_date)
    if age is None:
        return None
    rating = 1.0 - min(age, 40) * 0.015
    rating -= SOLVENT_WEAR.get((press.ink_solvent or "").lower(), 0.08)
    return round(max(0.0, rating), 3)


def build_guide(press: LetterPress, standard_minutes: int = 30) -> str:
    minutes = finalize_setup_time(standard_minutes, press.paper_feed)
    stock: str | None = recommended_stock(press)
    rating = reliability_rating(press)
    parts = [f"{press.model}: allow {minutes} min setup"]
    parts.append(f"stock {stock}" if stock else "stock undetermined (pressure unknown)")
    parts.append(
        f"reliability {rating:.2f}" if rating is not None else "reliability unverified"
    )
    return "; ".join(parts) + "."


def configure(presses: list[tuple]) -> list[str]:
    return [build_guide(LetterPress(*entry)) for entry in presses]

