import math

STONE_MARGIN_FACTORS = {"slate": 1.0, "granite": 0.8, "limestone": 1.3, "sandstone": 1.6}
MAKER_ERAS = {"thornby": "Georgian", "caldwell": "Victorian", "perrin": "Baroque"}
STYLE_ERAS = {"roman": "Renaissance", "arabic": "Modern", "gothic": "Medieval"}
STYLE_READABILITY = {"roman": 1.0, "arabic": 1.5, "gothic": 0.5}


class Sundial:
    def __init__(
        self,
        location: str,
        latitude: float | None = None,
        gnomon_height: float | None = None,
        base_stone: str | None = None,
        numeral_style: str | None = None,
        maker: str | None = None,
    ) -> None:
        self.location = location
        self.latitude = latitude
        self.gnomon_height = gnomon_height
        self.base_stone = base_stone
        self.numeral_style = numeral_style
        self.maker = maker


def noon_shadow_length(dial: Sundial) -> float | None:
    if dial.latitude is None or dial.gnomon_height is None:
        return None
    if abs(dial.latitude) >= 90.0:
        return None
    return dial.gnomon_height * math.tan(math.radians(abs(dial.latitude)))


def replica_era(dial: Sundial) -> str | None:
    if dial.maker is not None:
        era: str | None = MAKER_ERAS.get(dial.maker.strip().lower())
        if era is not None:
            return era
    if dial.numeral_style is None:
        return None
    return STYLE_ERAS.get(dial.numeral_style.strip().lower())


def adjust_margin(base_margin: float, stone_type: str | None) -> float:
    if stone_type is None:
        return round(base_margin * 1.5, 3)
    factor = STONE_MARGIN_FACTORS.get(stone_type.strip().lower(), 1.2)
    return round(base_margin * factor, 3)


def readability_rating(dial: Sundial) -> float | None:
    shadow: float | None = noon_shadow_length(dial)
    if shadow is None:
        return None
    score = min(8.0, shadow / 2.0)
    if dial.numeral_style is not None:
        score += STYLE_READABILITY.get(dial.numeral_style.strip().lower(), 0.25)
    return round(min(score, 10.0), 2)


def calibrate(dials: list[tuple]) -> list[str]:
    instructions = []
    for row in dials:
        dial = Sundial(*row)
        shadow: float | None = noon_shadow_length(dial)
        margin = adjust_margin(0.5, dial.base_stone)
        era: str | None = replica_era(dial)
        rating: float | None = readability_rating(dial)
        parts = [f"Place {dial.location} gnomon"]
        if shadow is None:
            parts.append("noon shadow length unknown")
        else:
            parts.append(f"noon shadow {shadow:.2f} cm")
        parts.append(f"error margin {margin:.2f} cm")
        if era is not None:
            parts.append(f"replica era {era}")
        if rating is not None:
            parts.append(f"readability {rating}/10")
        instructions.append("; ".join(parts) + ".")
    return instructions


def main() -> None:
    garden = [("Rose Garden", 45.0, None, "slate", None, None)]
    for line in calibrate(garden):
        print(line)


if __name__ == "__main__":
    main()

