from __future__ import annotations

STANDARD_MIXING_TIME = 12.0
MIX_FACTORS = {"copal": 1.25, "shellac": 1.10, "gum arabic": 0.90}
RESIN_ARCHIVAL_BONUS = {"copal": 2.0, "shellac": 1.0, "gum arabic": 0.5}
PRESS_TEMPERATURES = {"fast": "18 C", "medium": "21 C", "slow": "24 C"}


class InkBatch:
    def __init__(
        self,
        pigment: str,
        viscosity: float | None = None,
        drying_speed: str | None = None,
        resin: str | None = None,
        acid_resistance: int | None = None,
        grinding_time: float | None = None,
    ) -> None:
        self.pigment = pigment
        self.viscosity = viscosity
        self.drying_speed = drying_speed
        self.resin = resin
        self.acid_resistance = acid_resistance
        self.grinding_time = grinding_time


def normalize_resin(
    resin: str | None,
) -> str | None:
    if resin is None:
        return None
    return resin.strip().lower()


def saturation_index(ink: InkBatch) -> float | None:
    if ink.viscosity is None or ink.grinding_time is None:
        return None
    return round(10.0 * ink.grinding_time / (ink.viscosity + 1.0), 2)


def press_temperature(ink: InkBatch) -> str | None:
    speed: str | None = ink.drying_speed
    if speed is None:
        return None
    return PRESS_TEMPERATURES.get(speed.strip().lower())


def mixing_duration(standard_time: float, resin: str | None) -> float:
    key = normalize_resin(resin)
    factor = MIX_FACTORS.get(key, 1.0) if key is not None else 1.0
    return round(standard_time * factor, 1)


def archival_rating(ink: InkBatch) -> float | None:
    key = normalize_resin(ink.resin)
    if ink.acid_resistance is None and key is None:
        return None
    rating = 5.0
    if ink.acid_resistance is not None:
        rating += 1.5 * ink.acid_resistance
    if key is not None:
        rating += RESIN_ARCHIVAL_BONUS.get(key, 0.0)
    saturation: float | None = saturation_index(ink)
    if saturation is not None:
        rating += saturation / 10.0
    return round(min(rating, 10.0), 2)


def describe(value: float | None, suffix: str) -> str:
    if value is None:
        return "not determinable"
    return f"{value:g}{suffix}"


def formulate(inks: list[tuple]) -> list[str]:
    recipes: list[str] = []
    for record in inks:
        ink = InkBatch(*record)
        duration = mixing_duration(STANDARD_MIXING_TIME, ink.resin)
        temperature: str | None = press_temperature(ink)
        recipes.append(
            f"{ink.pigment}: mix {duration:g} min, "
            f"archival {describe(archival_rating(ink), '/10')}, "
            f"saturation {describe(saturation_index(ink), '')}, "
            f"press room {temperature or 'operator choice'}"
        )
    return recipes


def main() -> None:
    for recipe in formulate([("Prussian Blue", None, "fast", "copal", None, None)]):
