SPEED_OF_SOUND_CM_S = 34300.0

WOOD_DENSITY = {
    "eucalyptus": 0.90,
    "stringybark": 0.85,
    "woollybutt": 0.78,
    "bloodwood": 1.05,
    "bamboo": 0.55,
}

BEESWAX_SEAL_QUALITY = {"native": 1.05, "sugarbag": 1.10, "commercial": 0.95}


class Didgeridoo:
    def __init__(
        self,
        region: str,
        length_cm: float | None = None,
        bell_width_cm: float | None = None,
        species: str | None = None,
        beeswax: str | None = None,
        curing_months: int | None = None,
    ):
        self.region = region
        self.length_cm = length_cm
        self.bell_width_cm = bell_width_cm
        self.species = species
        self.beeswax = beeswax
        self.curing_months = curing_months


def parse_instrument(row: tuple) -> Didgeridoo:
    region = row[0]
    padded = tuple(row[1:]) + (None,) * (6 - len(row))
    return Didgeridoo(region, *padded)


def drone_frequency(instrument: Didgeridoo) -> float | None:
    if instrument.length_cm is None or instrument.length_cm <= 0:
        return None
    effective_length = instrument.length_cm
    if instrument.bell_width_cm is not None:
        effective_length += 0.6 * instrument.bell_width_cm
    return SPEED_OF_SOUND_CM_S / (2.0 * effective_length)


def overtone_richness(instrument: Didgeridoo) -> str | None:
    if instrument.length_cm is None or instrument.bell_width_cm is None:
        return None
    flare = instrument.bell_width_cm / instrument.length_cm
    if flare >= 0.18:
        return "brassy"
    if flare >= 0.10:
        return "balanced"
    return "reedy"


def base_market_value(instrument: Didgeridoo) -> float | None:
    if instrument.length_cm is None:
        return None
    return 90.0 + 1.8 * instrument.length_cm


def adjust_value(base_value: float, species: str | None) -> float:
    density = WOOD_DENSITY.get(species.lower()) if species else None
    if density is None:
        return round(base_value * 0.85, 2)
    return round(base_value * (0.7 + density / 2.0), 2)


def durability_score(instrument: Didgeridoo) -> float | None:
    density = WOOD_DENSITY.get(instrument.species.lower()) if instrument.species else None
    if density is None or instrument.curing_months is None:
        return None
    seasoning = min(instrument.curing_months, 36) / 36.0
    seal = BEESWAX_SEAL_QUALITY.get((instrument.beeswax or "").lower(), 1.0)
    return round(density * 60.0 * (1.0 + seasoning) * seal, 2)


def format_measure(value: float | None, unit: str) -> str:
    if value is None:
        return "unknown"
    return f"{value:.2f} {unit}"


def analyze(instruments: list) -> list:
    profiles = []
    for row in instruments:
        inst = parse_instrument(row)
        base = base_market_value(inst)
        value = adjust_value(base, inst.species) if base is not None else None
        profiles.append(
            f"{inst.region}: drone {format_measure(drone_frequency(inst), 'Hz')}, "
            f"overtones {overtone_richness(inst) or 'unknown'}, "
            f"durability {format_measure(durability_score(inst), 'pts')}, "
            f"value {format_measure(value, 'AUD')}"
        )
    return profiles


def main() -> None:
    sample = [
        ("Arnhem Land", 100.0, None, "eucalyptus", None, None),
        ("Kakadu", 145.0, 18.0, "bloodwood", "sugarbag", 24),
    ]
    for profile in analyze(sample):
        print(profile)


if __name__ == "__main__":
    main()

