from __future__ import annotations


class Seal:
    """A historical letter seal; every attribute but the crest may be unknown."""

    def __init__(
        self,
        crest: str,
        melting_point: float | None,
        dye_intensity: str | None,
        ribbon: str | None,
        stamp_metal: str | None = None,
        year: int | None = None,
    ) -> None:
        self.crest = crest
        self.melting_point = melting_point
        self.dye_intensity = dye_intensity
        self.ribbon = ribbon
        self.stamp_metal = stamp_metal
        self.year = year


def brittleness_factor(seal: Seal) -> float | None:
    """Brittleness grows with age and falls with a higher wax melting point."""
    if seal.melting_point is None or seal.year is None:
        return None
    age = 2025 - seal.year
    return round(age / (seal.melting_point + 10.0), 3)


def royal_house(seal: Seal) -> str | None:
    houses = {
        "Lion Rampant": "House of Plantagenet",
        "Double Eagle": "House of Habsburg",
        "Fleur de Lys": "House of Bourbon",
        "White Rose": "House of York",
    }
    return houses.get(seal.crest)


def adjust_forgery(base: float, ribbon: str | None) -> float:
    """Silk was reserved for court use; unknown ribbons stay slightly suspect."""
    modifiers = {"silk": -0.15, "linen": 0.05, "hemp": 0.20, "velvet": -0.05}
    if ribbon is None:
        adjusted = base + 0.10
    else:
        adjusted = base + modifiers.get(ribbon.lower(), 0.15)
    return round(min(max(adjusted, 0.0), 1.0), 3)


def authenticity_confidence(seal: Seal) -> float | None:
    intensity_scores = {"high": 0.9, "medium": 0.6, "low": 0.3}
    score: float | None = intensity_scores.get((seal.dye_intensity or "").lower())
    if score is None:
        return None
    if royal_house(seal) is not None:
        score += 0.05
    if seal.stamp_metal is not None:
        score += 0.05
    return round(min(score, 1.0), 3)


def _describe(value: float | None) -> str:
    return "unknown" if value is None else f"{value:.3f}"


def verify(seals: list[tuple]) -> list[str]:
    certificates: list[str] = []
    for record in seals:
        seal = Seal(*record)
        brittleness = brittleness_factor(seal)
        probability = adjust_forgery(0.40, seal.ribbon)
        confidence = authenticity_confidence(seal)
        house: str | None = royal_house(seal)
        certificates.append(
            f"{seal.crest} ({house or 'unattributed house'}): "
            f"brittleness={_describe(brittleness)}, "
            f"forgery_probability={probability:.3f}, "
            f"confidence={_describe(confidence)}"
        )
    return certificates


def main() -> None:
    records = [("Lion Rampant", None, "high", "silk", None, 1650)]
    for certificate in verify(records):
        print(certificate)


if __name__ == "__main__":
    main()

