    if royal_house(seal) is not None:
        score += 0.05
    if seal.stamp_metal is not None:
        score += 0.05
    return round(min(score, 1.0), 3)


def _describe(value: Optional[float]) -> str:
    return "unknown" if value is None else f"{value:.3f}"


def verify(seals: list[tuple]) -> list[str]:
    certificates: list[str] = []
    for record in seals:
