import math

class Metronome:
    def __init__(
        self,
        casing: str,
        pendulum_length: float | None = None,
        weight_mass: float | None = None,
        escapement_metal: str | None = None,
        winding_key: str | None = None,
        production_era: str | None = None,
    ):
        self.casing = casing
        self.pendulum_length = pendulum_length
        self.weight_mass = weight_mass
        self.escapement_metal = escapement_metal
        self.winding_key = winding_key
        self.production_era = production_era


def estimate_bpm(metronome: Metronome) -> float | None:
    length = metronome.pendulum_length
    if length is None or length <= 0:
        return None
    bpm = 60.0 / (2.0 * math.pi * math.sqrt(length / 980.0))
    if metronome.weight_mass is not None:
        bpm *= 1.0 - min(metronome.weight_mass, 50.0) / 400.0
    return round(bpm, 2)


def classify_resonance(metronome: Metronome) -> str | None:
    metal = metronome.escapement_metal
    if metal is None:
        return None
    metal = metal.strip().lower()
    timbre = {"brass": "warm", "steel": "bright", "bronze": "mellow", "iron": "dull"}
    resonance = timbre.get(metal, "neutral")
    if metronome.casing.strip().lower() == "pyramid":
        resonance += "-sustained"
    return resonance


def adjust_error_margin(base_margin: float, escapement_metal: str | None) -> float:
    factors = {"brass": 1.15, "steel": 0.9, "bronze": 1.05, "iron": 1.3}
    if escapement_metal is None:
        return round(base_margin * 1.5, 3)
    return round(base_margin * factors.get(escapement_metal.strip().lower(), 1.2), 3)


def friction_score(metronome: Metronome) -> float | None:
    if metronome.pendulum_length is None:
        return None
    score = metronome.pendulum_length / 10.0
    if metronome.weight_mass is not None:
        score += metronome.weight_mass / 25.0
    if metronome.winding_key is not None:
        score += 0.8 if metronome.winding_key.strip().lower() == "butterfly" else 0.4
    era: str | None = metronome.production_era
    if era is not None and era.strip().lower() in ("antique", "victorian"):
        score *= 1.25
    return round(score, 3)


def calibrate(metronomes: list[tuple]) -> list[str]:
    reports: list[str] = []
    for entry in metronomes:
        fields = list(entry) + [None] * (6 - len(entry))
        unit = Metronome(*fields[:6])
        bpm = estimate_bpm(unit)
        resonance = classify_resonance(unit)
        margin = adjust_error_margin(0.25, unit.escapement_metal)
        friction = friction_score(unit)
        beat_text = f"{bpm} bpm +/-{margin}" if bpm is not None else "beat range indeterminate"
        friction_text = f"friction {friction}" if friction is not None else "friction unknown"
        tone_text = resonance if resonance is not None else "resonance unclassified"
        reports.append(f"{unit.casing}: {beat_text}, {tone_text}, {friction_text}")
    return reports


def main() -> None:
    samples = [
        ("Pyramid", 15.0, None, "brass", None, None),
        ("Cabinet", 24.5, 12.0, "steel", "butterfly", "Victorian"),
        ("Drum",),
    ]
    for line in calibrate(samples):
        print(line)


if __name__ == "__main__":
    main()

