from math import pi


class Cask:
    """Construction parameters of a single wooden aging cask."""

    def __init__(
        self,
        client: str,
        stave_thickness_cm: float | None,
        hoop_count: int | None,
        oak_origin: str | None,
        char_level: str | None,
        drying_months: int | None,
    ) -> None:
        self.client = client
        self.stave_thickness_cm = stave_thickness_cm
        self.hoop_count = hoop_count
        self.oak_origin = oak_origin
        self.char_level = char_level
        self.drying_months = drying_months


def liquid_capacity(cask: Cask) -> float | None:
    """Usable volume in litres, or nothing when the geometry is unknown."""
    if cask.stave_thickness_cm is None or cask.hoop_count is None:
        return None
    outer_radius = 5.0 + 4.5 * cask.hoop_count
    inner_radius = outer_radius - cask.stave_thickness_cm
    if inner_radius <= 0:
        return None
    height = 95.0
    return round(pi * inner_radius**2 * height * 0.9 / 1000.0, 2)


def flavor_profile(cask: Cask) -> str | None:
    """Descriptive profile built from char level and, if known, oak origin."""
    if cask.char_level is None:
        return None
    char_notes = {"light": "vanilla", "medium": "caramel", "heavy": "smoke"}
    note = char_notes.get(cask.char_level.strip().lower(), "neutral")
    origin: str | None = cask.oak_origin
    if origin is None:
        return note
    return f"{note} with {origin.strip().lower()} structure"


def adjust_assembly_time(base_hours: float, oak_origin: str | None) -> float:
    """Scale the base assembly time according to how hard the oak works."""
    if oak_origin is None:
        return round(base_hours, 2)
    factors = {"french": 1.25, "american": 1.0, "hungarian": 1.15, "slavonian": 1.2}
    key = oak_origin.strip().lower().replace(" oak", "")
    return round(base_hours * factors.get(key, 1.05), 2)


def leakage_risk(cask: Cask) -> float | None:
    """Percentage chance of seepage, or nothing without thickness and drying."""
    if cask.stave_thickness_cm is None or cask.drying_months is None:
        return None
    risk = 22.0 - 4.0 * cask.stave_thickness_cm - 0.8 * cask.drying_months
    hoops: int | None = cask.hoop_count
    if hoops is not None:
        risk -= 0.5 * hoops
    return round(max(0.5, min(risk, 99.0)), 1)


def format_metric(value: float | None, unit: str) -> str:
    if value is None:
        return "n/a"
    return f"{value}{unit}"


def assemble(casks):
    tags = []
    for record in casks:
        cask = Cask(*record)
        capacity = liquid_capacity(cask)
        risk = leakage_risk(cask)
        profile: str | None = flavor_profile(cask)
        base_hours = 6.0 if cask.hoop_count is None else 1.5 * cask.hoop_count
        hours = adjust_assembly_time(base_hours, cask.oak_origin)
        tags.append(
            f"{cask.client} | capacity {format_metric(capacity, ' L')}"
            f" | leakage risk {format_metric(risk, '%')}"
            f" | {profile or 'profile unknown'} | {hours} h"
        )
    return tags


def main() -> None:
    orders = [("Chateau", None, 6, "French oak", "medium", None)]
    for tag in assemble(orders):
        print(tag)


if __name__ == "__main__":
    main()

