from dataclasses import dataclass


@dataclass
class MusicBox:
    melody: str
    width_cm: float | None
    peg_count: int | None
    comb_metal: str | None
    governor: str | None
    patent_year: int | None


def playtime_seconds(box: MusicBox) -> float | None:
    if box.peg_count is None or box.width_cm is None:
        return None
    revolutions = box.peg_count / 24.0
    return round(revolutions * box.width_cm * 1.8, 2)


def harmony_complexity(box: MusicBox) -> str | None:
    duration = playtime_seconds(box)
    if duration is None:
        if box.peg_count is None:
            return None
        return "monophonic" if box.peg_count < 120 else "polyphonic"
    density = box.peg_count / duration
    if density < 0.5:
        return "simple air"
    if density < 1.5:
        return "harmonized air"
    return "orchestral arrangement"


def restoration_fee(base_fee: float, comb_metal: str | None) -> float:
    multipliers = {"steel": 1.0, "brass": 1.25, "silver": 1.6, "gold": 2.1}
    if comb_metal is None:
        return round(base_fee * 1.4, 2)
    return round(base_fee * multipliers.get(comb_metal.lower(), 1.15), 2)


def preservation_score(box: MusicBox) -> float | None:
    known = [f for f in (box.width_cm, box.peg_count, box.comb_metal,
                         box.governor, box.patent_year) if f is not None]
    if len(known) < 2:
        return None
    score = 40.0 + 12.0 * len(known)
    if box.governor is not None and "worm" in box.governor.lower():
        score += 6.0
    age: int | None = None if box.patent_year is None else 2024 - box.patent_year
    if age is not None and age > 120:
        score -= 8.0
    fee = restoration_fee(100.0, box.comb_metal)
    score -= (fee - 100.0) / 10.0
    return round(min(score, 100.0), 1)


def certificate(box: MusicBox) -> str:
    harmony: str | None = harmony_complexity(box)
    score = preservation_score(box)
    harmony_text = harmony if harmony is not None else "indeterminate"
    score_text = "unrated" if score is None else f"{score:.1f}/100"
    return f"{box.melody}: {harmony_text}, preservation {score_text}"


def inspect(boxes: list[tuple]) -> list[str]:
    certificates = []
    for record in boxes:
        melody = record[0]
        specs = list(record[1:]) + [None] * (5 - len(record[1:]))
        box = MusicBox(melody, specs[0], specs[1], specs[2], specs[3], specs[4])
        certificates.append(certificate(box))
    return certificates


def main() -> None:
    catalogue = [
        ("Swan Lake", 10.0, None, "steel", None, 1890),
        ("Fur Elise", 14.5, 240, "brass", "worm gear", 1902),
        ("Greensleeves", None, None, None, None, 1875),
    ]
    for line in inspect(catalogue):
        print(line)


if __name__ == "__main__":
    main()

