import math

def is_prime(n: int) -> bool | None:
    if n is None or not isinstance(n, int):
        return None
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i: int | None = 5
    while i * i <= n:
        if i is None:
            return None # Should not happen with current logic
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

