import math
import sys


def parse_radius(text: str) -> float | None:
    """Convert user input into a radius, or None when it is not usable."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        value = float(stripped)
    except ValueError:
        return None
    if value < 0 or math.isnan(value):
        return None
    return value


def circle_area(radius):
    """Area of a circle of the given radius."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * radius * radius


def area_of(
    radius: float | None,
):
    """Area for an already-parsed radius; None propagates unchanged."""
    if radius is None:
        return None
    return circle_area(radius)


def annulus_area(
    outer: float,
    inner: float | None = None,
) -> float:
    """Area of a ring; with no inner radius this is just the full disc."""
    total = circle_area(outer)
    if inner is None:
        return total
    if inner > outer:
        raise ValueError("inner radius exceeds outer radius")
    return total - circle_area(inner)


def radius_from_area(area: float) -> float:
    """Inverse of circle_area."""
    if area < 0:
        raise ValueError("area must be non-negative")
    return math.sqrt(area / math.pi)


def format_area(area, digits: int | None = None) -> str:
    """Render an area, using "n/a" for a missing value."""
    if area is None:
        return "n/a"
    if digits is None:
        return repr(area)
    return f"{area:.{digits}f}"


def largest_radius(texts: list[str]) -> float | None:
    """Biggest usable radius among the inputs, or None if there is none."""
    best = None
    for text in texts:
        radius = parse_radius(text)
        if radius is not None and (best is None or radius > best):
            best = radius
    return best


def report(texts: list[str], digits: int | None = None) -> str:
    lines = []
    for text in texts:
        radius = parse_radius(text)
        label = text.strip() or "<empty>"
        lines.append(f"{label:>10} -> {format_area(area_of(radius), digits)}")
    widest = largest_radius(texts)
    if widest is None:
        lines.append("no valid radii supplied")
