from typing import Iterable


def is_leap(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year: int, month: int) -> int | None:
    lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month < 1 or month > 12:
        return None
    if month == 2 and is_leap(year):
        return 29
    return lengths[month - 1]


def validate_date(year: int, month: int, day: int) -> str | None:
    if year < 1:
        return f"year {year} is out of range"
    length = days_in_month(year, month)
    if length is None:
        return f"month {month} is out of range"
    if day < 1 or day > length:
        return f"day {day} is out of range for month {month}"
    return None


def format_date(year: int, month: int, day: int) -> str:
    return f"{year:04d}-{month:02d}-{day:02d}"


def parse_int(token: str) -> int | None:
    token = token.strip()
    if token.isdigit():
        return int(token)
    return None


def parse_date(
    text: str,
    default_year: int | None = None,
) -> tuple[int, int, int] | None:
    separator = "/" if "/" in text else "-"
    parts = [parse_int(part) for part in text.split(separator)]
    if any(part is None for part in parts):
        return None
    if len(parts) == 3:
        return parts[0], parts[1], parts[2]
    if len(parts) == 2 and default_year is not None:
        return default_year, parts[0], parts[1]
    return None


def normalize(
    text: str,
    default_year: int | None = None,
) -> str | None:
    fields = parse_date(text, default_year)
    if fields is None:
        return None
    year, month, day = fields
    if validate_date(year, month, day) is not None:
        return None
    return format_date(year, month, day)


def day_of_year(year: int, month: int, day: int) -> int | None:
    if validate_date(year, month, day) is not None:
        return None
    total = day
    for earlier in range(1, month):
        total += days_in_month(year, earlier)
    return total


def report(entries: Iterable[str], default_year: int | None = None) -> None:
    for entry in entries:
        formatted = normalize(entry, default_year)
        if formatted is None:
            print(f"{entry!r:>14} -> unrecognized or invalid date")
            continue
        year, month, day = (int(piece) for piece in formatted.split("-"))
        print(f"{entry!r:>14} -> {formatted} (day {day_of_year(year, month, day)} of the year)")


def main() -> None:
    print(format_date(2023, 7, 15))
    print(format_date(2020, 1, 1))
    report(["2023-7-15", "2020/1/1", "2/29", "3/1", "1999-13-02", "yesterday"], default_year=2024)
    problem = validate_date(2023, 2, 30)
    if problem is not None:
        print(f"rejected: {problem}")


if __name__ == "__main__":
    main()

