def update_inventory(inventory, item_name, quantity):
    """Add quantity to item_name in inventory, inserting the item if absent."""
    inventory[item_name] = inventory.get(item_name, 0) + quantity
    return inventory


def parse_quantity(text: str) -> int | None:
    """Return the integer encoded in text, or None if it is not an integer."""
    text = text.strip()
    try:
        return int(text)
    except ValueError:
        return None


def lookup(inventory: dict, item_name: str) -> int | None:
    """Return the stocked amount of item_name, or None if it is untracked."""
    return inventory.get(item_name)


def apply_line(inventory: dict, line: str) -> int | None:
    """Apply one "name qty" instruction; return the new stock or None on error."""
    parts = line.split()
    if len(parts) != 2:
        return None
    name, raw = parts
    quantity = parse_quantity(raw)
    if quantity is None:
        return None
    update_inventory(inventory, name, quantity)
    return inventory[name]


def build_inventory(lines) -> tuple[dict, list[str]]:
    """Apply every instruction line, collecting the ones that could not be read."""
    inventory: dict = {}
    rejected = []
    for line in lines:
        if not line.strip():
            continue
        if apply_line(inventory, line) is None:
            rejected.append(line.strip())
    return inventory, rejected


def total_units(inventory: dict, threshold: int | None = None) -> int:
    """Sum all stock, or only the stock strictly below threshold when given."""
    if threshold is None:
        return sum(inventory.values())
    return sum(q for q in inventory.values() if q < threshold)


def restock_amount(inventory: dict, item_name: str, target: int) -> int | None:
    """How much to order to reach target, or None if the item is untracked."""
    current = lookup(inventory, item_name)
    if current is None:
        return None
    return max(0, target - current)


def format_report(inventory: dict, threshold: int | None = None) -> str:
    lines = []
    for name in sorted(inventory):
        quantity = inventory[name]
        flag = ""
        if threshold is not None and quantity < threshold:
            flag = "  (low)"
        lines.append(f"{name:<10} {quantity:>4}{flag}")
    lines.append(f"{'TOTAL':<10} {total_units(inventory):>4}")
    return "\n".join(lines)


def main() -> None:
    instructions = [
        "apple 10",
        "banana 3",
        "apple 5",
        "cherry twelve",
        "banana 2",
        "date 40",
        "apple -4",
    ]
    inventory, rejected = build_inventory(instructions)
    print(format_report(inventory, threshold=10))
    print("low stock units:", total_units(inventory, threshold=10))
    for name in ("banana", "cherry"):
        needed = restock_amount(inventory, name, 20)
        if needed is None:
            print(f"{name}: not tracked")
        else:
            print(f"{name}: order {needed}")
    if rejected:
        print("unreadable lines:", ", ".join(rejected))


if __name__ == "__main__":
    main()

