def simulate_queue(operations: list[tuple[str, int | None]]) -> list[int | None]:
    """
    Simulates a queue's operations and returns its final state.
    """
    queue: list[int | None] = []
    for operation, item in operations:
        if operation == 'enqueue':
            if item is not None:
                queue.append(item)
        elif operation == 'dequeue':
            if queue:
                queue.pop(0)
    return queue

def _process_single_operation(
    current_queue: list[int | None],
    operation_type: str,
    value_to_add: int | None
) -> list[int | None]:
    """
    Helper to process a single queue operation.
    """
    if operation_type == 'enqueue':
        if value_to_add is not None:
            current_queue.append(value_to_add)
    elif operation_type == 'dequeue':
        if current_queue:
            current_queue.pop(0)
    return current_queue

def _get_queue_size(q: list[int | None]) -> int | None:
    """
    Returns the size of the queue, or None if the queue is empty.
    """
    if not q:
        return None
    return len(q)

def _get_front_element(q: list[int | None]) -> int | None:
    """
    Returns the front element of the queue, or None if the queue is empty.
    """
    if not q:
        return None
    return q[0]

