import re

HASHTAG_RE = re.compile(r"#(\w+)")


def extract_hashtags(text: str | None) -> list[str]:
    """Return the hashtags found in text, without the leading '#'."""
    if text is None:
        return []
    return HASHTAG_RE.findall(text)


def first_hashtag(text: str) -> str | None:
    """Return the first hashtag in text, or None when there is none."""
    tags = extract_hashtags(text)
    if not tags:
        return None
    return tags[0]


def normalize(tag: str, max_length: int | None = None) -> str:
    """Lowercase a tag and optionally truncate it to max_length characters."""
    tag = tag.lower()
    if max_length is not None:
        tag = tag[:max_length]
    return tag


def count_hashtags(texts: list[str], max_length: int | None = None) -> dict[str, int]:
    """Count normalized hashtags across several texts."""
    counts: dict[str, int] = {}
    for text in texts:
        for tag in extract_hashtags(text):
            key = normalize(tag, max_length)
            counts[key] = counts.get(key, 0) + 1
    return counts


def most_common(counts: dict[str, int]) -> tuple[str, int] | None:
    """Return the most frequent (tag, count) pair, or None for empty input."""
    best: tuple[str, int] | None = None
    for tag, count in counts.items():
        if best is None or count > best[1] or (count == best[1] and tag < best[0]):
            best = (tag, count)
    return best


def format_report(counts: dict[str, int], limit: int | None = None) -> str:
    """Render counts as lines of 'tag: count', optionally limited in length."""
    items = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    if limit is not None:
        items = items[:limit]
    return "\n".join(f"{tag}: {count}" for tag, count in items)


def main() -> None:
    samples = [
        "This is a #test with #python.",
        "No hashtags here.",
        "#Python and #python and #PYTHON are the same tag",
        "Mixing #data #science #datascience together",
    ]
    for sample in samples:
        print(sample)
        print("  tags:", extract_hashtags(sample))
        print("  first:", first_hashtag(sample))

    counts = count_hashtags(samples)
    print("\nReport (top 3):")
    print(format_report(counts, limit=3))

    top = most_common(counts)
    if top is None:
        print("\nNo hashtags at all.")
    else:
        print(f"\nMost common: #{top[0]} ({top[1]} times)")

    truncated = count_hashtags(samples, max_length=4)
    print("\nTruncated tags:")
    print(format_report(truncated))


if __name__ == "__main__":
    main()

