def parse_csv_line(line: str) -> list[str]:
    """Split a single CSV line into its comma-separated values."""
    if line.endswith("\n"):
        line = line[:-1]
    return [value.strip() for value in line.split(",")]


def parse_rows(text: str) -> list[list[str]]:
    """Parse every non-empty line of `text` into a row of values."""
    rows: list[list[str]] = []
    for raw in text.splitlines():
        if raw.strip():
            rows.append(parse_csv_line(raw))
    return rows


def field(row: list[str], index: int) -> str | None:
    """Return the value at `index`, or None when the row is too short or the cell is blank."""
    if index >= len(row):
        return None
    return row[index] or None


def to_number(value: str | None) -> float:
    """Convert a cell to a float, using 0.0 when it is missing or not numeric."""
    if value is None:
        return 0.0
    try:
        return float(value)
    except ValueError:
        return 0.0


def column_index(header: list[str], name: str) -> int | None:
    """Locate `name` in the header row, case-insensitively."""
    wanted = name.strip().lower()
    for i, column in enumerate(header):
        if column.lower() == wanted:
            return i
    return None


def column_total(rows: list[list[str]], index: int) -> float | None:
    """Sum the numeric cells of a column; None if the column holds no numbers."""
    total: float | None = None
    for row in rows:
        cell = field(row, index)
        if cell is not None:
            total = to_number(cell) if total is None else total + to_number(cell)
    return total


def format_report(text: str, sum_column: str | None = None) -> str:
    """Render `text` as an aligned table, optionally totalling one column."""
    rows = parse_rows(text)
    if not rows:
        return "no data"
    header, body = rows[0], rows[1:]
    lines = [" | ".join(header), "-" * 30]
    for row in body:
        lines.append(" | ".join(field(row, i) or "-" for i in range(len(header))))
    if sum_column is not None:
        index = column_index(header, sum_column)
        if index is None:
            lines.append(f"unknown column: {sum_column}")
        else:
            total = column_total(body, index)
            shown = "n/a" if total is None else f"{total:g}"
            lines.append(f"total {header[index]}: {shown}")
    return "\n".join(lines)


def main() -> None:
    data = "name,quantity,price\napple,3,1.25\nbanana,,0.50\ncherry,12,4\n"
    print(format_report(data, sum_column="price"))
    print(format_report(data, sum_column="quantity"))
    print(format_report(data, sum_column="weight"))


if __name__ == "__main__":
