import math


def parse_number(token: str) -> float | None:
    """Convert a single token to a float, or None if it is not numeric."""
    try:
        return float(token)
    except ValueError:
        return None


def parse_numbers(text: str) -> list[float] | None:
    """Parse a whitespace/comma separated list of numbers, None if any token is bad."""
    values = []
    for token in text.replace(",", " ").split():
        value = parse_number(token)
        if value is None:
            return None
        values.append(value)
    return values


def calculate_mean(numbers) -> float | None:
    """Arithmetic mean, or None for an empty sample."""
    if not numbers:
        return None
    return sum(numbers) / len(numbers)


def calculate_std_dev(numbers):
    """Sample standard deviation (n - 1 denominator)."""
    mean = calculate_mean(numbers)
    squared_deviations = sum((x - mean) ** 2 for x in numbers)
    return math.sqrt(squared_deviations / (len(numbers) - 1))


def sample_std_dev(numbers) -> float | None:
    """Standard deviation, or None when fewer than two values are available."""
    if len(numbers) < 2:
        return None
    return calculate_std_dev(numbers)


def coefficient_of_variation(numbers) -> float | None:
    """Relative dispersion, or None when it is undefined for this sample."""
    std_dev = sample_std_dev(numbers)
    mean = calculate_mean(numbers)
    if std_dev is None or not mean:
        return None
    return std_dev / abs(mean)


def format_measure(label: str, value: float | None) -> str:
    if value is None:
        return f"{label}: n/a"
    return f"{label}: {value:.3f}"


def describe(text: str) -> str:
    numbers = parse_numbers(text)
    if numbers is None:
        return f"{text!r}: not a valid list of numbers"
    lines = [
        f"sample: {numbers}",
        format_measure("  mean", calculate_mean(numbers)),
        format_measure("  std dev", sample_std_dev(numbers)),
        format_measure("  cv", coefficient_of_variation(numbers)),
    ]
    return "\n".join(lines)


def main() -> None:
    samples = ["1 2 3 4 5", "10, 10, 10", "4.5 7.25", "42", "3 x 9"]
    for sample in samples:
        print(describe(sample))


if __name__ == "__main__":
    main()

