import sys


def normalize_input(value: object) -> str | None:
    """Return the value as text, or None when it cannot be treated as text."""
    if isinstance(value, str):
        return value
    if isinstance(value, (bytes, bytearray)):
        return bytes(value).decode("utf-8", errors="replace")
    return None


def count_uppercase(text: str) -> int:
    """Count the uppercase letters contained in text."""
    normalized = normalize_input(text)
    if normalized is None:
        raise TypeError("count_uppercase() expects a string")
    return sum(1 for character in normalized if character.isupper())


def first_uppercase_index(text: str) -> int | None:
    """Position of the first uppercase letter, or None if there is none."""
    for index, character in enumerate(text):
        if character.isupper():
            return index
    return None


def uppercase_ratio(text: str) -> float | None:
    """Share of uppercase letters among the letters, or None if no letters."""
    letters = [character for character in text if character.isalpha()]
    if not letters:
        return None
    return count_uppercase("".join(letters)) / len(letters)


def parse_limit(raw: str) -> int | None:
    """Read a '--limit=N' style option, returning None when absent or invalid."""
    prefix = "--limit="
    if not raw.startswith(prefix):
        return None
    digits = raw[len(prefix):]
    if digits.isdigit():
        return int(digits)
    return None


def describe(text: str, limit: int | None = None) -> str:
    shown = text if limit is None or len(text) <= limit else text[:limit] + "..."
    total = count_uppercase(text)
    position = first_uppercase_index(text)
    ratio = uppercase_ratio(text)
    parts = [f"{shown!r}: {total} uppercase"]
    if position is None:
        parts.append("no uppercase letter found")
    else:
        parts.append(f"first at index {position}")
    if ratio is None:
        parts.append("no letters to measure")
    else:
        parts.append(f"ratio {ratio:.2f}")
    return " | ".join(parts)


def main(argv: list[str]) -> int:
    limit: int | None = None
    samples: list[str] = []
    for argument in argv[1:]:
        option = parse_limit(argument)
        if option is None:
            samples.append(argument)
        else:
            limit = option
    if not samples:
        samples = ["Hello World", "python is fun", "1234!?", "ALL CAPS HERE"]
    for sample in samples:
        print(describe(sample, limit))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

