from typing import Optional

def is_armstrong(number: Optional[int]) -> Optional[bool]:
    if number is None or number < 0:
        return None

    num_str: Optional[str] = str(number)
    num_digits: Optional[int] = len(num_str)
    sum_of_powers: Optional[int] = 0

    if num_digits is None:
        return None

    for digit_char in num_str:
        digit: Optional[int] = int(digit_char)
        if digit is None:
            return None
        if num_digits is None:
            return None
        sum_of_powers += digit ** num_digits

    return sum_of_powers == number

