from dataclasses import dataclass
from typing import Optional


def parse_guess(text: str) -> Optional[int]:
    """Convert raw user input into a guess, or None if it is not a number."""
    text = text.strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        return None


def simulate_guess(target: int, guess: int) -> str:
    """Return the feedback for a single guess against the target."""
    if guess > target:
        return 'Too high'
    if guess < target:
        return 'Too low'
    return 'Correct!'


@dataclass
class Bounds:
    """The range of numbers still possible for the target."""

    low: Optional[int] = None
    high: Optional[int] = None

    def update(self, guess: int, feedback: str) -> None:
        if feedback == 'Too high':
            if self.high is None or guess - 1 < self.high:
                self.high = guess - 1
        elif feedback == 'Too low':
            if self.low is None or guess + 1 > self.low:
                self.low = guess + 1

    def hint(self) -> Optional[str]:
        """Describe the remaining window, if anything is known about it."""
        if self.low is not None and self.high is not None:
            return f"between {self.low} and {self.high}"
        if self.low is not None:
            return f"greater than or equal to {self.low}"
        if self.high is not None:
            return f"less than or equal to {self.high}"
        return None


def format_round(index: int, guess: int, feedback: str) -> str:
    return f"Round {index}: guess {guess} -> {feedback}"


def play(
    target: int,
    raw_guesses: list[str],
) -> tuple[list[str], Optional[int]]:
