import re

def parse_log_line(log_line: str | None) -> dict | None:
    if log_line is None:
        return None

    pattern: str = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) - (INFO|ERROR|WARNING|DEBUG) - (.*)$'
    match: re.Match | None = re.match(pattern, log_line)

    if match:
        timestamp: str | None = match.group(1)
        level: str | None = match.group(2)
        message: str | None = match.group(3)
        return {'timestamp': timestamp, 'level': level, 'message': message}
    else:
        return None

