import sys


def has_unique_chars(text: str) -> bool:
    """Return True when every character in `text` occurs exactly once."""
    seen: set[str] = set()
    for char in text:
        if char in seen:
            return False
        seen.add(char)
    return True


def first_duplicate(text: str) -> str | None:
    """Return the first character that repeats, or None if all are unique."""
    seen: set[str] = set()
    for char in text:
        if char in seen:
            return char
        seen.add(char)
    return None


def first_duplicate_index(text: str) -> int | None:
    """Return the position of the first repeated character, or None."""
    seen: set[str] = set()
    for index, char in enumerate(text):
        if char in seen:
            return index
        seen.add(char)
    return None


def parse_argument(raw: str) -> str | None:
    """Strip surrounding quotes from an input word; None if nothing remains."""
    cleaned = raw.strip()
    if len(cleaned) >= 2 and cleaned[0] == cleaned[-1] and cleaned[0] in "'\"":
        cleaned = cleaned[1:-1]
    if not cleaned:
        return None
    return cleaned


def describe(text: str) -> str:
    """Build a one line report about the uniqueness of `text`."""
    if has_unique_chars(text):
        return f"{text!r}: True (all {len(text)} characters are unique)"
    duplicate: str | None = first_duplicate(text)
    position = first_duplicate_index(text)
    return f"{text!r}: False (repeat {duplicate!r} at index {position})"


def main(argv: list[str] | None = None) -> int:
    words = argv if argv is not None else sys.argv[1:]
    if not words:
        words = sys.stdin.read().split()
    candidates = [parse_argument(word) for word in words]
    for candidate in candidates:
        if candidate is not None:
            print(describe(candidate))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

