def minutes_to_hh_mm(total_minutes: int | None) -> str | None:
    if total_minutes is None:
        return None
    if not isinstance(total_minutes, int):
        raise TypeError("total_minutes must be an integer.")
    if total_minutes < 0:
        raise ValueError("total_minutes cannot be negative.")

    hours: int | None = total_minutes // 60
    minutes: int | None = total_minutes % 60

    if hours is None or minutes is None:
        return None

    hours_str: str | None = f"{hours:02d}"
    minutes_str: str | None = f"{minutes:02d}"

    if hours_str is None or minutes_str is None:
        return None

    formatted_time: str | None = f"{hours_str}:{minutes_str}"
    return formatted_time

def format_time_component(component: int | None) -> str | None:
    if component is None:
        return None
    return f"{component:02d}"

def process_and_format(raw_minutes: int | None) -> str | None:
    if raw_minutes is None:
        return None

