from urllib.parse import urlsplit

SCHEME_PORTS = {"http": 80, "https": 443}


def scheme_of(url: str) -> str | None:
    """Return the lower-case scheme of `url`, or None when it is missing."""
    scheme = urlsplit(url).scheme.lower()
    if scheme in SCHEME_PORTS:
        return scheme
    return None


def default_port(scheme: str) -> int | None:
    """Well-known port for a scheme, or None for unrecognised schemes."""
    return SCHEME_PORTS.get(scheme)


def explicit_port(url: str) -> int | None:
