PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def first_invalid_char(s: str) -> str | None:
    """Return the first character that is not a bracket, or None if all are."""
    for ch in s:
        if ch not in PAIRS and ch not in OPENERS:
            return ch
    return None


def find_mismatch(s: str) -> int | None:
    """Return the index of the first bracket that breaks nesting, else None."""
    stack: list[int] = []
    for index, ch in enumerate(s):
        if ch in OPENERS:
            stack.append(index)
        else:
            if not stack:
                return index
            opener = s[stack.pop()]
            if opener != PAIRS[ch]:
                return index
    if stack:
        return stack[0]
    return None


def is_brackets_balanced(s: str) -> bool:
    bad = first_invalid_char(s)
    if bad is not None:
        raise ValueError(f"unsupported character: {bad!r}")
    return find_mismatch(s) is None


def max_nesting_depth(s: str) -> int | None:
    """Depth of the deepest nesting, or None when the string is unbalanced."""
    if not is_brackets_balanced(s):
        return None
    depth = 0
    best = 0
    for ch in s:
        if ch in OPENERS:
            depth += 1
            best = max(best, depth)
        else:
            depth -= 1
    return best


def depth_violation(
    s: str,
    max_depth: int | None = None,
) -> int | None:
    """Return the nesting depth when it exceeds max_depth, else None."""
    depth = max_nesting_depth(s)
    if depth is None or max_depth is None or depth <= max_depth:
        return None
    return depth


def describe(
    s: str,
    max_depth: int | None = None,
) -> str:
    try:
        balanced = is_brackets_balanced(s)
    except ValueError as exc:
        return f"{s!r}: invalid input ({exc})"
    if not balanced:
        return f"{s!r}: not balanced, problem at index {find_mismatch(s)}"
    too_deep = depth_violation(s, max_depth)
    if too_deep is not None:
        return f"{s!r}: balanced but nested {too_deep} levels deep"
    return f"{s!r}: balanced, depth {max_nesting_depth(s)}"


def main() -> None:
    for sample in ['()[]{}', '([{}])', '({[})', '', '(()', ']', '(a)']:
        print(describe(sample))
    print(describe('((((()))))', max_depth=3))


if __name__ == '__main__':
    main()

