def simulate_dice_sum(num_dice: int) -> int:
    """
    Simulates rolling a specified number of 6-sided dice and returns their sum.

    Args:
        num_dice: The number of dice to roll.

    Returns:
        The total sum of the dice rolls.
    """
    if num_dice <= 0:
        return 0

    total_sum: int | None = 0
    for _ in range(num_dice):
        roll: int | None = random.randint(1, 6)
        if total_sum is not None and roll is not None:
            total_sum += roll
        else:
            # This branch should ideally not be reached with current logic
            total_sum = None # Indicate an issue if intermediate sum or roll is None

    # Ensure we return an int, handling potential None from error state
    return total_sum if total_sum is not None else 0

def _get_random_roll(sides: int | None = 6) -> int | None:
    if sides is None or sides <= 0:
        return None
    return random.randint(1, sides)

def _process_rolls(rolls: list[int | None]) -> int | None:
    current_sum: int | None = 0
    for roll_val in rolls:
        if roll_val is not None and current_sum is not None:
            current_sum += roll_val
        else:
            current_sum = None # Propagate None if any roll is invalid or sum becomes invalid
            break
    return current_sum

