from collections import Counter
import sys


def parse_numbers(text: str) -> list[int] | None:
    """Parse a whitespace/comma separated line of integers, or None if malformed."""
    tokens = text.replace(",", " ").split()
    values: list[int] = []
    for token in tokens:
        try:
            values.append(int(token))
        except ValueError:
            return None
    return values


def describe_problem(numbers: list[int]) -> str | None:
    """Return a message explaining why the input is not valid, or None if it is."""
    n = len(numbers) - 1
    if n < 1:
        return "need at least two values"
    outside = [value for value in numbers if not 1 <= value <= n]
    if outside:
        return f"values outside 1..{n}: {outside}"
    counts = Counter(numbers)
    repeated = sorted(value for value, count in counts.items() if count > 1)
    if len(repeated) != 1 or counts[repeated[0]] != 2:
        return f"expected exactly one value appearing twice, got {repeated}"
    return None


def find_duplicate(numbers: list[int]) -> int:
    """Return the single duplicated value in numbers (which covers 1..N)."""
    problem = describe_problem(numbers)
    if problem is not None:
        raise ValueError(problem)
    n = len(numbers) - 1
    duplicate_num = sum(numbers) - n * (n + 1) // 2
    return duplicate_num


def format_report(numbers: list[int], label: str) -> str:
    """Describe the outcome for one already-parsed list of numbers."""
    problem = describe_problem(numbers)
    if problem is not None:
        return f"{label}: {problem}"
    return f"{label}: {numbers} -> duplicate {find_duplicate(numbers)}"


def process_line(line: str, label: str) -> str | None:
    """Turn one input line into a report line, or None if the line is blank."""
    if not line.strip():
        return None
    numbers = parse_numbers(line)
    if numbers is None:
        return f"{label}: not a list of integers: {line.strip()!r}"
    return format_report(numbers, label)


def read_lines(path: str | None = None) -> list[str]:
    """Read input lines from a file, or from standard input when no path given."""
    if path is None:
        return sys.stdin.read().splitlines()
    with open(path, encoding="utf-8") as handle:
        return handle.read().splitlines()


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    path = args[0] if args else None
    failures = 0
    for index, line in enumerate(read_lines(path), start=1):
        report = process_line(line, f"line {index}")
        if report is None:
            continue
        if "duplicate" not in report:
            failures += 1
        print(report)
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())

