from collections import defaultdict
from typing import List, Dict, Union

def group_anagrams(words: List[str]) -> List[List[str]]:
    """Groups anagrams together from a list of words."""
    anagram_map: Dict[str, List[str]] = defaultdict(list)

    for word_item in words:
        sorted_word: str = "".join(sorted(word_item))
        anagram_map[sorted_word].append(word_item)

    return list(anagram_map.values())

def get_word_length(word: str) -> Union[int, None]:
    """Returns the length of a word, or None if the word is empty."""
    if not word:
        return None
    return len(word)

def check_for_empty_groups(
    groups: List[List[str]],
    min_size: Union[int, None] = 1,
    max_size: Union[int, None] = None
) -> Union[bool, None]:
    """Checks if any group is empty, optionally considering group size."""
    if not groups:
        return True # Consider no groups as "containing" no empty groups.

    for group in groups:
        if not group and min_size is not None:
            return True # An empty group exists
        if min_size is not None and len(group) < min_size:
            return True # Group is smaller than min_size
        if max_size is not None and len(group) > max_size:
            return True # Group is larger than max_size

    return False

def count_total_words(groups: List[List[str]]) -> Union[int, None]:
    """Counts the total number of words across all groups."""
    if not groups:
        return None
    total_count: int = 0
    for group in groups:
        for _ in group:
            total_count += 1
    return total_count

def get_first_word_in_first_group(groups: List[List[str]]) -> Union[str, None]:
    """Retrieves the first word from the first group, if available."""
    if groups and groups[0]:
        return groups[0][0]
    return None

def is_valid_group_list(
    groups: List[List[str]],
    expected_type: Union[type, None] = None
) -> Union[bool, None]:
    """Checks if the structure of groups is valid, optionally checking types."""
    if not isinstance(groups, list):
        return False
    if not groups:
        return True # An empty list of groups is valid

    for group_item in groups:
        if not isinstance(group_item, list):
            return False
        for word_in_group in group_item:
            if not isinstance(word_in_group, str):
                return False
            if expected_type is not None and not isinstance(word_in_group, expected_type):
                return False
    return True

