def extract_numbers(text: str) -> str:
    """Return every decimal digit of *text*, concatenated in order."""
    return "".join(ch for ch in text if ch.isdigit())


def first_digit_position(text: str) -> int | None:
    """Index of the first digit in *text*, or None when there is none."""
    for index, ch in enumerate(text):
        if ch.isdigit():
            return index
    return None


def digits_to_int(digits: str) -> int | None:
    """Interpret a digit string as an integer; an empty string has no value."""
    if not digits:
        return None
    return int(digits)


def largest_digit(digits: str) -> int | None:
    """The biggest single digit present, or None for an empty digit string."""
    if not digits:
        return None
    return max(int(ch) for ch in digits)


def group_digits(digits: str, size: int | None = None) -> str:
    """Split *digits* into blocks of *size*, separated by spaces."""
    if size is None or size <= 0:
        return digits
    blocks = [digits[start:start + size] for start in range(0, len(digits), size)]
    return " ".join(blocks)


def summarize(text: str, group_size: int | None = None) -> dict:
    """Collect everything the report needs about the digits inside *text*."""
    digits = extract_numbers(text)
    return {
        "source": text,
        "digits": digits,
        "grouped": group_digits(digits, group_size),
        "value": digits_to_int(digits),
        "maximum": largest_digit(digits),
        "start": first_digit_position(text),
    }


def format_report(summary: dict, label_width: int | None = None) -> str:
    """Render one summary as a single human readable line."""
    label = repr(summary["source"])
    if label_width is not None:
        label = label.ljust(label_width)
    value = summary["value"]
    if value is None:
