from typing import Optional


def parse_hour(text: str) -> Optional[int]:
    """Convert a textual hour into an integer, or None if it is not a valid hour."""
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    value = int(stripped)
    if 0 <= value <= 24:
        return value
    return None


def parse_task(line: str) -> Optional[tuple[str, int, int]]:
    """Parse 'name,start,end' into a task tuple, or None if the line is unusable."""
    parts = line.split(",")
    if len(parts) != 3:
        return None
    start = parse_hour(parts[1])
    end = parse_hour(parts[2])
    if start is None or end is None or start >= end:
        return None
    return parts[0].strip(), start, end


def has_overlap(task1_start: int, task1_end: int, task2_start: int, task2_end: int) -> bool:
    """Return True when the two half-open intervals share at least one hour."""
    return task1_start < task2_end and task2_start < task1_end


def overlap_window(
    task1_start: int, task1_end: int, task2_start: int, task2_end: int
) -> Optional[tuple[int, int]]:
    """Return the shared (start, end) window, or None when the tasks do not overlap."""
    if not has_overlap(task1_start, task1_end, task2_start, task2_end):
        return None
    return max(task1_start, task2_start), min(task1_end, task2_end)


def first_conflict(
    tasks: list[tuple[str, int, int]]
) -> Optional[tuple[tuple[str, int, int], tuple[str, int, int]]]:
    """Find the earliest pair of clashing tasks in the schedule."""
    ordered = sorted(tasks, key=lambda task: (task[1], task[2]))
    for index in range(len(ordered) - 1):
        left, right = ordered[index], ordered[index + 1]
        if has_overlap(left[1], left[2], right[1], right[2]):
            return left, right
    return None


def describe_conflict(tasks: list[tuple[str, int, int]]) -> Optional[str]:
    """Build a human readable conflict message, or None for a clean schedule."""
    conflict = first_conflict(tasks)
    if conflict is None:
        return None
    left, right = conflict
    start, end = max(left[1], right[1]), min(left[2], right[2])
    return f"{left[0]} and {right[0]} clash from {start:02d}:00 to {end:02d}:00"


def main() -> None:
    raw_schedule = [
        "standup,9,12",
        "review,11,14",
        "lunch,12,13",
        "retro,nine,ten",
    ]
    tasks: list[tuple[str, int, int]] = []
    for line in raw_schedule:
        task = parse_task(line)
        if task is None:
            print(f"skipping malformed entry: {line}")
            continue
        tasks.append(task)
    message = describe_conflict(tasks)
    print(message if message is not None else "no conflicts found")
    print(overlap_window(9, 10, 10, 12))


if __name__ == "__main__":
    main()

