    """Convert user text into a non-negative amount, or None when it is unusable."""
    cleaned = text.strip().replace(",", "").lstrip("$")
    if not cleaned:
        return None
    try:
        value = float(cleaned)
    except ValueError:
        return None
    if value < 0:
        return None
    return value


def parse_years(text: str) -> int | None:
    """Convert user text into a whole number of years, or None when it is unusable."""
    amount = parse_amount(text)
    if amount is None or amount != int(amount):
        return None
    return int(amount)


def parse_record(line: str) -> tuple[float, float, int] | None:
    """Parse a 'principal,rate,years' record into validated numbers."""
    fields = [field for field in line.split(",") if field.strip()]
    if len(fields) != 3:
        return None
    principal = parse_amount(fields[0])
    rate = parse_amount(fields[1])
    years = parse_years(fields[2])
    if principal is None or rate is None or years is None:
        return None
    return principal, rate, years


def total_amount(principal: float, rate: float, time: int) -> float:
    """Return principal plus the simple interest it accrues."""
    return principal + calculate_simple_interest(principal, rate, time)


def years_to_double(principal: float, rate: float) -> int | None:
    """Smallest whole number of years for simple interest to match the principal."""
    if principal <= 0 or rate <= 0:
        return None
    years = 1
    while calculate_simple_interest(principal, rate, years) < principal:
        years += 1
    return years


