    """Rank the words of text by frequency; limit None keeps every word."""
    counts = Counter(word.lower() for word in extract_words(text))
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    if limit is None:
        return ranked
    return ranked[:limit]


def describe(text: str) -> str:
    """Build a one-line report about the words found in text."""
    parts = [f"words={count_words(text)}"]
    best = longest_word(text)
    if best is not None:
        parts.append(f"longest={best!r}")
    mean = average_word_length(text)
    if mean is not None:
        parts.append(f"avg_len={mean:.2f}")
    frequent = top_words(text, 3)
    if frequent:
        listing = " ".join(f"{word}:{n}" for word, n in frequent)
        parts.append(f"top={listing}")
    return ", ".join(parts)


def read_text(argv: list[str]) -> Optional[str]:
    """Join command-line arguments into one text, or None if none were given."""
    if len(argv) <= 1:
        return None
    return " ".join(argv[1:])


def main() -> None:
    text = read_text(sys.argv)
    if text is None:
        text = sys.stdin.read()
    print(describe(text))


if __name__ == "__main__":
    main()

