import sys


def parse_number(text: str) -> int | None:
    """Convert a command-line token to a positive integer, or None if invalid."""
    token = text.strip().lstrip("+")
    if not token.isdigit():
        return None
    value = int(token)
    if value < 1:
        return None
    return value


def format_report(number: int | None) -> str:
    """Describe one parsed token; unparsable tokens are reported as skipped."""
    if number is None:
        return "skipped: not a positive integer"
    parts = " + ".join(str(d) for d in proper_divisors(number)) or "0"
    verdict = "is" if is_perfect_number(number) else "is not"
    return (f"{number}: {parts} = {aliquot_sum(number)} -> {number} {verdict} "
            f"perfect ({classify(number)})")


def parse_limit(args: list[str]) -> int | None:
    """Value following the first --limit flag, or None when absent or invalid."""
    for index, arg in enumerate(args):
        if arg == "--limit" and index + 1 < len(args):
            return parse_number(args[index + 1])
    return None


def strip_options(args: list[str]) -> list[str]:
    """Drop the --limit flag and its value, keeping the plain number tokens."""
    tokens: list[str] = []
    expect_value = False
    for arg in args:
        if expect_value:
            expect_value = False
        elif arg == "--limit":
            expect_value = True
        else:
            tokens.append(arg)
    return tokens


def proper_divisors(number: int) -> list[int]:
    """All positive divisors of `number` except `number` itself."""
    divisors = set()
    candidate = 1
    while candidate * candidate <= number:
        if number % candidate == 0:
            divisors.add(candidate)
            divisors.add(number // candidate)
        candidate += 1
    divisors.discard(number)
    return sorted(divisors)


def aliquot_sum(number: int) -> int:
    """Sum of the proper divisors of `number`."""
    return sum(proper_divisors(number))


def is_perfect_number(number: int) -> bool:
    if number < 2:
        return False
    return aliquot_sum(number) == number


def classify(number: int) -> str:
    total = aliquot_sum(number)
    if total == number:
        return "perfect"
    if total > number:
        return "abundant"
    return "deficient"


def next_perfect_number(
    start: int,
    limit: int | None = None,
) -> int | None:
    """Smallest perfect number >= start, searching up to `limit` inclusive."""
    candidate = max(start, 2)
    while limit is None or candidate <= limit:
        if is_perfect_number(candidate):
            return candidate
        candidate += 1
    return None


def main(argv: list[str]) -> int:
    limit = parse_limit(argv[1:])
    tokens = strip_options(argv[1:]) or ["6", "28", "18", "1"]
    for token in tokens:
        print(format_report(parse_number(token)))
    following = next_perfect_number(497, limit)
    if following is None:
        print(f"no perfect number in 497..{limit}")
    else:
        print(f"next perfect number at or above 497: {following}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

