from collections import OrderedDict
from typing import Any, Iterable


def sort_dict_by_key(input_dict: dict) -> OrderedDict:
    """Return a new OrderedDict with the items of input_dict ordered by key."""
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict")
    return OrderedDict(sorted(input_dict.items()))


def find_position(input_dict: dict, wanted_key: Any) -> int | None:
    """Return the zero-based rank of wanted_key once the dict is sorted."""
    for index, key in enumerate(sort_dict_by_key(input_dict)):
        if key == wanted_key:
            return index
    return None


def first_key(input_dict: dict) -> str | None:
    """Return the smallest key of input_dict, or None when it is empty."""
    for key in sort_dict_by_key(input_dict):
        return key
    return None


def key_before(input_dict: dict, wanted_key: Any) -> str | None:
    """Return the key that precedes wanted_key in sorted order, if any."""
    position = find_position(input_dict, wanted_key)
    if position is None or position == 0:
        return None
    return list(sort_dict_by_key(input_dict))[position - 1]


def merge_sorted(dicts: Iterable[dict]) -> OrderedDict:
    """Merge several dicts (later values win) and sort the result by key."""
    merged: dict = {}
    for piece in dicts:
        merged.update(piece)
    return sort_dict_by_key(merged)


def value_for_rank(input_dict: dict, rank: int) -> int | None:
    """Return the value sitting at the given rank in key order."""
    items = list(sort_dict_by_key(input_dict).items())
    if rank < 0 or rank >= len(items):
        return None
    return items[rank][1]


def format_sorted(input_dict: dict, limit: int | None = None) -> str:
    """Render the sorted dict as 'key=value' pairs, optionally truncated."""
    pairs = [f"{key}={value}" for key, value in sort_dict_by_key(input_dict).items()]
    if limit is not None and len(pairs) > limit:
        pairs = pairs[:limit] + ["..."]
    return ", ".join(pairs)


def main() -> None:
    sample = {'b': 2, 'a': 1, 'c': 3}
    print(sort_dict_by_key(sample))
    print(sort_dict_by_key({'z': 26, 'y': 25}))

    print("position of 'c':", find_position(sample, 'c'))
    print("position of 'q':", find_position(sample, 'q'))
    print("first key:", first_key(sample))
    print("first key of empty dict:", first_key({}))
    print("key before 'c':", key_before(sample, 'c'))
    print("key before 'a':", key_before(sample, 'a'))

    combined = merge_sorted([sample, {'d': 4, 'a': 99}])
    print("merged:", combined)
    print("value at rank 2:", value_for_rank(combined, 2))
    print("value at rank 9:", value_for_rank(combined, 9))

    print("full:", format_sorted(combined))
    print("short:", format_sorted(combined, limit=2))


if __name__ == "__main__":
    main()

