def normalize(s: str, casefold: bool = False, ignore: str | None = None) -> str:
    """Return the string prepared for uniqueness checks."""
    text = s.casefold() if casefold else s
    if ignore:
        text = "".join(ch for ch in text if ch not in ignore)
    return text


def first_duplicate(s: str) -> str | None:
    """Return the first character that repeats, or None if all are unique."""
    seen: set[str] = set()
    for ch in s:
        if ch in seen:
            return ch
        seen.add(ch)
    return None


def first_duplicate_index(s: str) -> int | None:
    """Return the position of the first repeated character, or None."""
    seen: set[str] = set()
    for index, ch in enumerate(s):
        if ch in seen:
            return index
        seen.add(ch)
    return None


def has_all_unique_chars(s: str) -> bool:
    """Return True when no character of s appears more than once."""
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    return first_duplicate(s) is None


def longest_unique_prefix(s: str) -> str:
    """Return the longest leading run of s that has no repeats."""
    cut: int | None = first_duplicate_index(s)
    if cut is None:
        return s
    return s[:cut]


def describe(s: str, casefold: bool = False, ignore: str | None = None) -> str:
    """Build a one-line report about the uniqueness of s."""
    text = normalize(s, casefold=casefold, ignore=ignore)
    if has_all_unique_chars(text):
        return f"{s!r}: all {len(text)} characters are unique"
    culprit: str | None = first_duplicate(text)
    position = first_duplicate_index(text)
    return (
        f"{s!r}: character {culprit!r} repeats at index {position}; "
        f"unique prefix {longest_unique_prefix(text)!r}"
    )


def main() -> None:
