import sys

def parse_base(text: str) -> int | float | None:
    """Parse a base value; return None when the text is not a number."""
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return None


def parse_exponent(text: str) -> int | None:
    """Parse an exponent; only whole numbers are accepted."""
    try:
        return int(text)
    except ValueError:
        return None


def calculate_power(base: int | float, exponent: int) -> int | float:
    """Return base raised to exponent using repeated multiplication."""
    if not isinstance(exponent, int) or isinstance(exponent, bool):
        raise TypeError("exponent must be an int")
    if exponent < 0:
        return 1 / calculate_power(base, -exponent)
    result: int | float = 1
    for _ in range(exponent):
        result *= base
    return result


def safe_power(base_text: str, exponent_text: str) -> int | float | None:
    """Compute a power from raw text, returning None if it is not defined."""
    base = parse_base(base_text)
    exponent = parse_exponent(exponent_text)
    if base is None or exponent is None:
        return None
    try:
        return calculate_power(base, exponent)
    except ZeroDivisionError:
        return None


def format_result(value: int | float | None) -> str:
    if value is None:
        return "undefined"
    if isinstance(value, int):
        return str(value)
    return f"{value:.6g}"


def smallest_exponent_above(base: int | float, target: int | float,
                            limit: int = 64) -> int | None:
    """Smallest exponent e in 0..limit with base**e > target, or None."""
    for exponent in range(limit + 1):
        if calculate_power(base, exponent) > target:
            return exponent
    return None


def read_pairs(args: list[str]) -> list[tuple[str, str]]:
    if len(args) >= 2:
        return [(args[i], args[i + 1]) for i in range(0, len(args) - 1, 2)]
    return [("2", "3"), ("5", "0"), ("2", "-2"), ("1.5", "4"), ("0", "-1")]


def main() -> None:
    for base_text, exponent_text in read_pairs(sys.argv[1:]):
        result = safe_power(base_text, exponent_text)
        print(f"{base_text} ^ {exponent_text} = {format_result(result)}")
        base = parse_base(base_text)
        if base is not None and result is not None:
            reach = smallest_exponent_above(base, 1000)
            label = "never" if reach is None else f"exponent {reach}"
            print(f"  exceeds 1000 at {label}")


if __name__ == "__main__":
    main()

