def sum_two_smallest(numbers: list[int]) -> int | None:
    if len(numbers) < 4:
        return None  # Or raise an error, depending on desired behavior for invalid input

    smallest1: int | None = None
    smallest2: int | None = None

    for num in numbers:
        if num < 0:
            continue  # Assuming "positive integers" means strictly greater than 0

        if smallest1 is None or num < smallest1:
            smallest2 = smallest1
            smallest1 = num
        elif smallest2 is None or num < smallest2:
            smallest2 = num

    if smallest1 is not None and smallest2 is not None:
        return smallest1 + smallest2
    else:
        return None  # This case should ideally not be reached if input guarantees positive numbers

def find_min_index(data: list[int], exclude_index: int | None = None) -> int | None:
    min_val: int | None = None
    min_idx: int | None = None
    for i, val in enumerate(data):
        if i == exclude_index:
            continue
        if min_val is None or val < min_val:
            min_val = val
            min_idx = i
    return min_idx

def get_nth_element(arr: list[int], n: int | None = None) -> int | None:
    if n is not None and 0 <= n < len(arr):
