import math


def parse_side(token: str) -> float | None:
    """Convert a text token into a positive side length, or None if invalid."""
    try:
        value = float(token)
    except ValueError:
        return None
    if value <= 0 or math.isinf(value) or math.isnan(value):
        return None
    return value


def parse_triangle(line: str) -> tuple[float, float, float] | None:
    """Parse a line of three side lengths separated by commas or whitespace."""
    tokens = line.replace(",", " ").split()
    if len(tokens) != 3:
        return None
    sides = []
    for token in tokens:
        side: float | None = parse_side(token)
        if side is None:
            return None
        sides.append(side)
    return sides[0], sides[1], sides[2]


def triangle_area(a, b, c):
    """Area of the triangle with the given sides, or 0.0 if it is degenerate."""
    if min(a, b, c) <= 0:
        return 0.0
    x, y, z = sorted((float(a), float(b), float(c)))
    if x + y <= z:
        return 0.0
    s = (x + y + z) / 2.0
    return math.sqrt(s * (s - x) * (s - y) * (s - z))


def classify(a: float, b: float, c: float, tolerance: float = 1e-9) -> str | None:
    """Name the triangle's shape, or None when the sides are not a triangle."""
    if triangle_area(a, b, c) == 0.0:
        return None
    x, y, z = sorted((a, b, c))
    if abs(x - z) <= tolerance:
        return "equilateral"
    if abs(x - y) <= tolerance or abs(y - z) <= tolerance:
        return "isosceles"
    if abs(x * x + y * y - z * z) <= tolerance * z * z:
        return "right"
    return "scalene"


def describe(line: str) -> str:
    """Build a one-line report for a raw input line."""
    sides: tuple[float, float, float] | None = parse_triangle(line)
    if sides is None:
        return f"{line.strip()!r}: not three valid side lengths"
    a, b, c = sides
    area = triangle_area(a, b, c)
    shape: str | None = classify(a, b, c)
    if shape is None:
        return f"{a:g}, {b:g}, {c:g}: degenerate (area {area:.4f})"
    return f"{a:g}, {b:g}, {c:g}: {shape} (area {area:.4f})"


def main() -> None:
    samples = [
        "3 4 5",
        "1 1 10",
        "2, 2, 2",
        "5 5 8",
        "7 8 9",
        "3 4",
        "-1 2 2",
        "abc 4 5",
    ]
    for sample in samples:
        print(describe(sample))


if __name__ == "__main__":
    main()

