def split_email(email_string: str) -> tuple[str, str] | None:
    """Split an address into (local, domain), or None if there is not exactly one '@'."""
    parts = email_string.split("@")
    if len(parts) != 2:
        return None
    return parts[0], parts[1]


def domain_of(email_string: str) -> str | None:
    """Return the domain part of an address, or None when the address is unusable."""
    pieces = split_email(email_string)
    if pieces is None:
        return None
    return pieces[1]


def is_valid_email(email_string: str) -> bool:
    """True if the string contains exactly one '@' and at least one '.' after it."""
    domain = domain_of(email_string)
    if domain is None:
        return False
    return "." in domain


def top_level_domain(email_string: str) -> str | None:
    """Return the last dot-separated label of the domain, or None for invalid addresses."""
    domain = domain_of(email_string)
    if domain is None or "." not in domain:
        return None
    return domain.rsplit(".", 1)[1]


