import sys


def parse_int(token: str) -> int | None:
    """Return the integer value of token, or None when it is not numeric."""
    try:
        return int(token)
    except ValueError:
        return None


def parse_list(text: str) -> list:
    """Turn "1, 2, a" into [1, 2, 'a'], keeping non-numeric items as strings."""
    items = []
    for raw in text.split(","):
        token = raw.strip()
        if not token:
            continue
        number = parse_int(token)
        items.append(token if number is None else number)
    return items


def parse_limit(text: str) -> int | None:
    """An empty field means "no limit"; anything else must be a whole number."""
    stripped = text.strip()
    if not stripped:
        return None
    limit = parse_int(stripped)
    if limit is None:
        raise ValueError(f"limit must be an integer, got {stripped!r}")
    if limit < 0:
        raise ValueError("limit must not be negative")
    return limit


def cartesian_product(list1, list2):
    pairs = []
    for left in list1:
        for right in list2:
            pairs.append((left, right))
    return pairs


def bounded_product(list1, list2, limit: int | None = None):
    """Cartesian product, truncated to the first `limit` pairs if given."""
    pairs = cartesian_product(list1, list2)
    if limit is None:
        return pairs
    return pairs[:limit]


def column_width(pairs) -> int | None:
    """Widest rendered pair, or None when there is nothing to render."""
    widths = [len(f"({pair[0]!r}, {pair[1]!r})") for pair in pairs]
    if not widths:
        return None
    return max(widths)


def format_pairs(pairs, width: int | None = None) -> str:
    if width is None:
        width = column_width(pairs)
    if width is None:
        return "(no pairs)"
    return "\n".join(f"({pair[0]!r}, {pair[1]!r})".ljust(width) for pair in pairs)


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    if len(args) < 2:
        print("usage: product.py LIST1 LIST2 [LIMIT]")
        return 1
    limit = parse_limit(args[2]) if len(args) > 2 else None
    pairs = bounded_product(parse_list(args[0]), parse_list(args[1]), limit)
    print(format_pairs(pairs))
    print(f"{len(pairs)} pair(s)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

