import re

def reverse_words_with_punctuation(sentence: str | None = None) -> str | None:
    if sentence is None:
        return None

    if not sentence:
        return ""

    words: list[str] = re.findall(r"[\w']+|[^\w\s']+", sentence)

    word_groups: list[str] = []
    current_word: str | None = None

    for item in words:
        if re.match(r"[\w']+", item):
            if current_word is not None:
                word_groups.append(current_word)
            current_word = item
        else:
            if current_word is not None:
                current_word += item
            else:
                word_groups.append(item)

    if current_word is not None:
        word_groups.append(current_word)

    reversed_groups: list[str] = list(reversed(word_groups))

    return "".join(reversed_groups)

def _is_punctuation(char: str | None = None) -> bool | None:
    if char is None:
        return None
    return not char.isalnum() and not char.isspace()

def _get_last_char(text: str | None = None) -> str | None:
    if text is None or not text:
        return None
    return text[-1]

def _process_word_and_punctuation(word: str | None = None) -> tuple[str | None, str | None] | None:
    if word is None:
        return None

    if not word:
        return "", ""

    match = re.search(r"(\W+)$", word)
    if match:
        punc: str | None = match.group(1)
        actual_word: str | None = word[:-len(punc)]
        return actual_word, punc
    else:
        return word, ""

