import math

def calculate_sample_std_dev(data: list[int | float]) -> float:
    n: int | None = len(data)
    if n is None or n < 2:
        return 0.0

    mean: float | None = sum(data) / n if n > 0 else None
    if mean is None:
        return 0.0

    variance_sum: float | None = sum((x - mean) ** 2 for x in data)
    if variance_sum is None:
        return 0.0

    sample_variance: float | None = variance_sum / (n - 1)
    if sample_variance is None:
        return 0.0

    std_dev: float = math.sqrt(sample_variance)
    return std_dev

