def get_quadrant(x: float | int, y: float | int) -> int | None:
    """
    Determines the quadrant of a point (x, y) in a 2D Cartesian coordinate system.

    Args:
        x: The x-coordinate of the point.
        y: The y-coordinate of the point.

    Returns:
        1, 2, 3, or 4 for the respective quadrants.
        0 if the point lies on an axis.
        None if x or y is not a valid number.
    """
    if not isinstance(x, (float, int)) or not isinstance(y, (float, int)):
        return None

    if x == 0 or y == 0:
        return 0
    elif x > 0 and y > 0:
        return 1
    elif x < 0 and y > 0:
        return 2
    elif x < 0 and y < 0:
        return 3
    else:  # x > 0 and y < 0
        return 4

def process_points(points: list[tuple[float | int, float | int]]) -> list[int | None]:
    """
    Processes a list of points and returns their quadrants.

    Args:
        points: A list of (x, y) tuples. Each coordinate can be float or int.

    Returns:
        A list of integers representing the quadrants, or None for invalid points.
    """
    results: list[int | None] = []
    for px, py in points:
        quadrant: int | None = get_quadrant(px, py)
        results.append(quadrant)
    return results

def get_quadrant_info(x: float | int, y: float | int, verbose: bool | None = True) -> str | int | None:
    quadrant_num: int | None = get_quadrant(x, y)
    if verbose:
        if quadrant_num == 0:
            return "On an axis"
        elif quadrant_num is not None:
            return f"Quadrant {quadrant_num}"
        else:
            return "Invalid coordinates"
    return quadrant_num

