    """Censors specific words in a text."""
    censored_text = text
    flags = 0 if case_sensitive else re.IGNORECASE

    for word in bad_words:
        if word:
            replacement_char = custom_mask if custom_mask is not None else '*'
            replacement = replacement_char * len(word)

            if max_replacements is not None:
                censored_text = re.sub(re.escape(word), replacement, censored_text, count=max_replacements, flags=flags)
            else:
                censored_text = re.sub(re.escape(word), replacement, censored_text, flags=flags)

    if not preserve_whitespace:
        censored_text = ' '.join(censored_text.split())

    return censored_text

