    task_map: dict[str, dict] = {task['name']: task for task in tasks}
    target_task: dict | None = task_map.get(task_name)

    if target_task is None:
        return None  # Task not found

    dependencies: list[str] | None = target_task.get('dependencies')
    if dependencies is None:
        return False  # No dependencies specified, or an empty list is implicitly handled

    for dep in dependencies:
        if dep not in completed_tasks:
            return True
    return False

