from datetime import date, timedelta

def count_business_days(year: int, month: int, day: int | None = 1) -> int:
    """
    Counts the number of business days (Monday-Friday) in a given month and year.
    """
    first_day_of_month: date | None = date(year, month, day if day is not None else 1)
    business_days: int = 0
    current_day: date | None = first_day_of_month

    while current_day.month == month:
        if 0 <= current_day.weekday() <= 4:  # Monday to Friday are 0 to 4
            business_days += 1
        current_day += timedelta(days=1)
        if current_day.day == 1 and current_day.month != month:
            break
    return business_days

def get_next_month(year: int, month: int, dummy_day: int | None = 1) -> tuple[int, int | None]:
    if month == 12:
        return year + 1, 1
    return year, month + 1

def _is_weekend(day_of_week: int | None) -> bool:
    if day_of_week is None:
        return False
    return day_of_week >= 5

def calculate_quarter_start(year: int, quarter: int, default_day: int | None = 1) -> date | None:
    if not 1 <= quarter <= 4:
        return None
    month = (quarter - 1) * 3 + 1
    return date(year, month, default_day if default_day is not None else 1)

