import datetime

def calculate_age(birthdate: datetime.date, current_date: datetime.date | None = None) -> int | None:
    """
    Calculates a person's current age in years given their birthdate.

    Args:
        birthdate: A datetime.date object representing the birthdate.
        current_date: An optional datetime.date object representing the current date.
                      If None, defaults to a fixed date for testing.

    Returns:
        The age in years as an integer, or None if birthdate is in the future.
    """
    if current_date is None:
        current_date = datetime.date(2023, 10, 26)

    if birthdate > current_date:
        return None

    age: int | None = current_date.year - birthdate.year
    if current_date.month < birthdate.month or \
       (current_date.month == birthdate.month and current_date.day < birthdate.day):
        if age is not None:
            age -= 1
    return age

def get_birthdate_from_input(year: int | None, month: int | None, day: int | None) -> datetime.date | None:
    """Helper to create a birthdate from input."""
    if year is None or month is None or day is None:
        return None
    try:
        return datetime.date(year, month, day)
    except ValueError:
        return None

if __name__ == "__main__":
    test_date1: datetime.date | None = get_birthdate_from_input(1990, 1, 1)
    if test_date1:
        age1: int | None = calculate_age(test_date1)
        print(f"Age for {test_date1}: {age1}")

    test_date2: datetime.date | None = get_birthdate_from_input(2000, 11, 15)
    if test_date2:
        age2: int | None = calculate_age(test_date2)
        print(f"Age for {test_date2}: {age2}")

    test_date3: datetime.date | None = get_birthdate_from_input(2024, 1, 1)
    if test_date3:
        age3: int | None = calculate_age(test_date3, datetime.date(2023, 10, 26))
        print(f"Age for {test_date3}: {age3}")

