from __future__ import annotations


def clean_rating(value: object) -> float | None:
    """Convert a raw rating into a float, or None if it is not usable."""
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        try:
            return float(text)
        except ValueError:
            return None
    return None


def average_of(ratings: list[object]) -> float:
    """Average of the usable ratings in a list; 0.0 when there are none."""
    usable: list[float] = []
    for raw in ratings:
        score = clean_rating(raw)
        if score is not None:
            usable.append(score)
    if not usable:
        return 0.0
    return sum(usable) / len(usable)


def get_average_movie_rating(movie_ratings: dict) -> dict:
    """Map each movie title to the average of its ratings (0.0 if none)."""
    return {title: average_of(list(ratings)) for title, ratings in movie_ratings.items()}


def best_movie(averages: dict) -> str | None:
    """Title with the highest average, or None for an empty collection."""
    winner: str | None = None
    for title, avg in averages.items():
        if winner is None or avg > averages[winner]:
            winner = title
    return winner


def parse_ratings_line(line: str) -> tuple[str, list[str]] | None:
    """Parse 'Title: 5, 4, 5' into a title and its raw rating tokens."""
    if ":" not in line:
        return None
    title, _, tail = line.partition(":")
    title = title.strip()
    if not title:
        return None
    tokens = [chunk.strip() for chunk in tail.split(",") if chunk.strip()]
    return title, tokens


def load_ratings(text: str) -> dict:
    """Build a ratings dictionary from a block of 'Title: ratings' lines."""
    table: dict = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        parsed = parse_ratings_line(line)
        if parsed is None:
            continue
        title, tokens = parsed
        table.setdefault(title, []).extend(tokens)
    return table


def format_line(title: str, average: float, rank: int | None) -> str:
    """Render one report row; rank is None when the movie has no ratings."""
    marker = "  -" if rank is None else f"{rank:3d}"
    return f"{marker} {title:<12} {average:.2f}"


def build_report(averages: dict) -> str:
    ordered = sorted(averages.items(), key=lambda item: (-item[1], item[0]))
    lines: list[str] = []
    position = 0
    for title, average in ordered:
        rank: int | None = None
        if average > 0.0:
            position += 1
            rank = position
        lines.append(format_line(title, average, rank))
    top = best_movie(averages)
    if top is not None:
        lines.append(f"Top rated: {top} ({averages[top]:.2f})")
    return "\n".join(lines)


def main() -> None:
    raw = """
    Movie A: 5, 4, 5
    Movie B: 3, 2
    Movie C:
    Movie D: 10
    """
    ratings = load_ratings(raw)
    averages = get_average_movie_rating(ratings)
    print(averages)
    print(build_report(averages))


if __name__ == "__main__":
    main()

