def normalize_tokens(raw: str | None) -> list[str]:
    """Split a raw name into whitespace-free tokens, tolerating a missing value."""
    if raw is None:
        return []
    return raw.split()


def initial_of(word: str) -> str | None:
    """Return the uppercase first letter of a word, or None if it has no letters."""
    for ch in word:
        if ch.isalpha():
            return ch.upper()
    return None


def generate_initials(full_name: str | None) -> str:
    """Build dotted uppercase initials from a full name."""
    letters = []
    for token in normalize_tokens(full_name):
        letter = initial_of(token)
        if letter is not None:
            letters.append(letter)
    return "".join(letter + "." for letter in letters)


def parse_age(
    text: str | None,
) -> int | None:
    """Interpret a textual age, returning None when it is absent or malformed."""
    if text is None:
        return None
    cleaned = text.strip()
    if not cleaned.isdigit():
        return None
    return int(cleaned)


def parse_record(line: str) -> tuple[str, int | None]:
    """Parse a 'name, age' line; the age part is optional."""
    name, separator, age_part = line.partition(",")
    return name, parse_age(age_part if separator else None)


def format_row(full_name: str, age: int | None) -> str:
    initials = generate_initials(full_name)
    display = initials if initials else "(none)"
    age_text = str(age) if age is not None else "?"
    return f"{display:<10} {age_text:>3}  {' '.join(normalize_tokens(full_name))}"


def find_by_initials(
    records: list[tuple[str, int | None]],
    target: str,
) -> int | None:
    """Return the index of the first record whose initials match, else None."""
    wanted = target.upper()
    for index, (full_name, _age) in enumerate(records):
        if generate_initials(full_name) == wanted:
            return index
    return None


def main() -> None:
    lines = [
        "John Doe, 42",
        "   Alice   Wonderland  , 31",
        "mary-jane o'neill",
        ", 19",
        "Pablo Diego Ruiz Picasso, twenty",
    ]
    records = [parse_record(line) for line in lines]
    print(f"{'INITIALS':<10} {'AGE':>3}  NAME")
    for full_name, age in records:
        print(format_row(full_name, age))

    for query in ("A.W.", "X.Y."):
        position = find_by_initials(records, query)
        if position is None:
            print(f"{query}: no match")
        else:
            matched_name, matched_age = records[position]
            known_age = matched_age if matched_age is not None else "unknown"
            print(f"{query}: row {position} -> {matched_name.strip()} (age {known_age})")


if __name__ == "__main__":
    main()

